export const ENTRIES = [{"id":"white_tailed_deer","title":"White-tailed deer","domain":"animals","also":["whitetail","white-tail deer","deer","buck","doe"],"def":"The white-tailed deer is the common deer of the East, brown with a white belly and a tail it raises like a white flag when alarmed.","look":["brown coat, white underside, tail raised like a white flag","bucks carry antlers from late summer to winter"],"use":"Deer are the main big-game animal in New England; check your state's season and tag rules before hunting.","not":"Do not approach a fawn lying alone; the doe is usually nearby. Watch for deer on roads at dawn and dusk.","src":["fws","state-regs-link"],"ask":"Tell me about white-tailed deer"},{"id":"moose","title":"Moose","domain":"animals","also":["Alces","bull moose","cow moose"],"def":"The moose is the largest deer, with a long face, a hanging dewlap, and broad flat antlers on bulls.","look":["huge with a long face, dewlap, and broad flat antlers on bulls","dark body on long pale legs"],"use":"Watch from at least 50 yards (about 45 m). If one lays its ears back or raises its hackles, back away and put a tree between you.","not":"Do not approach a cow with a calf or a bull in fall rut. Moose cause serious crashes at night on Maine roads.","src":["nps","fws"],"ask":"Tell me about moose"},{"id":"elk","title":"Elk","domain":"animals","also":["wapiti","Cervus canadensis","bull elk"],"def":"The elk is a large deer with a pale rump, a dark neck, and branching antlers on bulls.","look":["large with a pale rump and branching antlers","bugling calls in fall"],"use":"Elk are rare in New England; a big brown deer there is more likely a moose or white-tailed deer.","not":"Do not approach; bulls in rut and cows with calves charge.","src":["nps","fws"],"ask":"Tell me about elk"},{"id":"black_bear","title":"Black bear","domain":"animals","also":["bear","American black bear","Ursus americanus"],"def":"The black bear is the only bear in the East, black or brown, with a straight face profile and no shoulder hump.","look":["black or brown with a straight muzzle and no shoulder hump","tall pointed ears","short curved claws"],"use":"Make noise on the trail, store food and trash away from camp, and if you meet one, stand tall, talk firmly, and back away slowly.","not":"Never run or climb a tree to escape. If a black bear attacks, fight back. Keep distance, never run, store food away from camp.","src":["nps","fws"],"ask":"Tell me about black bear"},{"id":"coyote","title":"Coyote","domain":"animals","also":["eastern coyote","coywolf","Canis latrans","brush wolf"],"def":"The eastern coyote is a slim, dog-like wild canine with a bushy tail carried low and pointed ears.","look":["slim dog-like with a bushy low tail and pointed ears","yips and howls at night"],"use":"If one comes close, make yourself big, shout, and throw something toward it.","not":"Do not run, and do not leave food or pet food outside.","alike":["Red fox: Red coat, black legs, white tail tip"],"rel":["red_fox"],"src":["fws","nps"],"ask":"Tell me about coyote"},{"id":"red_fox","title":"Red fox","domain":"animals","also":["fox","Vulpes vulpes"],"def":"The red fox is a small wild canine with a red coat, black legs, and a white tail tip.","look":["red coat, black legs, white tail tip","bushy tail longer than half its body"],"use":"Watch from a distance; foxes are usually shy.","not":"A fox that is bold, stumbling, or aggressive may have rabies; leave it and report it.","alike":["Coyote: Slim dog-like with a bushy low tail and pointed ears"],"rel":["coyote"],"src":["cdc","fws"],"ask":"Tell me about red fox"},{"id":"bobcat","title":"Bobcat","domain":"animals","also":["wildcat","Lynx rufus","bay lynx"],"def":"The bobcat is a medium wild cat with a short bobbed tail, tufted ears, and a spotted coat.","look":["short tail with a black tip, tufted ears, spotted coat","tail tip black on top, white below"],"use":"Bobcats avoid people; enjoy the sighting from where you are.","not":"Do not corner one, and treat a bold, unafraid bobcat as possibly rabid.","src":["fws","cdc"],"ask":"Tell me about bobcat"},{"id":"porcupine","title":"Porcupine","domain":"animals","also":["porky","Erethizon dorsatum","quill pig"],"def":"The porcupine is a slow, round rodent covered in barbed quills.","look":["round quill-covered body, slow waddle","chewed bark high on trees"],"use":"Leave it alone and keep dogs away. A pet with quills needs a vet.","not":"It cannot throw quills, but it will swing its tail. Do not pull quills with bare fingers. Quills cannot be thrown. Keep dogs away.","src":["nps","fws"],"ask":"Tell me about porcupine"},{"id":"raccoon","title":"Raccoon","domain":"animals","also":["coon","Procyon lotor","trash panda"],"def":"The raccoon is a gray, masked, ring-tailed animal that raids camps and trash at night.","look":["black mask and ringed tail","handprint-like tracks near water"],"use":"Lock food away at night and keep a clean camp.","not":"A raccoon active in daylight, stumbling or unafraid may have rabies; leave it and report it.","src":["cdc","nps"],"ask":"Tell me about raccoon"},{"id":"striped_skunk","title":"Striped skunk","domain":"animals","also":["skunk","Mephitis"],"def":"The striped skunk is a black animal with white stripes down its back that sprays a strong musk when threatened.","look":["black with white stripes down the back","stamps its feet and raises its tail before spraying"],"use":"Back away slowly if it stamps or turns.","not":"A skunk out in daylight acting oddly may have rabies.","src":["cdc","nps"],"ask":"Tell me about striped skunk"},{"id":"beaver","title":"Beaver","domain":"animals","also":["American beaver","Castor canadensis"],"def":"The beaver is a large water rodent with a flat paddle tail that builds dams and lodges.","look":["flat paddle tail, dam and cut sapling stumps","tooth-chewed pointed stumps near water"],"use":"Beaver ponds flood trails and make routes longer; plan around them.","not":"Treat water near beaver ponds before drinking; it often carries Giardia (\"beaver fever\").","src":["cdc","fws"],"ask":"Tell me about beaver"},{"id":"snowshoe_hare","title":"Snowshoe hare","domain":"animals","also":["varying hare","Lepus americanus","snowshoe rabbit"],"def":"The snowshoe hare is a northern hare with huge furry hind feet whose coat turns white in winter.","look":["large back feet, coat white in winter and brown in summer","brown in summer, white in winter"],"use":"Hares are legal small game in many states; check your state's rules.","not":"Wear gloves when cleaning any rabbit or hare and cook it through, because of tularemia.","src":["cdc","state-regs-link"],"ask":"Tell me about snowshoe hare"},{"id":"wild_turkey","title":"Wild turkey","domain":"animals","also":["turkey","Meleagris gallopavo","gobbler","tom turkey"],"def":"The wild turkey is a large dark bird with a bare red-blue head and a fanned tail.","look":["large dark bird with a bare head and fanned tail","toms gobble in spring"],"use":"Turkey season has its own rules; identify the bird and what is beyond it before every shot.","not":"Do not wear red, white, or blue in spring turkey woods; those are a gobbler's colors.","src":["fws","state-regs-link"],"ask":"Tell me about wild turkey"},{"id":"ruffed_grouse","title":"Ruffed grouse","domain":"animals","also":["partridge","Bonasa umbellus","grouse","pa'tridge"],"def":"The ruffed grouse is a brown or gray barred woodland bird with a fan tail and a dark neck ruff.","look":["brown barred bird with a fan tail and dark neck ruff","drumming sound like a starting engine in spring"],"use":"Grouse are upland game in New England; check season rules.","not":"Cook game birds through.","src":["fws","state-regs-link"],"ask":"Tell me about ruffed grouse"},{"id":"bald_eagle","title":"Bald eagle","domain":"animals","also":["eagle","Haliaeetus leucocephalus","American eagle"],"def":"The bald eagle is a large raptor whose adults have a white head and tail and a yellow bill.","look":["large dark bird with a white head and tail on adults","young birds are mottled brown for four years"],"use":"Watch and photograph from a distance, especially near nests.","not":"Bald eagles and their feathers are protected by federal law; do not disturb, collect, or harm them.","src":["fws"],"ask":"Tell me about bald eagle"},{"id":"great_horned_owl","title":"Great horned owl","domain":"animals","also":["hoot owl","Bubo virginianus","cat owl"],"def":"The great horned owl is a large owl with ear tufts, yellow eyes, and a deep hooting call.","look":["large owl with ear tufts and yellow eyes","white throat patch"],"use":"Enjoy it from a distance, especially near nests in late winter.","not":"Owls are federally protected; do not disturb, collect, or harm them.","src":["fws"],"ask":"Tell me about great horned owl"},{"id":"canada_goose","title":"Canada goose","domain":"animals","also":["honker","Branta canadensis","goose"],"def":"The Canada goose is a large goose with a black neck and head and a white chin strap.","look":["black neck and head with a white chin strap","V-shaped flocks with loud honking"],"use":"Geese are migratory birds with federal and state season rules; check both.","not":"Geese defend nests and goslings by charging; give them room.","src":["fws","state-regs-link"],"ask":"Tell me about canada goose"},{"id":"rattlesnake","title":"Rattlesnake","domain":"animals","also":["timber rattlesnake","rattler","Crotalus horridus"],"def":"The timber rattlesnake is a heavy-bodied venomous snake with a broad triangular head and a rattle on its tail.","look":["thick body, triangular head, a rattle on the tail","dark crossbands on a yellow or dark body"],"use":"Rattlesnakes are rare and protected in much of New England. Back away slowly and walk around.","not":"Do not handle, kill, or pin it. After a bite, call 911, keep the person still and calm, and do not cut, suck, or tourniquet the bite. Venomous. Back away slowly. Call emergency services after a bite.","alike":["Garter snake: Slim, three pale stripes along the body","Northern water snake: Banded brown snake near water. Not venomous but it bites hard. Often mistaken for a copperhead"],"call":"Call 911 for trouble breathing, swelling of the face or throat, or a venomous bite; see a clinician for fever or rash after a tick bite.","rel":["eastern_garter_snake","northern_water_snake"],"src":["cdc","nps"],"ask":"Tell me about rattlesnake"},{"id":"copperhead","title":"Copperhead","domain":"animals","also":["Agkistrodon contortrix","highland moccasin"],"def":"The copperhead is a venomous snake with a copper-colored head and tan hourglass bands.","look":["copper head, tan body with hourglass bands","bands narrow on the back and wide on the sides"],"use":"Copperheads live in southern New England's rocky woods. Back away slowly.","not":"Do not handle it. After a bite, call 911, keep still, and do not cut, suck, or ice the bite. Venomous. Back away slowly. Call emergency services after a bite.","alike":["Northern water snake: Banded brown snake near water. Not venomous but it bites hard. Often mistaken for a copperhead"],"call":"Call 911 for trouble breathing, swelling of the face or throat, or a venomous bite; see a clinician for fever or rash after a tick bite.","rel":["northern_water_snake"],"src":["cdc","nps"],"ask":"Tell me about copperhead"},{"id":"cottonmouth","title":"Cottonmouth","domain":"animals","also":["water moccasin","Agkistrodon piscivorus"],"def":"The cottonmouth is a heavy, dark venomous water snake that gapes to show a white mouth.","look":["heavy dark water snake with a white mouth when it gapes","swims with its body high on the water"],"use":"Cottonmouths do not live in New England; a dark snake in water there is almost always a northern water snake.","not":"Do not handle any snake you cannot identify. After a bite, call 911 and keep still. Venomous. Back away slowly. Call emergency services after a bite.","alike":["Northern water snake: Banded brown snake near water. Not venomous but it bites hard. Often mistaken for a copperhead"],"call":"Call 911 for trouble breathing, swelling of the face or throat, or a venomous bite; see a clinician for fever or rash after a tick bite.","rel":["northern_water_snake"],"src":["cdc","nps"],"ask":"Tell me about cottonmouth"},{"id":"eastern_garter_snake","title":"Garter snake","domain":"animals","also":["garter snake","garden snake","Thamnophis sirtalis"],"def":"The eastern garter snake is a slim, harmless snake with three pale stripes along its body.","look":["slim, three pale stripes along the body","often basks on paths and rocks"],"use":"It is harmless; let it go on its way.","not":"Do not grab it; it may bite and release musk.","alike":["Rattlesnake: Thick body, triangular head, a rattle on the tail. Venomous. Back away slowly. Call emergency services after a bite"],"call":"Call 911 for trouble breathing, swelling of the face or throat, or a venomous bite; see a clinician for fever or rash after a tick bite.","rel":["rattlesnake"],"src":["nps"],"ask":"Tell me about garter snake"},{"id":"northern_water_snake","title":"Northern water snake","domain":"animals","also":["water snake","Nerodia sipedon"],"def":"The northern water snake is a common, non-venomous banded brown snake found in and near water.","look":["banded brown snake near water","round pupils"],"use":"It is not venomous; give it room.","not":"It bites hard if handled, and it is often mistaken for a copperhead or cottonmouth. Not venomous but it bites hard. Often mistaken for a copperhead.","alike":["Copperhead: Copper head, tan body with hourglass bands. Venomous. Back away slowly. Call emergency services after a bite","Cottonmouth: Heavy dark water snake with a white mouth when it gapes. Venomous. Back away slowly. Call emergency services after a bite"],"call":"Call 911 for trouble breathing, swelling of the face or throat, or a venomous bite; see a clinician for fever or rash after a tick bite.","rel":["copperhead","cottonmouth"],"src":["nps"],"ask":"Tell me about northern water snake"},{"id":"blacklegged_tick","title":"Blacklegged (deer) tick","domain":"animals","also":["deer tick","Ixodes scapularis","Lyme tick"],"def":"The blacklegged tick, or deer tick, is a tiny dark tick that spreads Lyme disease, anaplasmosis, and babesiosis.","look":["tiny dark tick","adult females have an orange-red body and black plate","nymphs are the size of a poppy seed"],"use":"Check your whole body after time outside, and remove ticks with fine tweezers pulled straight out.","not":"Do not twist, burn, or smother a tick. See a clinician for a spreading rash or fever after a bite. Carries Lyme and other diseases. Remove with tweezers close to the skin and keep the date.","alike":["American dog tick: Larger brown tick with white-cream markings on the back. Can carry spotted fever. Remove with tweezers close to the skin"],"call":"Call 911 for trouble breathing, swelling of the face or throat, or a venomous bite; see a clinician for fever or rash after a tick bite.","rel":["american_dog_tick"],"src":["cdc"],"ask":"Tell me about blacklegged tick"},{"id":"american_dog_tick","title":"American dog tick","domain":"animals","also":["dog tick","wood tick","Dermacentor variabilis"],"def":"The American dog tick is a larger brown tick with cream markings that can carry Rocky Mountain spotted fever.","look":["larger brown tick with white-cream markings on the back","common in grassy fields and trail edges"],"use":"Remove it with fine tweezers close to the skin and wash the bite.","not":"See a clinician for fever, rash, or headache in the two weeks after a bite. Can carry spotted fever. Remove with tweezers close to the skin.","alike":["Blacklegged (deer) tick: Tiny dark tick; adult females have an orange-red body and black plate. Carries Lyme and other diseases. Remove with tweezers close to the skin and keep the date"],"call":"Call 911 for trouble breathing, swelling of the face or throat, or a venomous bite; see a clinician for fever or rash after a tick bite.","rel":["blacklegged_tick"],"src":["cdc"],"ask":"Tell me about american dog tick"},{"id":"lone_star_tick","title":"Lone star tick","domain":"animals","also":["Amblyomma americanum","turkey tick"],"def":"The lone star tick is a reddish-brown tick whose females have one white dot on the back; its bites are linked to a red-meat allergy.","look":["reddish-brown tick with one white dot on the back of females","aggressive biter, spreading north"],"use":"Remove it with fine tweezers close to the skin.","not":"See a clinician for fever or rash after a bite, or hives hours after eating red meat. Bites can cause meat allergy. Remove with tweezers close to the skin.","call":"Call 911 for trouble breathing, swelling of the face or throat, or a venomous bite; see a clinician for fever or rash after a tick bite.","src":["cdc"],"ask":"Tell me about lone star tick"},{"id":"black_widow","title":"Black widow","domain":"animals","also":["widow spider","Latrodectus"],"def":"The black widow is a shiny black spider with a red hourglass under its belly whose bite needs medical care.","look":["shiny black spider with a red hourglass underneath","messy webs under rocks, logs, and outhouse seats"],"use":"Shake out gloves, boots, and firewood before use.","not":"After a bite, clean it, apply a cool pack, and get medical care, especially for cramps or trouble breathing. Venomous. Seek care after a bite.","call":"Call 911 for trouble breathing, swelling of the face or throat, or a venomous bite; see a clinician for fever or rash after a tick bite.","src":["cdc"],"ask":"Tell me about black widow"},{"id":"bald_faced_hornet","title":"Bald-faced hornet","domain":"animals","also":["white-faced hornet","Dolichovespula maculata"],"def":"The bald-faced hornet is a black-and-white wasp that builds a gray paper nest in trees and defends it fiercely.","look":["black and white wasp with a grey paper nest the size of a football","nests hang from branches or eaves"],"use":"Walk wide around nests.","not":"Call 911 for swelling of the face or throat, or trouble breathing after a sting. Stings hurt and are dangerous if allergic.","call":"Call 911 for trouble breathing, swelling of the face or throat, or a venomous bite; see a clinician for fever or rash after a tick bite.","src":["cdc"],"ask":"Tell me about bald-faced hornet"},{"id":"yellowjacket","title":"Yellowjacket","domain":"animals","also":["yellow jacket","ground wasp","Vespula"],"def":"The yellowjacket is a black-and-yellow wasp that nests in the ground and stings repeatedly.","look":["black and yellow wasp that nests underground","busy hole in the ground"],"use":"Watch for ground nests when clearing a camp or trail.","not":"Call 911 for swelling of the face or throat, or trouble breathing after a sting. Stings hurt and are dangerous if allergic.","call":"Call 911 for trouble breathing, swelling of the face or throat, or a venomous bite; see a clinician for fever or rash after a tick bite.","src":["cdc"],"ask":"Tell me about yellowjacket"},{"id":"wild_boar","title":"Wild boar (feral hog)","domain":"animals","also":["feral hog","feral pig","wild pig","Sus scrofa"],"def":"The wild boar, or feral hog, is a dark bristly pig with a long snout that can be aggressive.","look":["dark bristly pig with a long snout","rooted-up ground"],"use":"Feral hogs are not established in New England; report one to your state wildlife agency.","not":"Cook the meat fully, and wear gloves when cleaning; hogs can carry brucellosis. Can be aggressive. Cook the meat fully.","src":["cdc","state-regs-link"],"ask":"Tell me about wild boar"},{"id":"family_emergency_plan","title":"Family emergency plan and meeting points","domain":"family","also":["family plan","where do we meet","meeting place","family emergency card"],"def":"A family emergency plan says how you will reach each other, where you will meet near home and out of the neighborhood, and who an out-of-area contact is.","look":["a meeting spot near home and one farther away","an out-of-area contact everyone knows","phone numbers written on paper"],"use":"Write the plan down, give every family member a card, and practice it twice a year.","not":"Do not rely only on phones; networks fail in disasters.","rel":["child_lost_woods","child_calls_emergency"],"src":["ready"]},{"id":"child_lost_woods","title":"What to teach a child about being lost in the woods","domain":"family","also":["kid lost in woods","hug a tree","child lost hiking","teach kids if lost"],"def":"A child who is lost should stay in one place, hug a tree, make noise, and answer when called; searchers find children who stay put far faster.","look":["a whistle on the child's jacket","bright clothing","the child knows nobody will be angry"],"use":"Teach: stop, hug a tree, blow the whistle three times, stay put, and answer anyone calling your name. Practice it as a game.","not":"Do not teach a child to keep walking to find the way, and do not scold them when found.","call":"If a child is missing outdoors, call 911 right away; do not wait.","rel":["family_emergency_plan"],"src":["nps","ready"]},{"id":"child_calls_emergency","title":"How a child calls 911","domain":"family","also":["teach kids to call 911","child emergency call","what to say to 911"],"def":"Children can call 911 from any phone, even a locked one, and should say what happened, where they are, and stay on the line.","look":["how to reach emergency call on your phone's lock screen","the child knows their address","a calm practice run with a turned-off phone"],"use":"Teach your address, how to place an emergency call on a locked phone, and to answer the dispatcher's questions and stay on the line.","not":"Do not let children practice on a live line, and do not teach them to hang up if they make a mistake; they should stay and explain.","rel":["family_emergency_plan"],"src":["ready","fema"]},{"id":"child_cold_infant","title":"Keeping children warm and spotting cold stress in infants","domain":"family","also":["baby hypothermia","infant cold","keeping kids warm","child too cold"],"def":"Children lose heat faster than adults; an infant with hypothermia can have bright red, cold skin and very low energy.","look":["bright red, cold skin in a baby","a quiet, floppy, or very sleepy child","shivering, clumsy hands, or slurred speech in an older child"],"use":"Dress children in one more layer than adults, cover the head, change wet clothes at once, and warm a cold child against your body in a dry blanket.","not":"Do not use hot water bottles or heaters directly on a child's skin.","call":"Call 911 for an infant with cold, red skin and low energy, or any child who is confused or unresponsive.","rel":["clothing_layers_wet"],"src":["cdc"]},{"id":"child_dehydration_fever","title":"Dehydration and fever in a child","domain":"family","also":["child dehydrated","kid fever","baby dehydration signs","when to take child to doctor"],"def":"Children dehydrate quickly with vomiting, diarrhea, heat, or fever; a dry mouth, few wet diapers, no tears, and unusual sleepiness are warning signs.","look":["fewer wet diapers or no urine for many hours","no tears when crying, a dry mouth, sunken eyes","fever with a stiff neck, rash, or trouble breathing"],"use":"Give small, frequent sips of fluid or oral rehydration solution, keep the child cool, and watch urine and alertness.","not":"Do not give aspirin to children, and do not give plain water alone to an infant under six months for dehydration; ask a clinician.","call":"Call a doctor for an infant under 3 months with any fever. Call 911 for a child who is very sleepy, hard to wake, or breathing hard.","rel":["child_cold_infant"],"src":["cdc","nih-medline"]},{"id":"kids_prevention_rules","title":"Kids outdoors: ticks, poison ivy, water, and firearms","domain":"family","also":["kids safety outdoors","children and guns","kids near water","kids ticks"],"def":"A few short rules prevent most outdoor harm to children: check for ticks, avoid leaves of three, stay within reach near water, and never touch a gun.","look":["a tick check after every outing","a life jacket on near water","guns stored locked and unloaded"],"use":"Teach: if you see a gun, don't touch, leave, tell an adult. Keep children within arm's reach near water and do a full tick check at night.","not":"Do not leave children alone near water, even for a moment, or store firearms where a child can reach them.","rel":["family_emergency_plan"],"src":["cdc","ready"]},{"id":"infant_formula_unsafe_water","title":"Infant formula when the water is unsafe","domain":"family","also":["baby formula water","boil water notice baby","formula during outage"],"def":"When tap water is unsafe, infant formula should be ready-to-feed, or mixed with bottled water or water that was boiled and cooled.","look":["a boil-water notice","flooding near the well","no power to boil water"],"use":"Use ready-to-feed formula when you can; otherwise use bottled water or water brought to a rolling boil for one minute and cooled. Clean bottles in safe water.","not":"Do not use water from a flooded well or treated only with a filter for an infant without checking with your health department.","rel":[],"src":["cdc","epa"]},{"id":"child_in_vehicle","title":"A child left in a vehicle is an emergency","domain":"family","also":["child left in car","kid in hot car","baby in car heat"],"def":"A closed car heats up fast even on a mild day and can kill a child within minutes; in winter, a running car can fill with exhaust.","look":["a child alone in a car","a sweaty, red, or unresponsive child","a running car with snow blocking the tailpipe"],"use":"If you see a child alone in a hot car, call 911 at once and follow the dispatcher's directions. Make a habit of checking the back seat every time you leave the car.","not":"Do not leave a child in a car for any time, even with the windows cracked or the engine running.","call":"Call 911 immediately.","rel":["kids_prevention_rules"],"src":["nhtsa","ready"]},{"id":"pet_kit_evacuation","title":"Pet kit, pet evacuation, and pet poisoning","domain":"family","also":["pet emergency kit","evacuate with pets","dog ate something toxic","pet poison"],"def":"Pets need their own emergency kit and a plan for where they can stay, because many shelters only take service animals.","look":["food, water, medicines, leash, carrier, and records","a list of pet-friendly hotels or friends","an ID tag and microchip"],"use":"Pack a pet kit, plan pet-friendly places to stay, and take pets with you if you evacuate.","not":"Do not guess about a pet poisoning; call your veterinarian or an animal poison line.","call":"Call your veterinarian or an animal poison control line for any suspected pet poisoning.","rel":["kit_72_hour"],"src":["ready"]},{"id":"talk_kids_emergency","title":"Talking to children during an emergency","domain":"family","also":["kids scared storm","calm a child","explain disaster to kids","child anxiety emergency"],"def":"Children take their cue from adults; calm, simple, honest words and a job to do help them feel safer.","look":["a child clinging, crying, or very quiet","questions repeated many times","trouble sleeping after the event"],"use":"Get down to their level, say what is happening in a few words, tell them what you are doing to keep them safe, and give them a small task.","not":"Do not share frightening details or let them watch hours of disaster coverage.","rel":["after_hard_event_kids","family_emergency_plan"],"src":["ready","samhsa"]},{"id":"reunification_after_disaster","title":"Reuniting a family after a storm or evacuation","domain":"family","also":["find family after disaster","separated from family","reunification"],"def":"After a disaster, families reunite fastest when everyone knows the meeting places and the out-of-area contact ahead of time.","look":["the planned meeting spot","an out-of-area contact who relays messages","official reunification or shelter registries"],"use":"Go to the planned meeting place, text the out-of-area contact, and register with official shelters or reunification services.","not":"Do not return to a damaged or evacuated area to search until officials say it is safe.","rel":["family_emergency_plan"],"src":["ready","fema"]},{"id":"school_pickup_plan","title":"School or daycare pickup when phones or roads fail","domain":"family","also":["school emergency pickup","who picks up the kids","school lockdown parent"],"def":"A pickup plan names who can collect each child, how the school will reach you, and what happens if roads or phones are down.","look":["the school's emergency and release policy","backup adults on the authorized pickup list","the school's alert sign-up"],"use":"Learn the school's plan, add backup adults to the pickup list, and tell children who may collect them.","not":"Do not rush to a school in lockdown; follow official instructions about where to reunite.","rel":["family_emergency_plan","reunification_after_disaster"],"src":["ready"]},{"id":"child_carrier_trail","title":"Child carriers and trail safety with little ones","domain":"family","also":["hiking with a baby","child carrier backpack","toddler on trail"],"def":"Hiking with a baby or toddler needs a carrier that fits both of you, extra warmth and sun protection for the child, and short, flexible plans.","look":["the child's face, hands, and feet staying warm or shaded","the carrier's weight limit","secure footing on descents"],"use":"Check the child often, dress them warmer than you since they are not moving, take breaks, and avoid steep or icy ground.","not":"Do not hike exposed ridges or icy trails with a child on your back.","rel":["child_cold_infant"],"src":["nps","cdc"]},{"id":"shared_kit_meds","title":"Shared kit: who carries the meds and the inhaler","domain":"family","also":["who carries epipen","family medicines trip","inhaler on hike"],"def":"In a group, life-saving medicines such as an epinephrine auto-injector or an inhaler must stay with the person who needs them, with a backup someone else knows about.","look":["an epinephrine auto-injector with the allergic person","a spare inhaler with another adult","a list of medicines and doses"],"use":"Decide before leaving who carries what, show others where it is, and keep medicines protected from heat and freezing.","not":"Do not pack someone's emergency medicine in a car or another person's bag that may not be nearby.","call":"Use epinephrine as prescribed for a severe allergic reaction and call 911.","rel":["first_aid_kit_contents"],"src":["cdc","fda"]},{"id":"pets_outage_weather","title":"Pets in a power outage, heat, or cold","domain":"family","also":["dog in heat","pets cold weather","pets during outage"],"def":"Pets suffer in heat and cold like people do; during an outage they need shade or warmth, water, and their food and medicines.","look":["heavy panting, drooling, or weakness in heat","shivering or lethargy in cold","spoiled pet food after an outage"],"use":"Keep pets indoors with you, give plenty of water, never leave them in a parked car, and bring them when you go to a warming or cooling center that accepts pets.","not":"Do not leave pets tied outside in a storm or extreme weather.","call":"Call your veterinarian for heatstroke or cold injury signs.","rel":["pet_kit_evacuation"],"src":["ready"]},{"id":"after_hard_event_kids","title":"Helping children after a hard event","domain":"family","also":["kid saw something scary","child grief","explaining death to child","child after hunting harvest"],"def":"After a close call, a death, or seeing an animal harvested, children need brief, age-appropriate words, honest answers, and permission to have feelings.","look":["questions, drawings, or play about the event","clinginess or nightmares","a return to normal play over days"],"use":"Answer simply and honestly, keep routines, and let them talk or not; tell them it is okay to feel sad or confused.","not":"Do not lecture or force a child to talk.","call":"Ask a pediatrician or counselor if distress lasts more than a few weeks.","rel":["talk_kids_emergency","grief_after_loss"],"src":["samhsa","va-ptsd"]},{"id":"youth_hunts_link","title":"Youth seasons and mentored hunts","domain":"family","also":["youth deer season","kids hunting license","apprentice license"],"def":"Many states have youth days or apprentice licenses with special rules on age, supervision, and hunter education; they change by year.","look":["the state's minimum age and supervision distance","a hunter-education course requirement","special youth season dates"],"use":"Read your state agency's current youth-hunting page and follow its supervision rules.","not":"Do not rely on rules from a past year or another state.","rel":["youth_hunter_mentor"],"src":["state-regs-link","ihea"]},{"id":"teen_crisis_support","title":"Supporting a teenager in crisis","domain":"family","also":["teen depressed","teenager suicidal","help my teen"],"def":"A teenager in crisis needs an adult who listens calmly, takes their words seriously, and connects them with help.","look":["withdrawal, giving things away, or talk of death","sudden changes in sleep, school, or friends","access to guns or medicines"],"use":"Listen without judging, ask directly about suicide if worried, lock up guns and medicines, and call or text 988 together.","not":"Do not promise secrecy about safety or wait for it to pass.","call":"Call or text 988 any time for the Suicide & Crisis Lifeline; veterans can press 1. Call 911 if someone is in immediate danger.","rel":["suicidal_thoughts_help","helping_friend_crisis"],"src":["988","nimh"]},{"id":"emergency_info_card","title":"Emergency contact and medical card","domain":"family","also":["medical info card","emergency contacts on paper","ICE contact"],"def":"A small paper card with emergency contacts, allergies, medicines, and conditions helps responders when a phone is locked or dead.","look":["names and numbers of two contacts","allergies, medicines, and conditions","a copy in wallet, kit, and car"],"use":"Make a card for each family member, update it when medicines change, and add emergency contacts to your phone's lock-screen medical info.","not":"Do not rely on a locked phone alone.","rel":["family_emergency_plan"],"src":["ready"]},{"id":"check_older_relatives","title":"Checking on older relatives and neighbors","domain":"family","also":["check on elderly parent","older neighbor heat","senior in power outage"],"def":"Older adults are at higher risk in heat, cold, and outages, especially if they live alone or rely on medical devices.","look":["no answer by phone during an outage or heat wave","confusion, weakness, or a cold or hot home","medicines or devices that need power"],"use":"Call or visit twice a day during extreme weather or outages, help them reach a cooling or warming center, and make sure they have water and medicines.","not":"Do not assume they are fine because they say so on the phone if the home is very hot or cold.","call":"Call 911 for confusion, collapse, or trouble breathing.","rel":[],"src":["cdc","ready"]},{"id":"kids_water_safety","title":"Children and water","domain":"family","also":["kids drowning","child near pond","life jacket kids","swimming safety kids"],"def":"Drowning is quick and silent; children need a watcher whose eyes stay on them and a life jacket near open water.","look":["a designated adult watcher with no phone","a properly fitted life jacket","cold or moving water"],"use":"Name one adult watcher at a time, keep young children within arm's reach, and use life jackets on boats and near rivers and ponds.","not":"Do not rely on floaties or assume a child will splash or shout if in trouble.","call":"Call 911 for any child pulled from water, even if they seem fine.","rel":["kids_prevention_rules"],"src":["cdc"]},{"id":"fire_site_choice","title":"Choosing a fire site","domain":"fire","also":["where to build a fire","fire ring","keep a fire from spreading","fire pit"],"def":"A safe fire site is on bare mineral soil, clear of overhanging branches, dry grass, and roots, and downwind from your shelter.","look":["bare soil or sand, or an existing ring","a cleared circle about 10 feet (3 m) wide","water nearby to put it out"],"use":"Scrape away leaves and duff to bare soil, build a ring of rocks, keep water or a shovel at hand, and keep it small. Check local rules first.","not":"Do not build under low branches, on peat or roots, or on dry grass in wind.","rel":["fire_legal_ban","fire_out_completely"],"src":["usfs","nps","atp3-50-21"]},{"id":"fire_tinder_kindling_fuel","title":"Tinder, kindling, and fuel","domain":"fire","also":["what is tinder","what burns best","fire materials","birch bark","fatwood"],"def":"Tinder is fine dry material that catches a spark, kindling is pencil-sized sticks that carry the flame, and fuel is the larger wood that burns for hours.","look":["tinder: birch bark, fatwood shavings, dry grass, cattail fluff, cotton with petroleum jelly","kindling: dry twigs from pencil lead to thumb thick","fuel: wrist-thick and larger dead dry wood"],"use":"Gather three piles before you light: a double handful of tinder, twice as much kindling, and plenty of fuel. Use dead, standing, dry wood, which snaps when it is dry.","not":"Do not use damp wood, treated lumber, or trash.","region":"Birch bark and eastern white pine fatwood from dead stumps are classic New England tinder; check the rules on what you may take.","rel":["fire_build_teepee","fire_wet_wood"],"src":["atp3-50-21","usfs"]},{"id":"fire_build_teepee","title":"Building and lighting a basic fire (teepee)","domain":"fire","also":["how to start a campfire","teepee fire lay","start a fire"],"def":"A teepee fire is a cone of kindling leaned over a nest of tinder, lit from the windward side so the flame climbs.","look":["tinder bundle in the center","kindling leaning inward like a tent","fuel stacked nearby"],"use":"Place the tinder bundle, lean kindling around it, leave a gap on the windward side, light the tinder, and add small fuel as it catches. Blow gently at the base and add bigger pieces slowly.","not":"Do not smother the flame with too much fuel too early.","steps":["Clear a bare spot and ring it with rocks.","Place a handful of tinder in the center.","Lean kindling over it in a teepee with an opening to light.","Light the tinder from the upwind side.","Add bigger sticks as the fire grows."],"call":"Keep water nearby and never leave a fire unattended.","rel":["fire_wet_wood","fire_out_completely"],"src":["atp3-50-21","usfs"]},{"id":"fire_wet_wood","title":"Starting a fire in rain or with wet wood","domain":"fire","also":["fire in the rain","wet wood fire","damp tinder","fire in snow"],"def":"In rain, use dry material from under cover: dead branches still on trees, inner bark, and shaved wood, and protect the flame under a tarp.","look":["dead lower branches that snap","split wet logs to reach dry centers","fatwood or a dry starter you carried"],"use":"Look for dry tinder under logs and evergreen boughs, split wood to reach its dry inside, and shave fine curls. Build on a platform of sticks in snow or wet ground and shield the fire from rain.","not":"Do not use wet bark or green wood, and do not light in a closed shelter.","rel":["fire_tinder_kindling_fuel","fire_snow"],"src":["atp3-50-21","usfs"]},{"id":"fire_snow","title":"Starting a fire in snow","domain":"fire","also":["fire on snow","build a platform for a fire"],"def":"A fire in snow needs a platform of green logs or stones so it does not sink and go out.","look":["a platform of green logs, flat rocks, or a layer of sticks","a windbreak","dry tinder you kept inside your jacket"],"use":"Stamp down the snow, lay a log platform, and build the fire on top. Keep dry tinder against your body, and feed it slowly.","not":"Do not build under a snow-laden branch that can fall onto the fire.","rel":["fire_wet_wood","fire_build_teepee"],"src":["atp3-50-21"]},{"id":"fire_out_completely","title":"Putting a fire out completely","domain":"fire","also":["put out the campfire","drown the fire","cold fire","douse"],"def":"A fire is out only when the ashes are cold to the touch; drown it, stir it, and drown it again.","look":["steam or hissing means it is still hot","no glowing embers","back of your hand feels no heat"],"use":"Let the fire burn down, pour water on the embers, stir the ashes and soil with a stick, and add more water until nothing hisses. Feel for heat with the back of your hand.","not":"Do not just bury a hot fire or leave it smoldering, and do not leave until it is cold.","call":"Call 911 if a fire gets away from you.","rel":["fire_site_choice"],"src":["usfs","nps"]},{"id":"stove_vs_open_fire","title":"Camp stove versus open fire","domain":"fire","also":["cook on a stove","charcoal grill indoors","camping stove safety"],"def":"A camp stove is more controlled and leaves less trace than an open fire, but any stove, grill, or charcoal burner must never be used indoors, in a tent, or in a garage.","look":["stoves burn liquid or gas fuel","charcoal makes carbon monoxide","fuel should be stored away from heat"],"use":"Cook outdoors on a stable, flat surface, away from tents and dry grass, and have water handy. Let it cool before refueling.","not":"Do not use a camp stove, grill, or generator in a house, garage, or tent.","call":"Get out into fresh air for headache or dizziness; call 911 for carbon monoxide symptoms.","rel":["carbon_monoxide_poisoning","fuel_in_closed_shelter"],"src":["cpsc","cdc","usfs"]},{"id":"fire_legal_ban","title":"Is a fire legal here? Fire bans and permits","domain":"fire","also":["can I build a fire","burn ban","campfire permit"],"def":"Fire rules vary by state, town, and land, and bans are common in dry or windy weather, so check the official source before you light one.","look":["a burn ban or a red flag warning","state, town, or land-manager rules","a campfire permit requirement"],"use":"Check with the local fire department, the state forest service, or the land manager, and follow any ban. If fires are banned, use a stove only if rules allow.","not":"Do not guess; do not light a fire during a ban.","region":"Check the Maine Forest Service, your state forestry office, and the town for burn permits and bans.","rel":["red_flag_fire_weather","fire_site_choice"],"src":["usfs","nps","state-regs-link"]},{"id":"fire_dont_burn","title":"What not to burn","domain":"fire","also":["toxic smoke","burn poison ivy","treated lumber","trash fire"],"def":"Never burn poison ivy, treated lumber, painted wood, plastic, or trash; the smoke is toxic.","look":["poison ivy smoke carries irritating oil","treated lumber has chemicals","plastics make toxic fumes"],"use":"Burn only clean, dry, untreated wood. Pack out trash.","not":"Do not burn poison ivy, pressure-treated wood, or plastics, and do not breathe the smoke.","call":"Call 911 for trouble breathing after smoke exposure.","rel":["poison_ivy_rash","smoke_inhalation"],"src":["epa","cdc"]},{"id":"fire_smoke_wind","title":"Smoke, wind, and where to sit","domain":"fire","also":["smoke in my face","sit upwind of a fire","smoky fire"],"def":"Smoke drifts downwind, so sit upwind or to the side, and dry wood burns cleaner.","look":["smoke blowing toward your seat","a smoky fire from wet wood","wind shifts"],"use":"Move your seat upwind, burn dry wood, and keep the fire small. If it keeps smoking, stir and add dry fuel.","not":"Do not sit in the smoke or breathe it for long.","rel":["fire_build_teepee","smoke_inhalation"],"src":["usfs","epa"]},{"id":"fire_signal","title":"Signal fire","domain":"fire","also":["fire to be found","smoke signal","three fires"],"def":"A signal fire is a fire built to be seen from a distance, with green boughs for white smoke by day and bright fuel at night.","look":["three fires in a triangle is a distress signal","green leaves make dense smoke","a clearing for visibility"],"use":"Build it on an open spot, keep tinder dry and ready, and light it when an aircraft or searchers are close. Add green boughs for smoke by day.","not":"Do not leave it unattended or start it near dry grass.","rel":["fire_out_completely"],"src":["atp3-50-21","usfs"]},{"id":"fire_lighters_ferro","title":"Ferro rod, matches, and lighters","domain":"fire","also":["how to use a ferro rod","fire steel","waterproof matches","bic lighter"],"def":"A ferrocerium rod throws hot sparks when scraped, and it works wet; matches and lighters are easier but fail when wet or empty.","look":["scrape the rod down with a sharp spine, keeping it close to the tinder","carry two ways to light","a lighter kept dry in a pocket"],"use":"Hold the rod near the tinder and pull the striker backward fast. Carry a lighter, matches in a waterproof case, and a ferro rod as a backup.","not":"Do not rely on one ignition source, and do not use a bow drill until all else fails.","rel":["fire_tinder_kindling_fuel","fire_build_teepee"],"src":["atp3-50-21"]},{"id":"fire_bank_ember","title":"Keeping and moving an ember","domain":"fire","also":["viable ember","char cloth","keep a fire overnight"],"def":"A viable ember is glowing red and spreads when you blow on it; a dead ember is black and cool.","look":["a bright orange glow when blown on","char cloth or punky wood catches a spark","an ember in dry tinder can be blown into flame"],"use":"Place the ember in a nest of fine tinder, fold the tinder around it, and blow gently until it flames. Bank a fire at night with large logs and ash.","not":"Do not leave a fire banked unattended in wind.","rel":["fire_build_teepee"],"src":["atp3-50-21"]},{"id":"wound_cleaning","title":"Cleaning a wound","domain":"firstaid","also":["wash a cut","rinse a scrape","irrigate a wound"],"def":"Cleaning a wound means flushing dirt and germs out with plenty of clean running water after bleeding is under control.","look":["bleeding has stopped or is controlled","visible dirt or grit in the wound","edges you can see clearly"],"use":"Rinse for several minutes with clean water, use mild soap on the skin around it, and lift out loose grit with clean tweezers. Pat dry and cover.","not":"Do not scrub a deep wound, pour in hydrogen peroxide or alcohol, or pack it with plants or soil. Do not clean first if bleeding is heavy; stop the bleeding first.","steps":["Wash your hands or put on gloves.","Control any bleeding with direct pressure first.","Flush with clean, drinkable or boiled-and-cooled water for at least several minutes.","Wash the skin around it with soap, not inside a deep wound.","Dry gently and cover with a clean dressing."],"call":"Get medical care for deep, gaping, dirty, animal-bite or puncture wounds, or wounds that show spreading redness, pus, or fever. Call emergency services for bleeding that will not stop.","rel":["wound_infection_signs","bandaging_basics"],"src":["atp4-02-11","cdc","nih-medline"]},{"id":"wound_infection_signs","title":"Signs a wound is infected","domain":"firstaid","also":["infected cut","cellulitis","pus in a wound","red streaks"],"def":"A wound is likely infected when it gets worse over days instead of better, with growing redness, warmth, swelling, pus, or pain.","look":["redness that spreads outward from the wound","warmth, swelling, and increasing pain after the first day or two","pus or a bad smell","red streaks running toward the body, or fever"],"use":"Keep the wound clean and covered, and get it seen by a clinician the same day if you see these signs. Red streaks, fever, or a fast-spreading red area need urgent care.","not":"Do not squeeze or cut open a swollen wound, and do not rely on plant remedies or leftover antibiotics when you have signs of spreading infection.","call":"Call emergency services or get urgent care for red streaks, fever with chills, confusion, a rapidly spreading red area, or a wound over a joint that is swollen and very painful.","rel":["sepsis_signs","wound_cleaning"],"src":["cdc","nih-medline","atp4-02-11"]},{"id":"sepsis_signs","title":"Sepsis warning signs","domain":"firstaid","also":["blood poisoning","septic","infection spreading through the body"],"def":"Sepsis is the body's dangerous overreaction to an infection, and it can quickly harm organs and cause death if not treated.","look":["fever or shivering, or feeling very cold","fast heartbeat and fast breathing","confusion, sleepiness, or hard to wake","clammy or mottled skin, very low urine, or severe pain"],"use":"Treat it as an emergency in anyone with a known or suspected infection who has these signs. Get to hospital care fast; sepsis needs medical treatment.","not":"Do not wait to see if it passes, and do not treat it at home with food, water, or herbs alone.","call":"Call emergency services right away. Say you are worried about sepsis.","rel":["wound_infection_signs","fever_adult"],"src":["cdc","nih-medline"]},{"id":"bandaging_basics","title":"Bandaging a wound","domain":"firstaid","also":["dressing a wound","wrap a cut","cover a wound","gauze"],"def":"A dressing is the clean pad that sits on the wound, and a bandage is what holds it in place without cutting off blood flow.","look":["clean, non-stick or gauze pad","wrap snug but loose enough for a finger beneath","fingers or toes beyond the wrap stay warm and pink"],"use":"Cover the wound with a clean dressing, wrap over it firmly, and check the fingers or toes beyond it for color, warmth, and feeling every little while.","not":"Do not wrap so tightly that the skin beyond turns pale, blue, cold, or numb. Do not reuse a wet, dirty dressing.","steps":["Place a clean dressing over the wound.","Wrap the bandage from beyond the wound toward the heart, overlapping each turn.","Tie or tape it off on the side, not on the wound.","Check feeling, warmth, and color beyond the wrap."],"call":"Call emergency services if blood soaks through and keeps coming, or if the limb below the wrap turns pale, blue, or numb.","rel":["pressure_bandage","wound_cleaning"],"src":["atp4-02-11","cdc"]},{"id":"pressure_bandage","title":"Pressure bandage","domain":"firstaid","also":["emergency bandage","israeli bandage","wrap that stops bleeding"],"def":"A pressure bandage is a thick pad held over a bleeding wound with a firm wrap, so you can keep pressure on without your hands.","look":["thick pad directly on the wound","firm wrap that presses the pad down","pad is not pulled off when blood soaks it"],"use":"Use it after direct pressure when bleeding is steady and you need your hands free. Add more padding on top if blood soaks through; do not remove the first layer.","not":"Do not use it as a tourniquet, and do not wrap so tight that it cuts off circulation to the limb below. Do not peel off a soaked dressing to look.","call":"Call emergency services for any bleeding that soaks through a pressure bandage or comes in spurts.","rel":["bleeding_pressure","tourniquet_last_resort"],"src":["atp4-02-11"]},{"id":"arterial_bleeding","title":"Arterial bleeding","domain":"firstaid","also":["spurting blood","bright red bleeding","life-threatening bleeding"],"def":"Arterial bleeding is blood from an artery: bright red and often spurting with each heartbeat, and it can be fatal within minutes.","look":["bright red blood that spurts or pulses","blood that quickly pools or soaks clothing","pale, cold, clammy skin and fast pulse as blood is lost"],"use":"Press hard with both hands directly on the wound with a thick pad or cloth, keep pressing, and call emergency services. If pressure cannot stop bleeding on an arm or leg, a tourniquet is the last resort.","not":"Do not stop pressing to look at the wound, do not remove soaked cloth (add more on top), and do not use a tourniquet for minor bleeding.","call":"Call emergency services now. Keep the person lying down and warm until help arrives.","rel":["bleeding_pressure","tourniquet_last_resort","shock_position"],"src":["atp4-02-11","cdc"]},{"id":"internal_bleeding","title":"Internal bleeding","domain":"firstaid","also":["bleeding inside the body","hidden bleeding","blood loss you cannot see"],"def":"Internal bleeding is blood loss inside the body that you cannot see, often after a hard blow, a fall, a crash, or a deep injury to the torso.","look":["bruising, swelling, or a hard painful belly after a blow","pale, cold, clammy skin, fast weak pulse, dizziness","vomiting or coughing blood, or blood in stool or urine","growing confusion or collapse"],"use":"Lay the person down, keep them still and warm, raise the legs only if no head, spine, or leg injury is suspected, and get emergency help. Do not give food or drink.","not":"Do not give anything to eat or drink, do not let them walk it off, and do not assume a lack of visible blood means a lack of danger.","call":"Call emergency services immediately; internal bleeding needs a hospital.","rel":["shock_position","abdominal_injury"],"src":["atp4-02-11","nih-medline"]},{"id":"abdominal_injury","title":"Belly (abdominal) wound or injury","domain":"firstaid","also":["stomach wound","bowel sticking out","gut injury","blow to the belly"],"def":"A serious belly injury can damage organs and bleed inside, and an open wound can let intestines show.","look":["open wound or protruding bowel","a rigid, swollen, very painful belly","vomiting, pale clammy skin, fast pulse"],"use":"Keep the person lying on their back with knees bent if comfortable, cover any exposed organs loosely with a clean moist cloth, and get emergency help.","not":"Do not push organs back in, do not press on the wound, and do not give food or drink.","call":"Call emergency services immediately.","rel":["internal_bleeding","shock_position"],"src":["atp4-02-11"]},{"id":"chest_wound","title":"Chest wound (sucking chest wound)","domain":"firstaid","also":["punctured lung","stab to the chest","penetrating chest injury","pneumothorax"],"def":"A penetrating chest wound can let air into the chest around the lung, making breathing hard and getting worse.","look":["hole in the chest, sometimes with a sucking sound or bubbling blood","trouble breathing and chest pain","blue lips, fast breathing, anxiety"],"use":"Cover the hole with a chest seal or a piece of plastic taped on three sides so air can escape on the way out but not in. Sit the person up if they can breathe better that way. Get emergency help.","not":"Do not remove an object stuck in the chest, and do not seal all four sides if you have no vented seal and breathing is getting worse; release the tape briefly.","call":"Call emergency services immediately.","rel":["impaled_object","shock_position"],"src":["atp4-02-11"]},{"id":"impaled_object","title":"Object stuck in a wound","domain":"firstaid","also":["impaled object","stabbed","something stuck in the leg","embedded object"],"def":"An embedded object plugs the wound it caused, and pulling it out can release heavy bleeding.","look":["object visibly stuck in the body","bleeding around, not through, the object","pain with movement"],"use":"Leave it in place. Pad around it to hold it still and stop it moving, control bleeding by pressing around it, and get emergency help.","not":"Do not pull it out, do not push it deeper, and do not cut it unless it must be shortened to move the person. Never remove an object from the eye, neck, or chest.","call":"Call emergency services immediately.","rel":["chest_wound","bleeding_pressure"],"src":["atp4-02-11"]},{"id":"amputation_care","title":"Amputation: care of the person and the part","domain":"firstaid","also":["severed finger","cut off hand","body part cut off","avulsion"],"def":"After an amputation, the first job is to stop the bleeding and treat shock; the severed part is saved wrapped and cool so it might be reattached.","look":["heavy bleeding from the stump","a separated finger, hand, or limb","pale clammy skin and fast pulse"],"use":"Press hard on the stump, use a tourniquet if pressure does not stop life-threatening bleeding, lay the person down and keep them warm. Wrap the part in clean damp gauze, put it in a plastic bag, and keep that bag cool on ice, not touching it.","not":"Do not put the part directly on ice or in water, do not wash it hard, and do not delay getting help to look for it.","call":"Call emergency services immediately and send the part with the person.","rel":["tourniquet_last_resort","shock_position"],"src":["atp4-02-11","nih-medline"]},{"id":"crush_injury","title":"Crush injury","domain":"firstaid","also":["pinned under something","trapped limb","crushed leg","building collapse injury"],"def":"A crush injury is damage from a heavy weight pressing a body part, and releasing a long-trapped limb can suddenly cause shock or kidney trouble.","look":["limb pinned under a heavy object","swelling, numbness, and pain","dark urine or weakness after a long entrapment"],"use":"Get emergency help first. If trapped less than about 15 minutes and the load is safe to lift, free the person, control bleeding, and treat for shock. Keep them still.","not":"Do not free someone who has been crushed for hours without medical direction if you can avoid it, and do not massage the limb.","call":"Call emergency services immediately and tell them how long the person was trapped.","rel":["shock_position","splint_immobilize"],"src":["atp4-02-11","fema"]},{"id":"broken_bone_signs","title":"Signs of a broken bone","domain":"firstaid","also":["fracture","broken arm","broken leg","did I break it","cracked bone"],"def":"A fracture is a break or crack in a bone, and the signs are pain that is worse with movement, swelling, bruising, and an odd shape or loss of use.","look":["sharp pain at one spot that is worse with use","swelling, bruising, and a limb that looks bent or short","a grinding feeling or sound, or a bone end through the skin"],"use":"Keep the limb still, splint it in the position found, treat bleeding, and get medical care. Check feeling and color beyond the injury before and after splinting.","not":"Do not try to straighten a bent limb, push a bone end back in, or let the person walk on a suspected leg or hip fracture.","call":"Call emergency services for an open fracture, a limb that is pale, blue, or numb beyond the break, a suspected hip, thigh, pelvis, neck or back fracture, or heavy bleeding.","rel":["splint_immobilize","sling_and_swathe","open_fracture"],"src":["atp4-02-11","nih-medline"]},{"id":"open_fracture","title":"Open (compound) fracture","domain":"firstaid","also":["bone sticking out","compound fracture","bone through skin"],"def":"An open fracture is a broken bone with an open wound, which means a high risk of infection and bleeding.","look":["bone end visible or a wound over a deformed limb","bleeding at the break","severe pain and swelling"],"use":"Control bleeding with pressure around the bone, not on it. Cover the wound loosely with a clean moist dressing, splint without pushing the bone back, and get emergency help.","not":"Do not push the bone back under the skin, do not wash the exposed bone hard, and do not pull on the limb to line it up.","call":"Call emergency services immediately.","rel":["broken_bone_signs","splint_immobilize"],"src":["atp4-02-11"]},{"id":"sling_and_swathe","title":"Sling and swathe","domain":"firstaid","also":["arm sling","triangle bandage sling","broken collarbone sling","shoulder injury support"],"def":"A sling holds the forearm up, and a swathe is a second bandage that binds the arm against the chest so it cannot swing.","look":["a triangular bandage or a shirt tail","forearm rests higher than the elbow","knot placed at the side of the neck, not on the spine"],"use":"Use it for a broken arm, collarbone, shoulder or dislocation, after you have checked the fingers for color and feeling. Put padding between the arm and body.","not":"Do not use it to hold a bone in a position that hurts more; support it as found. Do not tie it so tight that the fingers go pale or numb.","steps":["Support the injured arm in a comfortable position, elbow bent.","Slide the triangular bandage under the forearm and tie it behind the neck on the side.","Pad the knot and secure the elbow end.","Tie a second band around the chest and the arm to hold it still."],"call":"Call emergency services for an open fracture, a pale, blue, or numb hand, or severe pain.","rel":["broken_bone_signs","dislocation"],"src":["atp4-02-11"]},{"id":"dislocation","title":"Dislocated joint","domain":"firstaid","also":["dislocated shoulder","dislocated finger","joint out of place","popped out of socket"],"def":"A dislocation is when the ends of the bones in a joint are forced out of place, leaving the joint looking wrong and unable to move.","look":["joint looks deformed or out of position","severe pain and swelling and unable to move it","numbness or tingling beyond the joint"],"use":"Support the joint in the position found with padding and a sling or splint, apply a cool pack for pain, and get it put back by a clinician.","not":"Do not try to force the joint back in yourself, and do not massage or move it to test it.","call":"Call emergency services if the limb below is pale, blue, cold, or numb, or if the joint is the hip, knee, neck or back.","rel":["sling_and_swathe","sprain_rice"],"src":["atp4-02-11","nih-medline"]},{"id":"concussion_signs","title":"Concussion and head injury","domain":"firstaid","also":["hit head","bump on the head","knocked out","head trauma","brain injury"],"def":"A concussion is a mild brain injury from a blow or jolt to the head, and the danger is that a serious bleed can build slowly.","look":["headache, dizziness, confusion, or memory gaps","nausea or vomiting, or blurred vision","a brief loss of consciousness, or sleepiness","clear fluid or blood from the nose or ears"],"use":"Keep the person resting and watch them closely for the next day or two. Stay with them. Get checked by a clinician after any significant blow, loss of consciousness, or confusion.","not":"Do not leave them alone, do not let them return to sport or hard activity the same day, and do not give alcohol.","call":"Call emergency services for loss of consciousness, repeated vomiting, a seizure, worsening headache, confusion, weakness, unequal pupils, or clear fluid from the ears or nose.","rel":["spinal_still","unconscious_person"],"src":["cdc","nih-medline","atp4-02-11"]},{"id":"unconscious_person","title":"Person who is unconscious but breathing","domain":"firstaid","also":["passed out","fainted","not waking up","unresponsive"],"def":"An unresponsive person who is still breathing normally needs their airway kept open and an ambulance, because they can choke on their own tongue or vomit.","look":["does not respond to voice or a shoulder tap","chest rises and falls with normal breathing","no obvious neck or spine injury"],"use":"Call for emergency help, check breathing, and place the person in the recovery position unless a spine injury is suspected. Stay with them and recheck breathing often.","not":"Do not give food or drink, do not leave them alone, and do not move them if a neck or spine injury is suspected unless you must open the airway.","call":"Call emergency services; if breathing stops, begin CPR.","rel":["recovery_position","cpr_rate_depth"],"src":["atp4-02-11","cdc","nih-medline"]},{"id":"fainting","title":"Fainting","domain":"firstaid","also":["passing out","about to faint","blacked out","lightheaded and dizzy"],"def":"Fainting is a short loss of consciousness when the brain briefly gets too little blood, often from standing too long, heat, fear, pain, or dehydration.","look":["lightheaded, pale, sweaty, vision narrowing","collapse that lasts under a minute or two","wakes quickly and recovers"],"use":"Lay the person flat and raise their legs, loosen tight clothing, and give fresh air. Let them sit up slowly after they have recovered, and offer a drink if awake.","not":"Do not sit them up quickly, do not splash water in the face, and do not ignore a faint with chest pain, an irregular heartbeat, injury, or pregnancy.","call":"Call emergency services if they do not wake within a minute or two, hit their head, have chest pain or trouble breathing, or faint again.","rel":["unconscious_person","heat_exhaustion_signs"],"src":["nih-medline","atp4-02-11"]},{"id":"eye_object","title":"Something in the eye","domain":"firstaid","also":["speck in eye","grit in eye","eyelash in eye","foreign body in eye","eye pain"],"def":"A speck or grit in the eye usually washes out with tears or clean water, and anything stuck or sharp needs a clinician.","look":["watering, blinking, redness, a gritty feel","pain that is worse when blinking","something visible on the white of the eye or under the lid"],"use":"Do not rub. Blink, then flush the eye with clean water or saline for several minutes. Pull the upper lid over the lower to let lashes sweep it out.","not":"Do not rub the eye, do not try to dig out an embedded object, and do not remove a stuck or impaled object.","call":"Call emergency services or get urgent care for an embedded object, a chemical splash that is still painful after flushing, vision loss, or a cut on the eyeball.","rel":["chemical_eye_flush","snow_blindness"],"src":["nih-medline","atp4-02-11"]},{"id":"snow_blindness","title":"Snow blindness","domain":"firstaid","also":["sun burned eyes","photokeratitis","eye sunburn","welder flash"],"def":"Snow blindness is a painful sunburn of the surface of the eye from bright ultraviolet light reflecting off snow, ice, or water.","look":["gritty, burning pain and tears hours after exposure","red, swollen lids and sensitivity to light","blurry vision that usually clears in a day or two"],"use":"Get out of the light, cover both eyes with a dark soft cloth, rest, and use cool damp cloths for comfort. Prevent it with dark tinted glasses with side shields.","not":"Do not rub the eyes or keep going on the glare. Do not treat it with leaf or herb poultices.","call":"Get medical care if the pain is severe or sight does not improve in a day or two.","rel":["eye_object","sunburn"],"src":["atp3-50-21","nih-medline"]},{"id":"tooth_knocked_out","title":"Knocked-out tooth","domain":"firstaid","also":["lost a tooth","avulsed tooth","broken tooth","tooth fell out"],"def":"A knocked-out adult tooth can sometimes be saved if it is kept moist and put back or seen by a dentist within about an hour.","look":["a whole tooth out with the root attached","bleeding in the socket","pain and swelling"],"use":"Pick up the tooth by the crown, not the root. Rinse gently with milk or saline if dirty and try to push it back into the socket; otherwise keep it in milk or against the cheek. See a dentist right away.","not":"Do not scrub the tooth, touch the root, or put a baby tooth back in. Do not store it dry.","call":"Call emergency services if there is other injury to the head, face or neck, or heavy bleeding.","rel":["toothache_field","concussion_signs"],"src":["nih-medline","cdc"]},{"id":"toothache_field","title":"Toothache in the field","domain":"firstaid","also":["tooth pain","abscess","swollen gum","dental pain"],"def":"A toothache is pain from decay, a crack, or an abscess, and swelling or fever means the infection may be spreading.","look":["steady throbbing pain, worse with hot or cold","swollen gum or cheek, a bad taste","fever or swelling of the face or neck"],"use":"Rinse with warm salt water, keep the mouth clean, and use over-the-counter pain relievers as directed on the label. See a dentist as soon as you can.","not":"Do not put aspirin on the gum, and do not drain or poke an abscess yourself.","call":"Call emergency services for swelling that spreads to the eye, neck or floor of the mouth, trouble swallowing or breathing, or fever with a swollen face.","rel":["tooth_knocked_out","wound_infection_signs"],"src":["nih-medline","cdc"]},{"id":"fishhook_removal","title":"Fishhook removal","domain":"firstaid","also":["hook in finger","fish hook stuck","hook in skin"],"def":"A fishhook is barbed, so pulling straight back tears the skin; it is pushed through or backed out along its curve.","look":["hook embedded in finger, arm, or face","barb under the skin","small bleeding point at the entry"],"use":"For a shallow hook, push the point through, snip off the barb with clippers, and back the shaft out. Clean the wound and cover it. Check your tetanus status.","not":"Do not try to remove a hook from the eye, face near the eye, or a deep joint; get medical help. Do not yank it straight back.","call":"Call emergency services or go to an emergency room for hooks in the eye, face, a joint, or a vein.","rel":["wound_cleaning","tetanus_shot"],"src":["nih-medline","atp4-02-11"]},{"id":"tetanus_shot","title":"Tetanus and wounds","domain":"firstaid","also":["lockjaw","tetanus booster","rusty nail","dirty wound vaccine"],"def":"Tetanus is a serious infection from bacteria in soil and dirt that enter a wound, and it is prevented by vaccination with boosters.","look":["a dirty, deep, or puncture wound","animal bite or rusty or soil-contaminated injury","no booster in the last five to ten years"],"use":"Ask a clinician about a booster after a dirty or deep wound, usually if you have not had one in the last five years for dirty wounds or ten years for clean ones.","not":"Do not rely on rinsing alone to prevent it, and do not assume the rust itself causes it; the germ is in soil and dirt.","call":"Call emergency services for muscle stiffness, jaw spasms, or trouble swallowing after a wound.","rel":["wound_cleaning","animal_bite"],"src":["cdc","nih-medline"]},{"id":"animal_bite","title":"Animal bite","domain":"firstaid","also":["dog bite","cat bite","bitten by a wild animal","rabies exposure","bat in the house"],"def":"An animal bite can cause infection and, from wild animals, rabies, so it needs washing and a call to a clinician or health department.","look":["puncture or torn skin from teeth or claws","a wild, strange-acting, or unprovoked animal","a bat found in a room with a sleeping person or child"],"use":"Wash with soap and running water for several minutes, control bleeding, and cover. Get medical care the same day and report the animal. Rabies shots are most effective when started early.","not":"Do not wait for symptoms. Do not try to catch or kill the animal with your hands.","call":"Call emergency services for severe bleeding or a face, neck or hand bite; call a clinician or health department for any wild-animal bite or bat exposure.","rel":["wound_cleaning","tetanus_shot"],"src":["cdc","nih-medline"]},{"id":"splinter_removal","title":"Splinter removal","domain":"firstaid","also":["sliver","thorn in the skin","wood splinter","cactus spines"],"def":"A splinter is a small piece of wood, thorn, or glass in the skin that is removed with clean tweezers along the angle it went in.","look":["a visible end sticking out","tenderness at the spot","redness only around the entry point"],"use":"Wash the skin, clean the tweezers with alcohol or boiling water, pull the splinter out in the line it entered, and wash again. Tape can lift fine cactus spines.","not":"Do not dig around with a dirty needle or squeeze it. Do not remove a deep, long, or glass splinter near an eye or joint yourself.","call":"Get medical care for a deep splinter, signs of infection, or one close to the eye.","rel":["wound_cleaning","tetanus_shot"],"src":["nih-medline","cdc"]},{"id":"blister_care","title":"Blisters and hot spots","domain":"firstaid","also":["foot blister","rubbing boot","hot spot on heel","blister on foot"],"def":"A blister is a fluid-filled pocket from friction or heat, and a hot spot is the warm, tender patch that warns one is coming.","look":["a warm, red, tender patch where a boot rubs","a raised bubble of clear fluid","torn skin or a blood blister"],"use":"Stop and treat hot spots early with tape or a friction pad. Leave an intact blister covered with a donut pad. If it is large and in the way, drain it with a clean pin at the edge, leave the roof, and cover it.","not":"Do not rip off the roof of a blister, and do not keep hiking in the same wet socks. Do not cover signs of infection.","call":"Get medical care for redness spreading, pus, fever, or a blister in someone with diabetes or poor circulation.","rel":["trench_foot","foot_care_hiking"],"src":["nps","nih-medline","atp3-50-21"]},{"id":"foot_care_hiking","title":"Foot care on the trail","domain":"firstaid","also":["sore feet","care for feet when hiking","preventing blisters","dry socks"],"def":"Foot care is keeping feet dry, clean, and padded so friction, wet, and cold do not disable you.","look":["changing to dry socks at breaks","trimmed toenails and well-fitting boots","treating hot spots the moment they start"],"use":"Stop at the first hot spot, dry feet at rests, rotate socks, and use powder or tape where you rub. Air feet at night and dry socks against your body.","not":"Do not break in new boots on a long trip, and do not hike on wet feet all day.","call":"Get medical care for infection signs, numb or pale toes, or foot pain that is not going away.","rel":["blister_care","trench_foot"],"src":["atp3-50-21","nps"]},{"id":"trench_foot","title":"Trench foot (immersion foot)","domain":"firstaid","also":["wet foot injury","immersion foot","feet numb and swollen from wet"],"def":"Trench foot is damage to the feet from long exposure to wet and cold, even above freezing, and it can lead to tissue loss.","look":["cold, numb, tingling feet that may look pale, blue, or red","swelling and a heavy, 'wooden' feel","blisters or open sores after warming"],"use":"Get out of wet footwear, dry and gently warm the feet, keep them raised and clean, and get medical care. Prevent it with dry socks and regular foot checks.","not":"Do not rub or massage the feet, do not walk on them if badly injured, and do not warm with high heat or a fire.","call":"Call emergency services or get care for numb, blue, or blistering feet.","rel":["frostbite_warming","foot_care_hiking"],"src":["atp3-50-21","atp4-02-11","cdc"]},{"id":"sunburn","title":"Sunburn","domain":"firstaid","also":["burned by the sun","red skin","sun poisoning"],"def":"Sunburn is skin damage from ultraviolet light that shows up as red, painful skin hours after exposure.","look":["red, hot, painful skin that appears hours later","blisters on bad burns","fever, chills, or nausea with a severe burn"],"use":"Get out of the sun, cool the skin with cool water, drink fluids, and use moisturizer. Cover up and keep burned skin out of the sun. Prevent it with shade, clothing, a hat, and sunscreen.","not":"Do not break blisters, do not use butter or petroleum on a fresh burn, and do not go back in the sun.","call":"Call emergency services or get care for blistering over a large area, fever, confusion, or severe pain, and for any sunburn on a baby under one year.","rel":["heat_exhaustion_signs","burn_cool_water"],"src":["cdc","nih-medline"]},{"id":"recovery_position","title":"Recovery position","domain":"firstaid","also":["lateral position","roll someone on their side","put them on their side","keep airway open"],"def":"The recovery position lays an unresponsive person who is breathing on their side so the tongue falls forward and fluid drains out of the mouth.","look":["person is unresponsive but breathing normally","lying on their side with the top leg bent for stability","head tilted back slightly with the mouth angled down"],"use":"Use it when someone who is breathing normally will not wake and no spine injury is suspected. Stay with them, call for help, and check their breathing again and again.","not":"Do not use it if they are not breathing (start CPR). If you suspect a neck or spine injury, keep the head, neck, and back in line and move them only as much as needed to keep the airway open.","steps":["Kneel beside them and place the arm nearest you at a right angle.","Bring the far arm across the chest and hold the back of the hand against their cheek.","Bend the far knee and roll them toward you onto their side.","Tilt the head back to keep the airway open and adjust the top leg so they cannot roll forward."],"call":"Call emergency services for anyone who will not wake up.","rel":["cpr_rate_depth","unconscious_person"],"src":["atp4-02-11","cdc","nih-medline"]},{"id":"heat_exhaustion_signs","title":"Heat exhaustion","domain":"firstaid","also":["overheated","heavy sweating and weak","too hot and dizzy","heat sickness"],"def":"Heat exhaustion is the body overheating from heat and fluid loss, with heavy sweating, weakness, and dizziness. It can progress to heat stroke.","look":["heavy sweating, pale or clammy skin","headache, dizziness, nausea, and weakness","fast weak pulse and muscle cramps","body temperature is raised but the person is alert"],"use":"Move to shade or a cool place, loosen clothes, cool with wet cloths or a fan, and give small sips of water. Rest and do not go back to hard work that day.","not":"Do not let them keep exercising, and do not give salt tablets or alcohol. Do not force fluids on someone vomiting or confused.","call":"Call emergency services if they vomit repeatedly, get confused, faint, stop sweating, or are not better within about 30 minutes.","rel":["heat_stroke_signs","hydration_basics"],"src":["cdc","nws","nih-medline"]},{"id":"heat_stroke_signs","title":"Heat stroke","domain":"firstaid","also":["sunstroke","hyperthermia","very hot skin and confused","body overheated"],"def":"Heat stroke is a life-threatening emergency in which the body temperature rises dangerously high and the brain is affected.","look":["hot, red, dry or damp skin; sweating may stop","confusion, slurred speech, or odd behavior","throbbing headache, fast pulse, and collapse","seizure or loss of consciousness"],"use":"Call for emergency help, move the person to shade, and cool them fast: remove extra clothing and use cold water on the skin, wet sheets, fanning, or ice packs on the neck, armpits, and groin.","not":"Do not give fluids to someone who is confused or unconscious, and do not stop cooling until help arrives.","call":"Call emergency services immediately; heat stroke can be fatal.","rel":["heat_exhaustion_signs","hydration_basics"],"src":["cdc","nws","nih-medline"]},{"id":"heat_cramps","title":"Heat cramps","domain":"firstaid","also":["muscle cramps in the heat","leg cramps from sweating","cramping while hiking"],"def":"Heat cramps are painful muscle spasms during or after hard work in the heat, usually from fluid and salt loss.","look":["cramping in the legs, arms, or belly","heavy sweating","otherwise alert and normal temperature"],"use":"Stop, rest in the shade, stretch and gently massage the cramping muscle, and sip water or a drink with electrolytes.","not":"Do not keep pushing through cramps. Do not take salt tablets without advice.","call":"Get medical care if cramps last more than an hour or you also feel confused, faint, or very ill.","rel":["heat_exhaustion_signs","hydration_basics"],"src":["cdc","nih-medline"]},{"id":"hydration_basics","title":"Staying hydrated","domain":"firstaid","also":["how much water to drink","drink more water","thirst","pale urine"],"def":"Staying hydrated means drinking steadily so urine stays pale; thirst lags behind, so drink before you are thirsty during work or heat.","look":["pale yellow urine means good hydration","dark urine, headache, dry mouth, and tiredness mean you need more","very little urine or dizziness are warning signs"],"use":"Sip regularly through the day and more in heat, at altitude, or when ill. Add food and some salt when sweating heavily for hours.","not":"Do not drink only when thirsty during hard work, and do not drink huge amounts quickly; too much plain water can dilute the body's salt.","call":"Call emergency services for confusion, fainting, or no urination for many hours.","rel":["hyponatremia","oral_rehydration"],"src":["cdc","nih-medline","atp3-50-21"]},{"id":"hyponatremia","title":"Water intoxication (low blood sodium)","domain":"firstaid","also":["drinking too much water","hyponatremia","overhydration"],"def":"Drinking far more water than you sweat out can dilute the salt in the blood, causing headache, nausea, and confusion.","look":["headache, nausea, and bloated feeling after drinking lots of water","confusion, weakness, or seizures in severe cases","long endurance effort with lots of plain water and little food"],"use":"Stop drinking plain water and eat salty snacks. Get medical help for confusion or severe symptoms.","not":"Do not keep forcing water or treat it as dehydration, and do not drink large volumes in a short time.","call":"Call emergency services for confusion, vomiting, seizure, or collapse.","rel":["hydration_basics","heat_exhaustion_signs"],"src":["cdc","nih-medline"]},{"id":"hypothermia_stages","title":"Hypothermia: mild to severe","domain":"firstaid","also":["too cold","shivering uncontrollably","umbles","stumbling and mumbling","cold exposure"],"def":"Hypothermia is when body temperature falls below normal, and the signs progress from shivering to clumsiness and confusion to stopped shivering.","look":["mild: shivering, cold hands, clumsy","moderate: stumbling, slurred speech, apathy, confusion","severe: shivering stops, drowsy, very slow pulse or breathing"],"use":"Get out of wind and wet, remove wet clothes, insulate from the ground, wrap in a dry blanket and add a vapor barrier, then give warm sweet drinks if awake and able to swallow. Handle severely cold people gently.","not":"Do not rub the limbs, give alcohol, or put a severely cold person in a hot bath. Do not leave them alone.","call":"Call emergency services for confusion, stopped shivering, or unconsciousness. Begin CPR if no pulse or breathing and keep going until help arrives.","rel":["rewarming_safely","cold_layers"],"src":["cdc","atp3-50-21","atp4-02-11","nih-medline"]},{"id":"rewarming_safely","title":"Rewarming a cold person","domain":"firstaid","also":["warm someone up","how to warm a hypothermic person","sleeping bag with another person"],"def":"Rewarming a cold person means stopping heat loss first and then adding gentle heat to the trunk, not to the limbs.","look":["dry insulation under and over them","warm packs or bottles wrapped in cloth at chest, armpits, groin","warm sweet drink only if fully awake"],"use":"Put them in a pre-warmed sleeping bag, cover the head, add warm packs to the trunk, and give warm sweet drinks if they are alert. Keep them horizontal and handle gently.","not":"Do not rub or massage, do not use direct heat on the skin, and do not give alcohol or caffeine.","call":"Call emergency services for anyone who is confused or not shivering.","rel":["hypothermia_stages","frostbite_warming"],"src":["cdc","atp4-02-11","atp3-50-21"]},{"id":"drowning_rescue","title":"Drowning rescue and first aid","domain":"firstaid","also":["near drowning","pulled from water","pulled someone out of the water","cold water immersion"],"def":"Drowning is trouble breathing from submersion; the first moves are to reach the person safely, then get them breathing again.","look":["person in the water who is quiet, vertical, and not waving","not breathing or breathing with difficulty after being rescued","coughing or vomiting water"],"use":"Reach or throw something to them rather than going in. Once out, call for help and start rescue breaths and CPR if they are not breathing, then keep them warm.","not":"Do not swim out unless you are trained, and do not press on the stomach to remove water.","steps":["Reach with a pole or throw a rope or a float.","Get them out and check for breathing.","If not breathing, give 5 rescue breaths, then CPR.","Treat for hypothermia and watch for later breathing trouble."],"call":"Call emergency services for everyone who was submerged, even if they seem fine; breathing trouble can appear hours later.","rel":["cpr_rate_depth","hypothermia_stages"],"src":["cdc","atp4-02-11","nih-medline"]},{"id":"electric_shock","title":"Electrical shock","domain":"firstaid","also":["electrocuted","got shocked","downed power line","live wire"],"def":"An electric shock can stop the heart and cause internal burns that are bigger than they look, so every significant shock needs a medical check.","look":["person still touching a live source or near a downed wire","burns at the entry and exit points","unconscious, irregular pulse, or confusion"],"use":"Do not touch them until the power is off or the source is safely removed. If a downed line is near, stay back at least 10 meters, call emergency services, and do not approach. After power is off, check breathing and start CPR if needed.","not":"Do not touch a person in contact with a live source, do not move near a downed line, and do not use a metal or wet object to move a wire.","call":"Call emergency services for any electrical injury, including high-voltage or lightning.","rel":["lightning_strike_first_aid","burn_cool_water"],"src":["cdc","nih-medline","atp4-02-11"]},{"id":"lightning_strike_first_aid","title":"Lightning strike victim","domain":"firstaid","also":["struck by lightning","lightning injury","hit by lightning"],"def":"A lightning strike victim does not carry a charge, and they often need CPR because the heart or breathing may stop.","look":["unconscious or not breathing","burns, confusion, hearing or vision loss","several people hit in a group"],"use":"Move them to a safer place away from the storm, call for help, check breathing and pulse, and start CPR if needed. Treat burns and fractures after the person is breathing.","not":"Do not wait for the storm to end if more strikes are close and you can safely move them, and do not leave a seemingly dead person; people struck may revive with CPR.","call":"Call emergency services; lightning victims should always be checked at a hospital. Treat the most still ones first.","rel":["lightning","cpr_rate_depth"],"src":["nws","cdc","atp4-02-11"]},{"id":"carbon_monoxide_poisoning","title":"Carbon monoxide poisoning","domain":"firstaid","also":["CO poisoning","gas stove in tent","generator fumes","headache and dizzy in a closed room","carbon monoxide"],"def":"Carbon monoxide is an invisible, odorless gas from burning fuel that keeps blood from carrying oxygen.","look":["headache, dizziness, nausea, confusion","several people ill at the same time, or pets sick","symptoms ease when you go outside","cooking or heating fuel burning in a closed space"],"use":"Get everyone into fresh air at once, turn off the source, and call emergency services. Stay out until the space has been checked. Run generators and grills outside, far from doors and windows, and use CO alarms.","not":"Do not use a stove, grill, lantern, or generator inside a tent, vehicle, garage, or house, even with a door open.","call":"Call emergency services for anyone with symptoms, and move them out first.","rel":[],"src":["cdc","fema","usfa"]},{"id":"smoke_inhalation","title":"Smoke inhalation","domain":"firstaid","also":["breathed smoke","house fire fumes","smoke in the lungs"],"def":"Breathing smoke can burn the airway and carry poisonous gases, even if the skin is not burned.","look":["coughing, hoarse voice, black spit","singed nose hairs or soot around the mouth and nose","shortness of breath, headache, confusion"],"use":"Move the person into fresh air, call emergency services, and keep them sitting upright and calm. Start CPR if they stop breathing.","not":"Do not let them go back inside, and do not wait for symptoms to worsen; airway swelling can develop later.","call":"Call emergency services for anyone who breathed smoke.","rel":["carbon_monoxide_poisoning","burn_cool_water"],"src":["cdc","usfa","nih-medline"]},{"id":"burn_degrees","title":"Burn severity: first, second, third degree","domain":"firstaid","also":["how bad is the burn","burn blisters","charred skin","degrees of burns"],"def":"Burns are graded by depth: first-degree is red and dry, second-degree blisters, and third-degree is white, brown, or charred and may be numb.","look":["first degree: red, dry, painful, no blisters","second degree: blisters, moist, very painful","third degree: leathery, white or charred, may not hurt","size, face, hands, genitals, and joints raise the danger"],"use":"Cool any burn under cool running water for about 20 minutes, remove rings and loose clothing, and cover with a clean non-stick dressing. Get care for blisters larger than the palm.","not":"Do not use ice, butter, oils, toothpaste, or popped blisters. Do not pull off stuck clothing.","call":"Call emergency services for third-degree burns, burns on the face, hands, feet, genitals, or over joints, chemical or electrical burns, or burns bigger than a palm in a child.","rel":["burn_cool_water","chemical_burn_skin"],"src":["cdc","nih-medline","atp4-02-11"]},{"id":"chemical_burn_skin","title":"Chemical burn on the skin","domain":"firstaid","also":["acid on skin","bleach on skin","lye","caustic burn"],"def":"A chemical burn keeps damaging skin until the chemical is removed, so flushing starts immediately.","look":["burning, redness, or blistering after contact","chemical container or label nearby","itching or pain that keeps getting worse"],"use":"Remove contaminated clothing, brush off dry powder first, and flush with lots of cool running water for at least 20 minutes. Cover loosely and call poison control or emergency services.","not":"Do not try to neutralize the chemical, and do not use only a small splash of water. Do not rub.","call":"Call emergency services or poison control (in the US, 1-800-222-1222) with the container label in hand.","rel":["chemical_eye_flush","burn_degrees"],"src":["cdc","nih-medline"]},{"id":"stroke_fast","title":"Stroke signs (FAST)","domain":"firstaid","also":["face drooping","slurred speech","arm weakness","mini stroke","TIA"],"def":"A stroke is a blocked or burst blood vessel in the brain, and fast treatment limits the damage.","look":["Face drooping on one side","Arm weakness or drifting down","Speech slurred or confused","Time to call emergency services"],"use":"Note the time symptoms started, call emergency services immediately, keep the person calm and seated or lying with the head slightly raised, and do not give food or drink.","not":"Do not wait to see if it passes, do not drive them yourself if an ambulance is available, and do not give aspirin unless a dispatcher tells you to.","call":"Call emergency services immediately.","rel":["heart_attack_signs","fainting"],"src":["cdc","nih-medline"]},{"id":"asthma_attack","title":"Asthma attack","domain":"firstaid","also":["wheezing","cannot breathe tight chest","inhaler","shortness of breath"],"def":"An asthma attack is a tightening of the airways that makes breathing hard and noisy.","look":["wheezing, coughing, tight chest","struggling to speak a full sentence","using neck and belly muscles to breathe, or blue lips"],"use":"Sit the person upright, help them use their own quick-relief inhaler as directed, keep them calm, and move them away from triggers. Call emergency help if it does not ease.","not":"Do not lay them flat, do not leave them alone, and do not use someone else's medicine unless a dispatcher tells you to.","call":"Call emergency services if breathing is not quickly better after the inhaler, if lips or fingers turn blue, or if they cannot speak.","rel":["anaphylaxis_signs","choking_thrusts"],"src":["cdc","nih-medline"]},{"id":"anaphylaxis_signs","title":"Severe allergic reaction (anaphylaxis) signs","domain":"firstaid","also":["allergic reaction","swelling of throat","hives and trouble breathing","bee sting allergy","peanut allergy"],"def":"Anaphylaxis is a rapid, whole-body allergic reaction that can close the airway and drop blood pressure.","look":["hives, swelling of the face, lips or tongue","wheezing, throat tightness, trouble breathing","vomiting, dizziness, pale or faint","symptoms within minutes of a sting, food, or medicine"],"use":"Use the person's prescribed epinephrine auto-injector right away on the outer thigh if one is available, call emergency services, and lay them down with legs raised unless breathing is easier sitting.","not":"Do not wait to see if it settles, do not give food or drink, and do not stand them up quickly.","call":"Call emergency services immediately, even if the injector helped.","rel":["epinephrine_auto","bee_wasp_sting"],"src":["cdc","nih-medline"]},{"id":"bee_wasp_sting","title":"Bee and wasp stings","domain":"firstaid","also":["bee sting","hornet sting","stung by a wasp","stinger"],"def":"A sting injects venom that causes pain and swelling; a honeybee leaves its stinger and venom sac in the skin.","look":["sharp pain, a red welt, and local swelling","a small black stinger in the skin","hives, wheezing, or swelling away from the sting mean an allergic reaction"],"use":"Move away from the nest, scrape the stinger out with a card edge or fingernail, wash, and apply a cool pack. Watch for allergy signs for at least 30 minutes.","not":"Do not squeeze the stinger with tweezers, and do not ignore breathing trouble, a swollen face, or dizziness.","call":"Call emergency services for any sign of a severe allergic reaction, or for many stings at once.","rel":["anaphylaxis_signs","spider_bites"],"src":["cdc","nih-medline"]},{"id":"spider_bites","title":"Black widow and brown recluse bites","domain":"firstaid","also":["spider bite","black widow","brown recluse","venomous spider"],"def":"Most spiders are harmless, but black widows and brown recluses have bites that need medical care.","look":["black widow: shiny black spider with a red hourglass underneath; severe cramps and sweating","brown recluse: tan spider with a violin mark; a blister that can turn into a sore","pain, redness, and a spreading wound"],"use":"Clean the bite, apply a cool pack, keep the area still and raised, and get medical care. If you can safely do so, note what the spider looked like.","not":"Do not cut the bite, apply a tourniquet, or try to suck out venom.","call":"Call emergency services for severe pain, belly cramps, trouble breathing, or a child or older adult bitten.","rel":["scorpion_sting","bee_wasp_sting"],"src":["cdc","nih-medline"]},{"id":"scorpion_sting","title":"Scorpion sting","domain":"firstaid","also":["stung by a scorpion","bark scorpion"],"def":"Most scorpion stings hurt like a bee sting, but the bark scorpion of the US Southwest can cause serious nerve symptoms, especially in children.","look":["sharp burning pain, numbness, and tingling","drooling, odd eye movements, or twitching muscles in severe stings","a child who is restless or crying and cannot be calmed"],"use":"Wash with soap and water, apply a cool pack, keep the area still, and get medical advice or call poison control. Shake out shoes and clothes in scorpion country.","not":"Do not cut the sting, apply a tourniquet, or ignore a child with severe symptoms.","call":"Call emergency services or poison control (US 1-800-222-1222) for severe symptoms, a young child, or an older adult.","rel":["spider_bites","bee_wasp_sting"],"src":["cdc","nih-medline"]},{"id":"poison_ivy_rash","title":"Poison ivy, oak, and sumac rash","domain":"firstaid","also":["itchy rash from a plant","leaves of three","urushiol","contact dermatitis"],"def":"Poison ivy, oak, and sumac carry an oil called urushiol that causes an itchy, blistering rash on contact.","look":["streaks or patches of itchy red bumps and blisters","rash shows up hours to days after touching the plant","oil can be carried on tools, pets, and clothes"],"use":"Wash skin with soap and cool water as soon as you can, then wash clothing and tools. Cool compresses and calamine can ease the itch.","not":"Do not burn the plants, scratch blisters open, or touch your face after handling them.","call":"Get medical care for a rash on the face, genitals, or over much of the body, or swelling and trouble breathing; never breathe smoke from burning these plants.","rel":["poison_ivy_id","wound_cleaning"],"src":["cdc","nih-medline","usda-nrcs"]},{"id":"jellyfish_sting","title":"Jellyfish and marine stings","domain":"firstaid","also":["jellyfish","portuguese man o war","stingray","sea urchin"],"def":"Jellyfish tentacles carry stinging cells that keep firing; treat by removing them and soaking in hot water, not by rubbing.","look":["lines of welts where a tentacle touched","burning pain and itching","trouble breathing or chest pain in severe stings"],"use":"Rinse the area with seawater (not fresh water), pick off tentacles with tweezers or a gloved hand, and soak in hot water, as hot as is comfortable, for 20 to 45 minutes. Vinegar helps with some species.","not":"Do not rinse with fresh water, rub with sand, or use urine.","call":"Call emergency services for trouble breathing, chest pain, a large area stung, or a stingray puncture.","rel":["anaphylaxis_signs","wound_cleaning"],"src":["cdc","nih-medline"]},{"id":"low_blood_sugar","title":"Low blood sugar (diabetic emergency)","domain":"firstaid","also":["hypoglycemia","diabetic passed out","shaky and sweaty","insulin shock","blood sugar low"],"def":"Low blood sugar in a person with diabetes causes shakiness, sweating, and confusion and is fixed fast with sugar.","look":["shaky, sweaty, hungry, and anxious","confusion, slurred speech, or odd behavior","drowsy, seizure, or unconscious in severe cases"],"use":"If they are awake and can swallow, give fast sugar such as juice, glucose tablets, or regular soda, then a snack. Call for help if it does not improve in about 15 minutes.","not":"Do not give food or drink to someone who is unconscious or cannot swallow, and do not give insulin.","call":"Call emergency services if they are unconscious, having a seizure, or are not better in 15 minutes.","rel":["fainting","unconscious_person"],"src":["cdc","nih-medline"]},{"id":"fever_adult","title":"Fever in an adult","domain":"firstaid","also":["high temperature","running a fever","hot and chills"],"def":"A fever is a body temperature of about 38 C (100.4 F) or higher, usually a sign the body is fighting an infection.","look":["hot skin, chills, sweating, and aches","temperature above 38 C (100.4 F)","stiff neck, rash, confusion, or trouble breathing are red flags"],"use":"Rest, drink fluids, and dress lightly. Over-the-counter fever reducers can help if used as the label says. Watch for signs of getting worse.","not":"Do not give aspirin to children or teens, do not bundle up in heavy covers, and do not ignore a fever that lasts more than a few days.","call":"Call emergency services or get care for a stiff neck, severe headache, confusion, trouble breathing, a fever over 40 C (104 F), or fever with a new rash.","rel":["sepsis_signs","hydration_basics"],"src":["cdc","nih-medline"]},{"id":"vomiting_diarrhea","title":"Vomiting and diarrhea","domain":"firstaid","also":["stomach bug","food poisoning","traveler's diarrhea","gastroenteritis","upset stomach"],"def":"Vomiting and diarrhea are the body's way of clearing a gut infection or toxin; the main danger is dehydration.","look":["frequent loose stools or vomiting","dry mouth, dark urine, dizziness","blood in stool, high fever, or severe belly pain are red flags"],"use":"Rest, take frequent small sips of clean water or oral rehydration solution, and eat bland food when you can. Wash hands carefully and keep clear of food prep.","not":"Do not drink untreated water, and do not give anti-diarrhea medicine to young children or when there is high fever or blood.","call":"Call emergency services or get care for blood, high fever, severe pain, signs of dehydration, an infant, or illness lasting more than a couple of days.","rel":["oral_rehydration","hydration_basics"],"src":["cdc","nih-medline","atp3-50-21"]},{"id":"abdominal_pain_red_flags","title":"Belly pain: when it is urgent","domain":"firstaid","also":["stomach ache","appendicitis","severe stomach pain","belly pain"],"def":"Most belly pain is minor, but pain that is severe, constant, or moving to the lower right can be appendicitis or another emergency.","look":["pain that starts near the navel and moves to the lower right","rigid, tender belly, fever, vomiting","pain with fainting, black stool, or vomiting blood"],"use":"Rest, take nothing by mouth if you may need surgery, and get medical care quickly if pain is severe or getting worse.","not":"Do not give laxatives or heat pads on a painful belly, and do not wait if the pain is severe.","call":"Call emergency services for severe or worsening pain, rigid belly, fever with pain, or pain after an injury.","rel":["internal_bleeding","vomiting_diarrhea"],"src":["nih-medline","cdc"]},{"id":"childbirth_field","title":"Emergency childbirth","domain":"firstaid","also":["baby coming now","giving birth","delivery in the field","woman in labor"],"def":"When a baby is crowning and cannot be reached by help in time, you can support the delivery, keep the baby warm, and wait for emergency services.","look":["contractions a minute or two apart, urge to push","the baby's head is visible","water has broken"],"use":"Call emergency services, put clean towels under her, let her push, and support the baby's head as it emerges. Dry and wrap the baby, place the baby on her chest, and keep both warm.","not":"Do not pull the baby, cut the cord, or pull on the placenta. Do not push the baby back.","call":"Call emergency services right away; stay on the phone with the dispatcher if you can.","rel":["newborn_care","shock_position"],"src":["nih-medline","cdc","atp4-02-11"]},{"id":"newborn_care","title":"Care of a newborn","domain":"firstaid","also":["baby just born","keep a newborn warm","infant born outside"],"def":"A newborn loses heat quickly, so drying, warming, and watching the breathing are the first jobs.","look":["baby cries or breathes within seconds","wet, slippery, and cold skin","blue color or no breathing needs help"],"use":"Dry the baby, wrap in warm dry cloths with the head covered, and hold skin-to-skin against the mother. Keep the face clear and note the time of birth.","not":"Do not slap or shake the baby, do not bathe the baby, and do not cut the cord unless told to by a dispatcher.","call":"Call emergency services; if the baby is not breathing, rub the back firmly and follow the dispatcher.","rel":["childbirth_field","hypothermia_stages"],"src":["nih-medline","cdc"]},{"id":"miscarriage_bleeding","title":"Heavy bleeding in pregnancy","domain":"firstaid","also":["bleeding while pregnant","miscarriage","pregnancy emergency"],"def":"Bleeding, severe pain, or fainting in a pregnant woman can be serious and needs medical help.","look":["vaginal bleeding with cramps or pain","dizzy, pale, faint, or severe one-sided belly pain","fluid leaking or no baby movement late in pregnancy"],"use":"Have her lie down on her left side, keep her warm and calm, and get emergency help. Note how many pads she is soaking.","not":"Do not put anything in the vagina, and do not wait to see if it passes.","call":"Call emergency services for heavy bleeding, severe pain, or fainting.","rel":["shock_position","childbirth_field"],"src":["nih-medline","cdc"]},{"id":"altitude_sickness_levels","title":"Altitude sickness: mild versus dangerous","domain":"firstaid","also":["AMS","HAPE","HACE","mountain sickness","can't breathe at altitude"],"def":"Altitude sickness is an illness from too little oxygen at height; mild forms ease with rest, but fluid on the lungs or brain is life-threatening.","look":["mild: headache, nausea, poor sleep, tiredness","HAPE: breathlessness at rest, wet cough, pink froth","HACE: stumbling, confusion, severe headache"],"use":"Stop climbing, rest, drink water, and descend if symptoms are getting worse. Dangerous forms need immediate descent.","not":"Do not keep going up with symptoms, and do not sleep higher until symptoms clear.","call":"Call emergency services or start descent immediately for breathlessness at rest, confusion, loss of balance, or a wet cough.","rel":["altitude_descend","hydration_basics"],"src":["nps","cdc","nih-medline"]},{"id":"poisoning_swallowed","title":"Swallowed poison or overdose","domain":"firstaid","also":["swallowed something poisonous","child ate pills","drank cleaner","poison control"],"def":"For a swallowed poison, the quickest help is poison control or emergency services, who tell you exactly what to do for that substance.","look":["an opened container, plants, berries, or pills nearby","vomiting, drowsiness, confusion, or burns around the mouth","a child who may have swallowed something"],"use":"Call poison control (US 1-800-222-1222) or emergency services right away, have the container or plant with you, and follow their directions. Keep the person awake and calm.","not":"Do not make the person vomit, give salt water, or give milk or other home remedies unless told to.","call":"Call poison control or emergency services immediately; do not wait for symptoms.","rel":["fainting"],"src":["cdc","nih-medline"]},{"id":"heavy_vs_minor_bleeding","title":"Heavy bleeding versus a minor cut","domain":"firstaid","also":["is the bleeding serious","how bad is the bleeding","bleeding will not stop","bleeding a lot"],"def":"Heavy bleeding is blood that spurts, pools, soaks through cloth, or does not slow after 10 minutes of firm pressure; a minor cut slows and stops with pressure.","look":["spurting, pulsing, or fast flowing blood","blood soaking through several layers or pooling on the ground","person pale, clammy, dizzy, or confused","a minor cut oozes and slows within a few minutes of pressure"],"use":"Put firm direct pressure on the wound: press hard and straight down with a thick pad or both hands and keep pressing. Call 911 for heavy bleeding. If it is a limb and pressure does not control it, put on a tourniquet. For a minor cut, wash, press, and cover.","not":"Do not lift the cloth to check; add more on top. Do not use a tourniquet on a minor cut or on the neck.","call":"Heavy bleeding is urgent: call 911 early and get help on the way for any bleeding that will not stop with firm pressure.","rel":["tourniquet_apply","wound_packing"],"src":["atp4-02-11","cdc"]},{"id":"tourniquet_apply","title":"How to apply a tourniquet","domain":"firstaid","also":["CAT tourniquet","windlass tourniquet","TQ","strap to stop bleeding","tourniquet time"],"def":"A tourniquet is a tight band, ideally a commercial windlass device, and a last resort for life-threatening bleeding from an arm or leg when firm direct pressure has not stopped it.","look":["life-threatening bleeding from an arm or leg","a traumatic amputation","pressure and packing are not controlling it"],"use":"Place the tourniquet 2 to 3 inches (5 to 8 cm) above the wound on bare skin, not over a joint. Pull the strap tight, turn the windlass until the bleeding stops, lock it, and note the time it went on by writing it on the band. If you cannot see the wound or are in a hurry, put it high and tight on the limb. Call 911.","not":"Do not use it for a minor cut, on the neck, chest, or belly, or over a joint, a pocket, or a wallet. Do not loosen it once on; only medical staff do that.","steps":["Call 911 and keep pressing on the wound until the tourniquet is ready.","Slip the band around the limb 2 to 3 inches above the wound, on skin, not over a joint.","Pull the strap as tight as you can and twist the windlass until the bleeding stops.","Lock the windlass in its clip and write the time on the tourniquet.","If bleeding continues, put a second one just above the first and tighten both."],"call":"Call 911; a tourniquet is emergency care, not a replacement for a hospital. Get trained in a Stop the Bleed or first-aid class before you need one.","rel":["heavy_vs_minor_bleeding","tourniquet_bleeding_continues","wound_packing"],"src":["atp4-02-11","stopthebleed"]},{"id":"tourniquet_bleeding_continues","title":"Bleeding continues after a tourniquet","domain":"firstaid","also":["tourniquet not working","still bleeding with tourniquet","second tourniquet","tourniquet too loose"],"def":"If blood keeps flowing after a tourniquet is on, it is usually not tight enough or not high enough, and the fix is to tighten it or add a second one.","look":["blood still flowing or spurting below the band","a pulse can still be felt below it","the band slips or the windlass is loose"],"use":"Tighten the windlass more until the bleeding stops. If it still flows, place a second tourniquet right above the first and tighten it. Pack the wound and press while you wait for help.","not":"Do not remove or loosen the tourniquet to check the wound. Do not wait to ask permission; act and keep calling 911.","call":"Call 911 and stay with the person; check for shock.","rel":["tourniquet_apply","shock_position"],"src":["atp4-02-11"]},{"id":"wound_packing","title":"Packing a wound and pressure dressing","domain":"firstaid","also":["pack the wound","gauze in the wound","hemostatic gauze","wound that tourniquet cannot reach","neck bleeding","armpit bleeding","groin bleeding"],"def":"Packing means pushing gauze or clean cloth deep into a bleeding wound and pressing hard on it; it is used where a tourniquet will not work, such as the neck, armpit, or groin.","look":["deep wound at the neck, armpit, groin, or the top of a limb","blood welling from the depth of the wound","a tourniquet cannot be placed above the wound"],"use":"Push gauze or a clean cloth deep into the wound, right to the bleeding source. Keep packing until it is full, then press down hard with both hands for at least 3 minutes and then hold on with a wrap. Call 911.","not":"Do not use a limb tourniquet on the neck. Do not remove soaked gauze; pack more on top. Do not wrap so tight around the neck that it blocks breathing.","call":"Call 911; deep wounds to the neck, chest, or belly need a hospital.","rel":["pressure_bandage","arterial_bleeding"],"src":["atp4-02-11","stopthebleed"]},{"id":"child_infant_choking","title":"Choking in a child or infant","domain":"firstaid","also":["baby choking","toddler choking","back blows infant","chest thrusts infant"],"def":"For an infant under one year, a choking rescue uses five back blows and five chest thrusts, not abdominal thrusts; a child over one uses abdominal thrusts like an adult.","look":["cannot cry, cough, or breathe, silent or high-pitched noise","blue lips or face","grabbing at the throat in a child"],"use":"Call 911. For an infant, lay the baby face down along your forearm with the head lower than the body and give five back blows, then turn the baby over and give five chest thrusts with two fingers. Repeat until the object comes out or the baby becomes unresponsive. For a child, give abdominal thrusts from behind.","not":"Do not do blind finger sweeps. Do not give abdominal thrusts to an infant. Do not hold an infant upside down by the legs.","call":"Call 911 or your local emergency services; if the child becomes unresponsive, start CPR. Take a pediatric first-aid and CPR class before you need it.","rel":["child_infant_cpr","choking_thrusts"],"src":["atp4-02-11","cdc"]},{"id":"child_infant_cpr","title":"CPR for a child or infant","domain":"firstaid","also":["baby CPR","infant not breathing","child not breathing","rescue breaths for a baby"],"def":"CPR for children and infants keeps blood and oxygen moving; it is similar to adult CPR but uses less force, and breaths matter more because children often stop breathing first.","look":["not breathing or only gasping","limp and unresponsive","blue or gray color"],"use":"Call 911, then push hard and fast in the center of the chest at about 100 to 120 per minute: two fingers for an infant, one or two hands for a child, about one third the depth of the chest. Give two gentle breaths after every 30 compressions. Use an AED with child pads if available.","not":"Do not stop until help or an AED takes over or the child breathes. Do not tilt an infant's head back too far.","call":"Call 911 and follow the dispatcher; take a CPR class so you can do it with confidence.","rel":["cpr_rate_depth","child_infant_choking"],"src":["atp4-02-11","cdc"]},{"id":"aed_use","title":"Using an AED","domain":"firstaid","also":["defibrillator","automated external defibrillator","heart paddles","shock machine"],"def":"An AED is a portable device that checks the heart's rhythm and, if needed, gives a shock; it talks you through each step.","look":["person is unresponsive and not breathing normally","voice prompts after you turn it on","pads show where to be placed on bare chest"],"use":"Call 911, turn on the AED, bare the chest, dry it if wet, and put the pads where the pictures show. Let it analyze and do exactly what it says; keep everyone clear when it shocks, then resume CPR.","not":"Do not touch the person when it says to stand clear, and do not use pads over a medication patch or a pacemaker bump.","call":"Call 911; anyone can use an AED safely.","rel":["cpr_rate_depth","heart_attack_signs"],"src":["atp4-02-11","cdc"]},{"id":"naloxone_overdose","title":"Opioid overdose and naloxone","domain":"firstaid","also":["narcan","overdose","passed out from pills","blue lips pinpoint pupils","fentanyl overdose"],"def":"An opioid overdose slows or stops breathing, and naloxone (Narcan) is a medicine that can reverse it for a short time.","look":["will not wake, slow or stopped breathing","blue or gray lips and skin","pinpoint pupils, gurgling or snoring sounds"],"use":"Call 911 first. If naloxone is on hand, give it as the package directs, start rescue breathing or CPR if not breathing, and put the person on their side if they are breathing. If they wake and then fade, give another dose after two to three minutes.","not":"Do not leave the person alone, and do not assume it has worn off; the drug can outlast the naloxone.","call":"Call 911 even if naloxone works; overdose can return.","rel":["unconscious_person","cpr_rate_depth"],"src":["cdc","nih-medline"]},{"id":"fracture_sprain_dislocation","title":"Broken bone, sprain, or dislocation?","domain":"firstaid","also":["is it broken or sprained","sprain versus fracture","twisted ankle or broken ankle"],"def":"A fracture is a broken bone, a sprain is a stretched or torn ligament, and a dislocation is a joint forced out of place; the field answer is the same: stabilize and get care.","look":["fracture: point pain on the bone, deformity, cannot bear weight","sprain: pain and swelling at a joint, some use possible","dislocation: joint visibly out of place and will not move","numbness or a pale limb beyond the injury is an emergency"],"use":"Stop using the limb, immobilize it in the position found with padding and a splint or sling, and apply a cool pack for swelling. Get X-rays if you cannot walk on it or the pain is intense. For a simple sprain, use rest, a cool pack, gentle compression, and elevation above the heart.","not":"Do not try to straighten a deformity or to pop a joint back in. Do not test it by walking.","call":"Call 911 for an open wound over the break, a limb that is blue, pale, or numb, or a suspected thigh, hip, neck, or back fracture.","rel":["splint_immobilize","sprain_rice"],"src":["atp4-02-11","nih-medline"]},{"id":"infant_hypothermia","title":"Cold baby: infant hypothermia","domain":"firstaid","also":["baby too cold","newborn cold","bright red cold skin baby","low energy baby"],"def":"Babies lose heat fast, and a cold infant may have bright red, cold skin and very low energy, not just shivering.","look":["bright red, cold skin","very low energy, weak cry, or refusing to feed","cool belly and chest in a cool room"],"use":"Take the baby indoors, remove damp clothing, and hold the baby skin to skin under dry blankets, with the head and a hat covered. Warm the room. Get urgent care at once.","not":"Do not use a hot bath, heating pad, or a hot water bottle, and do not put a sleeping baby in a cold car or on a cold floor.","call":"Call 911 or get urgent care now for a cold, limp, or hard-to-wake baby.","rel":["hypothermia_stages"],"src":["cdc","nih-medline"]},{"id":"frostbite_dont","title":"Frostbite: what not to do","domain":"firstaid","also":["rub frostbite","thaw frozen fingers","stove on frostbite","heating pad frostbite"],"def":"Frostbitten skin is numb and easily damaged; rubbing, high heat, or thawing then re-freezing makes it worse.","look":["pale, waxy, hard, or blotchy skin that is numb","tingling and then loss of feeling","blisters after warming"],"use":"Get out of the cold, take off wet gloves and boots, and gently warm the area with warm (not hot) water or body heat, such as fingers in the armpits. Do not walk on frostbitten feet if you can avoid it. Cover loosely and get care.","not":"Do not rub with snow or hands, do not use a stove, fire, heating pad, or hot water, and do not thaw it if it might freeze again.","call":"Get medical care for any frostbite; call 911 for confusion, shivering that stops, or deep, hard, or blackened skin.","rel":["frostbite_warming","wind_chill"],"src":["cdc","atp4-02-11"]},{"id":"cold_water_shock","title":"Cold-water shock and near-drowning","domain":"firstaid","also":["fell through the ice","fell in cold water","capsized","cold shock","cold water immersion"],"def":"Cold-water shock is the gasp and panic in the first minute after falling into very cold water, and it can cause drowning before hypothermia sets in.","look":["a sudden gasp, rapid breathing, and panic","swimming ability lost within minutes","numb hands and arms that will not grip"],"use":"Float and control your breathing for the first minute before you try to swim or climb out. Keep your head up, get out of the water as soon as you can, and then get dry, warm, and into shelter. Anyone rescued should be seen by a clinician.","not":"Do not thrash or try to swim hard right away, and do not go onto the ice to help without a rope or pole.","call":"Call 911 for anyone who was under water or is unresponsive; start CPR if not breathing.","rel":["drowning_rescue"],"src":["nws","cdc"]},{"id":"call_911_dispatcher","title":"Talking to a 911 dispatcher","domain":"firstaid","also":["what to say when I call 911","how to call for help","emergency call","giving my location"],"def":"When you call 911, stay on the line and give your location and what happened; the dispatcher will tell you what to do next.","look":["your exact location, with a road, landmark, or GPS coordinates","what happened and how many people are hurt","whether the person is awake and breathing"],"use":"Call 911, say where you are, and say what happened. Answer the dispatcher's questions, and follow their instructions. Put the phone on speaker so you can help the person while you talk. Do not hang up until they tell you to.","not":"Do not hang up first, and do not assume the call is placed if you have no signal; try text-to-911 or move to a place with signal.","call":"If you have no cell service, try texting 911, move to higher ground, or use the satellite SOS feature of your phone.","rel":["describe_symptoms"],"src":["cdc","fema"]},{"id":"describe_symptoms","title":"Describing symptoms clearly to a clinician","domain":"firstaid","also":["what to tell the doctor","how to explain symptoms","medical history for an emergency crew"],"def":"Clear information helps a clinician decide fast: when it started, what makes it worse or better, what medicines and allergies the person has.","look":["start time and how it began","what makes it better or worse","medicines taken, allergies, and past conditions"],"use":"Write down or say the time it started, the main symptom, any change since, medicines and allergies, and any vital signs. Keep a list of medicines and allergies in your phone or on the family card.","not":"Do not guess at a diagnosis; say what you see and feel.","call":"Call 911 for chest pain, trouble breathing, or any sudden severe symptom.","rel":["call_911_dispatcher","medication_questions"],"src":["cdc","nih-medline"]},{"id":"medication_questions","title":"Medication basics: missed dose, expired, sharing","domain":"firstaid","also":["missed a pill","expired medicine","share a prescription","can I take this with that"],"def":"For a missed dose, an expired medicine, or a drug interaction, read the label and ask a pharmacist; never share prescription drugs.","look":["label directions for a missed dose","an expiration date","a new medicine alongside others"],"use":"Check the label or the pharmacist or Poison Control line for a missed dose, and keep medicines in a cool, dry place. Ask a pharmacist before mixing medicines. Keep a list of what you take.","not":"Do not take someone else's prescription, double up without advice, or use a medicine that looks or smells changed.","call":"Call Poison Control at 1-800-222-1222 or 911 for an overdose or a bad reaction.","rel":["poisoning_swallowed","describe_symptoms"],"src":["fda","cdc","nih-medline"]},{"id":"lyme_signs","title":"Lyme disease signs after a tick bite","domain":"firstaid","also":["bullseye rash","erythema migrans","tick fever","deer tick bite","Lyme"],"def":"Lyme disease is spread by blacklegged (deer) ticks, and an expanding red rash, often with fever, chills, and aches, can appear three to thirty days after a bite.","look":["a red expanding rash, sometimes with a clear center","fever, chills, headache, and tiredness","joint pain or facial droop later","a rash is not always a bullseye"],"use":"Remove the tick with fine-tipped tweezers, clean the bite, and note the date. See a clinician if a rash, fever, or aches follow within about a month, and say you had a tick bite.","not":"Do not use nail polish, heat, or petroleum jelly on a tick, and do not wait for a bullseye.","region":"Blacklegged ticks are common across Maine, Rhode Island and the rest of New England; check yourself, children, and pets after time in leaf litter, brush, and tall grass.","call":"Get care for a rash or fever after a tick bite; call 911 for severe headache, stiff neck, or heart symptoms.","rel":["tick_removal","tick_prevention"],"src":["cdc"]},{"id":"tick_prevention","title":"Preventing tick bites","domain":"firstaid","also":["tick check","permethrin","stay safe from ticks","repellent for ticks"],"def":"Preventing tick bites means covering skin, using repellent, and checking your whole body after being outdoors.","look":["tick season from spring through fall, with nymphs most active in late spring and summer","brush, leaf litter, and tall grass","small ticks the size of a poppy seed"],"use":"Wear long pants tucked into socks, use an EPA-registered repellent or permethrin-treated clothing, walk in the center of trails, and check your body, hair, and gear. Shower within two hours and put clothes in a hot dryer.","not":"Do not rely on one check; look again in the days after.","region":"In Maine and Rhode Island the blacklegged tick is active whenever it is above freezing, not only in summer.","call":"Call a clinician for a tick that was attached for more than a day, or any rash or fever after a bite.","rel":["lyme_signs","tick_removal"],"src":["cdc","epa"]},{"id":"snakebite_new_england","title":"Snakebite in New England","domain":"firstaid","also":["timber rattlesnake","northern copperhead","snake bit me","venomous snake","garter snake bite"],"def":"New England has very few venomous snakes: the timber rattlesnake and the northern copperhead in a few southern areas; most snakes are harmless.","look":["venomous bites leave two puncture marks with swelling and severe pain","timber rattlesnake has a rattle and a heavy body","most bites in New England are from harmless snakes"],"use":"Move away from the snake, stay calm, remove rings and tight items, and keep the bitten limb still at about heart level. Call 911 or get to a hospital; note the time and the snake's appearance if it is safe.","not":"Do not cut the bite, suck it, apply ice or a tourniquet, drink alcohol, or try to catch the snake.","region":"Timber rattlesnakes are rare and protected in parts of New England, and copperheads occur in southern Connecticut and Massachusetts; check state wildlife agency pages for ranges.","call":"Call 911 or go to an emergency room for any bite you think is venomous.","rel":["wound_cleaning"],"src":["cdc","nih-medline","atp4-02-11"]},{"id":"nail_puncture","title":"Nail or tool puncture wound","domain":"firstaid","also":["stepped on a nail","puncture in the foot","deep puncture"],"def":"A puncture wound is narrow and deep, closes quickly, and traps germs, so it can get infected and may need a tetanus shot.","look":["a small hole with little bleeding","pain that gets worse in the next days","redness, swelling, or drainage"],"use":"Let it bleed a little, wash with soap and clean water, and cover. See a clinician the same day for a deep wound, a rusty or dirty object, or a wound in the foot. Ask about a tetanus shot.","not":"Do not seal it with glue or tape, and do not probe it. Do not ignore a puncture through a shoe.","call":"Get care for deep punctures, and for fever, spreading redness, or swelling later.","rel":["tetanus_shot","wound_infection_signs"],"src":["cdc","nih-medline"]},{"id":"high_blood_sugar","title":"High blood sugar (diabetic emergency)","domain":"firstaid","also":["hyperglycemia","diabetic ketoacidosis","very thirsty and frequent urination","fruity breath"],"def":"High blood sugar builds slowly with thirst, frequent urination, tiredness, and fruity breath, and it can become a medical emergency.","look":["extreme thirst and frequent urination","nausea, belly pain, and fast deep breathing","fruity breath and confusion"],"use":"If the person has diabetes, help them follow their own plan and check their blood sugar. Give plain water and get medical help for vomiting, drowsiness, or fast deep breathing.","not":"Do not give sugary drinks if blood sugar is already high, and do not give insulin that is not theirs.","call":"Call 911 for confusion, vomiting, trouble breathing, or unresponsiveness. If you are unsure whether it is high or low and they can swallow, giving sugar is safer.","rel":["low_blood_sugar","hydration_basics"],"src":["cdc","nih-medline"]},{"id":"ear_sinus_pain","title":"Ear or sinus pain after a swim or a cold","domain":"firstaid","also":["swimmer's ear","earache","sinus pressure","ear infection"],"def":"Ear or sinus pain after swimming or a cold is often a mild infection, but severe pain, fever, or discharge needs a clinician.","look":["ear pain that hurts when you pull on it","stuffy nose and pressure around the eyes","fever, drainage, or hearing loss"],"use":"Keep the ear dry, use a warm compress, and take over-the-counter pain medicine as the label says. See a clinician if pain lasts more than a day or two or if there is fever or drainage.","not":"Do not put cotton swabs or objects into the ear, and do not use drops if the eardrum might be torn.","call":"Get care for severe pain, high fever, swelling behind the ear, or dizziness.","rel":["fever_adult","wound_infection_signs"],"src":["nih-medline","cdc"]},{"id":"frostnip_vs_frostbite","title":"Frostnip versus frostbite","domain":"firstaid","also":["cold fingers pale","nose turned white","ears numb"],"def":"Frostnip is a mild cold injury that turns skin pale and numb but is reversible with warming; frostbite is a deeper freeze injury.","look":["frostnip: pale or red skin that tingles and returns to normal when warmed","frostbite: hard, waxy, numb skin that stays white or gray","blisters appear later with deeper injury"],"use":"Get inside or out of the wind, cover the area with a warm dry glove or hand, and warm it gently. If skin stays numb or hard, treat it as frostbite and get care.","not":"Do not rub the skin, and do not use direct heat.","call":"Get care for numb, hard, or blistered skin, and call 911 if the person is confused or very cold.","rel":["frostbite_warming","frostbite_dont"],"src":["cdc","nws"]},{"id":"cpr_when_to_start","title":"When to start CPR","domain":"firstaid","also":["should I do CPR","no pulse","not breathing what do I do","hands only CPR"],"def":"Start CPR for anyone who is unresponsive and not breathing, or only gasping, and call 911 first.","look":["no response to a shout or shoulder tap","not breathing, or only occasional gasps","no obvious signs of life"],"use":"Call 911 or have someone call, push hard and fast in the middle of the chest at 100 to 120 per minute, about 2 inches (5 cm) deep for an adult, and let the chest rise fully. Do not stop until help or an AED takes over.","not":"Do not stop to check for a pulse for long, and do not be afraid of hurting them; chest compressions can save a life. Do not do CPR on someone who is breathing normally.","call":"Call 911, put the phone on speaker, and follow the dispatcher; take a CPR class for hands-on skills.","rel":["cpr_rate_depth","aed_use"],"src":["atp4-02-11","cdc"]},{"id":"hungry_in_woods","title":"Hungry in the woods","domain":"food","also":["I am hungry","no food in the woods","need to eat","starving lost"],"def":"If you are hungry in the woods, eat the food you carried and focus first on water, shelter, warmth, and being found, because a person can go weeks without food but only days without water.","look":["a hunger that feels urgent but is not an emergency","packed food, even small amounts","water, warmth, and signals come first"],"use":"Eat what you carried in small amounts, keep warm and hydrated, and stop to make a plan. Save energy and signal for help. Fish or known foods only if you know how.","not":"Do not start by eating wild plants or mushrooms; mistakes can be deadly.","call":"Call 911 or use satellite SOS if you are lost or hurt.","rel":["plant_safe_positive_id","foraging_false_rules"],"src":["atp3-50-21","ready"]},{"id":"food_danger_zone","title":"Danger zone: 40 to 140 F","domain":"food","also":["how long can food sit out","bacteria grow in food","two hour rule","food temperature danger zone"],"def":"The danger zone is 40 to 140 F (4 to 60 C), where bacteria multiply fast, so perishable food should not stay out more than two hours, or one hour above 90 F.","look":["perishable food left out on a counter or picnic table","food not kept cold in a cooler","hot food that cooled slowly"],"use":"Keep cold food at or below 40 F and hot food at or above 140 F. Put leftovers in the fridge or cooler within two hours (one hour if it is above 90 F). Use ice packs and a thermometer in the cooler.","not":"Do not leave perishable food out for more than two hours, and do not taste it to see whether it is safe.","rel":["food_leftovers_safety","food_safe_cook_temps"],"src":["usda-fsis"]},{"id":"food_safe_cook_temps","title":"Safe minimum cooking temperatures","domain":"food","also":["what temperature to cook chicken","how done should venison be","meat thermometer","ground meat temperature"],"def":"Use a food thermometer: 165 F (74 C) for poultry and leftovers, 160 F (71 C) for ground meats and egg dishes, and 145 F (63 C) for whole cuts of meat and fish with a three-minute rest.","look":["poultry and reheated food: 165 F","ground beef, pork, and ground game: 160 F","whole beef, pork, lamb, venison, and fish: 145 F"],"use":"Insert the thermometer into the thickest part, away from bone, and let the temperature settle. Do not rely on color.","not":"Do not judge doneness by color or juice; ground meat can be brown before it is safe.","rel":["food_danger_zone"],"src":["usda-fsis"]},{"id":"food_leftovers_safety","title":"Are leftovers, picnic food, or cooler food still safe?","domain":"food","also":["is this food still good","leftovers how long","cooler food melted ice","can I eat this"],"def":"Leftovers are safe for three to four days in the fridge and picnic or cooler food is safe only if it stayed at 40 F or below; when in doubt, throw it out.","look":["how long it sat in the danger zone","a cooler with ice still present and food cold","smell is not a reliable test"],"use":"Reheat leftovers to 165 F, keep coolers full of ice or ice packs, and discard perishable food that was out over two hours (one hour above 90 F).","not":"Do not rely on smell or taste; harmful bacteria often do not change them.","rel":["food_danger_zone","food_outage"],"src":["usda-fsis"]},{"id":"food_field_hygiene","title":"Food hygiene in the field","domain":"food","also":["wash hands before eating","keep raw meat separate","clean cutting board outdoors"],"def":"Wash hands and tools, keep raw meat separate from ready-to-eat food, and cook to a safe temperature.","look":["hands washed with soap or sanitizer","separate cutting boards and knives","cooler kept cold"],"use":"Wash hands with soap and treated water before touching food, bag raw meat separately, wash utensils, and keep the cooler in shade.","not":"Do not reuse a plate or knife that touched raw meat without washing.","rel":["food_danger_zone","water_hygiene_scarce"],"src":["usda-fsis","cdc"]},{"id":"food_outage","title":"Food in the fridge and freezer during an outage","domain":"food","also":["power outage food","how long does a fridge stay cold","freezer without power","throw out food"],"def":"A closed refrigerator keeps food safe about 4 hours without power; a full freezer holds for about 48 hours (24 if half full) if the door stays shut.","look":["a thermometer in the fridge at 40 F or below","ice crystals still in the freezer food","a cooler with ice for backup"],"use":"Keep doors closed, group food together, use ice or dry ice carefully, and check temperatures. Discard perishable food above 40 F for more than two hours.","not":"Do not taste food to test it, and do not refreeze food that fully thawed.","rel":["power_out_safety","food_danger_zone"],"src":["usda-fsis","cdc","ready"]},{"id":"jerky_drying_meat","title":"Making jerky safely","domain":"food","also":["dry meat","venison jerky","dehydrating meat"],"def":"Safe jerky starts with heating the meat to a safe internal temperature before or during drying, and the drying alone does not kill bacteria.","look":["lean meat sliced thin","heat to 160 F (71 C), poultry to 165 F, then dry at 130 to 140 F (54 to 60 C)","a dry, leathery finish that bends but does not break"],"use":"Follow USDA guidance: marinate in the fridge, steam or oven-heat to the right internal temperature, then dry. Store in a cool dry place.","not":"Do not rely on drying alone or dry at too low a temperature.","rel":["food_safe_cook_temps"],"src":["usda-fsis"]},{"id":"home_canning_safe","title":"Home canning: pressure canner for meat and vegetables","domain":"food","also":["canning venison","botulism","low-acid canning","pressure canner"],"def":"Low-acid foods such as meat and vegetables must be canned in a pressure canner following the USDA guide, because boiling-water canning cannot make them safe from botulism.","look":["a pressure canner with a tested gauge","a bulging lid, spurting liquid, or a bad smell","USDA tested processing times"],"use":"Follow the USDA Complete Guide to Home Canning for your food, jar size, and altitude. Check each jar seal before storage.","not":"Do not taste food from a jar that bulges, leaks, or smells off; throw it away carefully.","call":"Call 911 for double vision, drooping eyelids, or trouble swallowing or breathing after eating home-canned food.","rel":["food_danger_zone","jerky_drying_meat"],"src":["usda-canning","usda-fsis"]},{"id":"food_allergies","title":"Allergies to wild or familiar foods","domain":"food","also":["food allergy outdoors","allergic reaction to nuts","epinephrine on a trip"],"def":"Food allergies can cause hives, swelling, or trouble breathing within minutes; carry any prescribed epinephrine and tell your group.","look":["hives, swelling of the lips or tongue, wheezing","vomiting or dizziness after eating","exposure to a known allergen"],"use":"Know your allergens, tell your group, carry medicine, and avoid new wild foods. Use epinephrine as prescribed and call 911.","not":"Do not try a wild food if you have a known allergy.","call":"Call 911 for any signs of a severe reaction.","rel":["anaphylaxis_signs","epinephrine_auto"],"src":["cdc","nih-medline"]},{"id":"fish_cleaning_spoilage","title":"Cleaning fish and spoilage signs","domain":"food","also":["how to clean a fish","is the fish bad","fish smell"],"def":"Gut and chill fish quickly; cook it to 145 F; spoiled fish smells sour, feels slimy, and has cloudy eyes.","look":["fresh: clear eyes, firm flesh, mild smell","spoiled: sour smell, slime, sunken or cloudy eyes","check state fish consumption advisories"],"use":"Gut the fish soon after catching, keep it on ice, wash your hands, and cook it to 145 F. Check the state health department's fish advisories for mercury and other contaminants.","not":"Do not eat fish that smells off, and do not leave it in the sun.","region":"Maine and Rhode Island post fish consumption advisories; check them before you eat what you catch.","rel":["food_danger_zone","food_safe_cook_temps"],"src":["usda-fsis","cdc"]},{"id":"shellfish_closures","title":"Shellfish closures and red tide","domain":"food","also":["clams closed","paralytic shellfish poisoning","red tide","mussels safe"],"def":"Shellfish can carry toxins from algal blooms, and cooking does not remove them, so follow the official closure notices.","look":["a posted closure or red tide notice","numbness around the mouth after eating shellfish","state marine resources pages"],"use":"Check the state shellfish closure page before you harvest; if you cannot confirm that the area is open, do not eat shellfish from it.","not":"Do not rely on cooking or on the look of the water.","region":"Maine DMR and Rhode Island DEM post closure notices; link, never guess.","call":"Call 911 for numbness, weakness, or trouble breathing after eating shellfish.","rel":["fish_cleaning_spoilage","poisoning_swallowed"],"src":["cdc","state-regs-link"]},{"id":"poison_hemlock","title":"Poison hemlock","domain":"foraging","also":["Conium maculatum","poison parsley","tall white umbrella flower","hemlock plant"],"def":"Poison hemlock is a deadly poisonous plant in the carrot family, often mistaken for wild carrot, parsley, or parsnip.","look":["smooth, hairless, hollow stalk with purple blotches","fern-like, finely divided leaves that smell musty when crushed","clusters of small white flowers in umbrella shapes, up to 6 to 10 feet tall"],"use":"Use this entry for identification and warnings only. Treat every wild carrot-family plant as dangerous unless an expert has confirmed it, and keep children and pets away.","not":"Never eat, brew, or taste any part, and do not rely on boiling to make it safe.","alike":["Wild carrot (Queen Anne's lace): hairy stem, carrot-smelling root, not blotched","Water hemlock: grows in wet ground, with chambered roots and veins running to leaf notches","Fool's parsley and wild parsnip: also unpleasant or harmful; do not guess"],"region":"Poison hemlock is established across much of New England along roadsides, ditches, and field edges.","call":"If someone may have eaten it, call 911 if they are very sick or Poison Control at 1-800-222-1222; do not wait for symptoms.","rel":["wild_carrot_lookalike","water_hemlock"],"src":["atp3-50-21","nih-medline","poison-control"]},{"id":"wild_carrot_lookalike","title":"Wild carrot (Queen Anne's lace)","domain":"foraging","also":["Daucus carota","Queen Anne's lace","bird's nest flower","wild carrot"],"def":"Wild carrot is a common white umbrella wildflower with hairy stems and a carrot-smelling root, and it is easy to confuse with deadly hemlocks.","look":["hairy, solid stems","carrot smell from a crushed root or leaf","flat white flower head, sometimes with a single dark center floret, curling into a bird's nest when seeding"],"use":"Use it only as an identification lesson. A beginner should not eat any carrot-family plant from the wild.","not":"Do not eat it unless you can positively tell it from poison hemlock and water hemlock; a carrot smell alone is not enough when guessing.","alike":["Poison hemlock: smooth, hairless, purple-blotched hollow stems; musty smell","Water hemlock: wet ground, chambered roots","Giant hogweed and wild parsnip: sap can cause severe skin burns in sunlight"],"call":"If someone may have eaten a hemlock, call 911 if very sick, or Poison Control at 1-800-222-1222.","rel":["poison_hemlock","water_hemlock"],"src":["atp3-50-21","poison-control"]},{"id":"water_hemlock","title":"Water hemlock","domain":"foraging","also":["Cicuta maculata","spotted water hemlock","cowbane","deadly umbrella plant in wet ground"],"def":"Water hemlock is one of the most poisonous plants in North America; a small amount of the root can cause fatal seizures.","look":["grows in wet ground: stream banks, ditches, marshes","smooth hollow stems streaked or spotted with purple","doubly compound leaves with toothed leaflets whose veins run to the notches","a chambered root that oozes yellowish liquid when cut"],"use":"Use only as a warning. Stay out of wet-ground carrot-family plants.","not":"Never eat, taste, or handle the roots, and do not use it for a whistle or a straw.","alike":["Wild carrot and poison hemlock: also in the carrot family","Wild parsnip and angelica: similar flowers and leaves","Edible-looking tubers or roots in wet ground: never eat them from the wild"],"call":"Call 911 immediately for any ingestion; seizures can start within an hour.","rel":["poison_hemlock","wild_carrot_lookalike"],"src":["atp3-50-21","poison-control"]},{"id":"poison_ivy_id","title":"Poison ivy","domain":"foraging","also":["leaves of three","Toxicodendron radicans","hairy rope vine","itchy vine","three leaf plant"],"def":"Poison ivy is a common plant of New England with three-leaflet leaves and an oil, urushiol, that causes an itchy, blistering rash on contact.","look":["three leaflets, with the middle leaflet on a longer stalk","grows as a vine with hairy aerial roots, a shrub, or ground cover","leaves shiny or dull, edges smooth or notched, red in fall; white berries"],"use":"Wash skin and clothing within minutes of contact and keep from touching your face. Learn it by sight, and look before you touch brush.","not":"Never burn it; the smoke can injure the lungs. Do not pet a dog that has been in it without washing the coat.","alike":["Virginia creeper: five leaflets","Box elder seedlings: leaflets in threes but opposite branching","Wild raspberry and blackberry: thorny stems","Poison sumac: swamp shrub with 7 to 13 leaflets"],"region":"Poison ivy is abundant in New England woods, edges, and dunes; poison oak does not occur there.","call":"Get care for a rash on the face or genitals, over much of the body, or with swelling or trouble breathing.","rel":["poison_ivy_rash","poison_sumac"],"src":["nih-medline","cdc","atp3-50-21"]},{"id":"poison_sumac","title":"Poison sumac and poison oak","domain":"foraging","also":["Toxicodendron vernix","poison oak","swamp sumac","white berries sumac"],"def":"Poison sumac is a swamp shrub with 7 to 13 smooth-edged leaflets and white berries; it causes the same rash as poison ivy.","look":["leaves of 7 to 13 smooth leaflets on a red stem","grows in wet swamps and bogs","drooping clusters of white-gray berries"],"use":"Stay out of swamp shrubs you cannot name, and wash after contact like poison ivy.","not":"Never burn it, and do not confuse it with harmless red-berried staghorn sumac.","alike":["Staghorn sumac: upright red berry cones, toothed leaflets, dry ground","Poison ivy: three leaflets, vine or shrub","Poison oak: a western and southeastern plant, not in New England"],"call":"Get care for a severe, facial, or widespread rash.","rel":["poison_ivy_id","poison_ivy_rash"],"src":["nih-medline","cdc"]},{"id":"mushrooms_never_from_photo","title":"Never eat a wild mushroom from a photo","domain":"foraging","also":["can I eat this mushroom","is this mushroom edible","mushroom identification app","identify a mushroom"],"def":"A photo, an app, or a camera match can never confirm a wild mushroom is safe; deadly species resemble edible ones, and cooking does not remove most toxins.","look":["many deadly species look like edible ones","key features like spore print, base, and habitat do not show in a photo","apps and AI make mistakes"],"use":"If you want to forage, learn from a local expert or a mycological society, and have every mushroom confirmed in person. If you are hungry and in trouble, use packed food and do not experiment.","not":"Do not eat any wild mushroom from a photo, an app, a color rule, or a taste test, and do not give one to a child or pet.","call":"Call Poison Control at 1-800-222-1222, or 911 if very sick, for any wild mushroom eaten by mistake; keep a sample.","rel":["amanita_death_cap","jack_o_lantern_mushroom"],"src":["atp3-50-21","poison-control","nih-medline"]},{"id":"jack_o_lantern_mushroom","title":"Jack-o'-lantern mushroom (not a chanterelle)","domain":"foraging","also":["Omphalotus illudens","orange poisonous mushroom","false chanterelle","orange mushroom on a stump"],"def":"The Jack-o'-lantern is an orange, poisonous mushroom that grows in clusters on wood and causes severe vomiting and cramps; it is often mistaken for a chanterelle.","look":["orange, funnel-shaped caps growing in clusters from wood or buried roots","true, thin, sharp-edged gills running down the stem","grows on stumps or at the base of trees"],"use":"Use as a warning example. If you find an orange mushroom, leave it, and do not eat anything you cannot confirm with an expert.","not":"Do not eat any orange mushroom, and do not think a color or a glow in the dark confirms it.","alike":["Chanterelle: single, from soil, blunt forked ridges (false gills), apricot smell, solid white flesh","Orange grocery produce and signs: not mushrooms; Yehsa does not identify them","Other orange mushrooms: do not guess"],"region":"Jack-o'-lanterns are common in the eastern US in late summer and fall, on stumps and oak roots.","call":"Call Poison Control at 1-800-222-1222 for any ingestion; call 911 if severely ill.","rel":["chanterelle_vs_lookalikes","mushrooms_never_from_photo"],"src":["poison-control","nih-medline"]},{"id":"chanterelle_vs_lookalikes","title":"Chanterelle and its look-alikes","domain":"foraging","also":["Cantharellus","golden chanterelle","false chanterelle","chanterelles in New England"],"def":"True chanterelles are golden, funnel-shaped mushrooms with blunt, forked ridges instead of thin gills, but only an expert should confirm them.","look":["blunt, forked ridges that run down the stem and look like folds","grows from soil near trees, usually singly or scattered","fruity, apricot-like smell and solid white flesh inside"],"use":"Learn them in person with a local expert or society, never from a photo.","not":"Do not eat one that grows in dense clusters on wood, has thin sharp gills, or that you are not certain of.","alike":["Jack-o'-lantern: clusters on wood, thin true gills","False chanterelle (Hygrophoropsis): thin, orange, forked true gills","Other orange mushrooms: do not guess"],"call":"Call Poison Control at 1-800-222-1222 for any mistake; call 911 if very sick.","rel":["jack_o_lantern_mushroom","mushrooms_never_from_photo"],"src":["poison-control"]},{"id":"amanita_death_cap","title":"Destroying angel and death cap (deadly amanitas)","domain":"foraging","also":["Amanita bisporigera","Amanita phalloides","death cap","destroying angel","white mushroom in the woods"],"def":"Destroying angels and death caps are deadly mushrooms; a small bite can destroy the liver, and symptoms may be delayed for hours.","look":["white or greenish cap with white gills","a skirt-like ring on the stem and a cup or sac (volva) at the base, which may be buried","white spore print"],"use":"Use as a warning: do not eat white woodland mushrooms, and dig, never cut, if you are learning with an expert.","not":"Do not eat any mushroom with white gills, a ring, and a swollen base. A white 'button' in the woods is not a grocery mushroom.","alike":["Grocery button mushrooms: pink to brown gills, no cup at the base","Edible puffballs: solid white inside, no gills or stem outline","Other white Amanita: all may be poisonous"],"region":"Amanita species and the introduced death cap occur in New England woodlands, often near oaks and pines.","call":"Call 911 or Poison Control at 1-800-222-1222 at once; stomach pain may pass, but the liver may fail days later.","rel":["mushrooms_never_from_photo","jack_o_lantern_mushroom"],"src":["poison-control","nih-medline"]},{"id":"eaten_poison_plant_what_to_do","title":"Someone may have eaten a poisonous plant or mushroom","domain":"foraging","also":["ate a wild plant","child ate a berry","ate a mushroom and sick","pet ate a mushroom"],"def":"If someone may have eaten a poisonous plant or mushroom, call Poison Control or 911 immediately, before symptoms appear.","look":["any wild plant or mushroom swallowed by a child or pet","vomiting, belly pain, drooling, confusion, or seizures","delayed symptoms hours later with deadly mushrooms"],"use":"Call 911 if the person is very sick, unresponsive, or having a seizure; otherwise call Poison Control at 1-800-222-1222. Keep a sample or a photo and note the time and amount. Rinse the mouth and keep the person calm.","not":"Do not make the person vomit, and do not wait for symptoms or a plant-ID app.","call":"Call 911 or Poison Control at 1-800-222-1222 right away; for pets call a veterinarian or a pet poison line.","rel":["poisoning_swallowed","mushrooms_never_from_photo"],"src":["poison-control","cdc"]},{"id":"plant_safe_positive_id","title":"Is this plant safe to eat?","domain":"foraging","also":["can I eat this plant","is this berry safe","wild plant edible","hungry and found a plant"],"def":"A wild plant is only safe to eat when a person has positively identified it by several features and ruled out its poisonous look-alikes; if you are unsure, the answer is no.","look":["more than one feature checked: leaf, flower, fruit, stem, habitat","look-alikes ruled out","legal to harvest where you are"],"use":"Use food you carried first. If you want to learn foraging, go with a local expert, use a regional guide, and start with the few plants that have no deadly look-alikes.","not":"Do not eat unknown plants, do not use a camera or app as a yes, and do not use a taste test.","call":"Call Poison Control at 1-800-222-1222 for any mistaken ingestion.","rel":["foraging_false_rules","eaten_poison_plant_what_to_do"],"src":["atp3-50-21","poison-control"]},{"id":"foraging_false_rules","title":"False rules about wild food","domain":"foraging","also":["universal edibility test","animals eat it so it is safe","red berries rule","boiling removes poison","taste test","color rule"],"def":"Rules of thumb such as 'animals eat it', 'boiling makes it safe', or 'avoid red plants' are false and have killed people.","look":["animals can eat plants that poison people","boiling does not destroy many toxins","berry color is not a safety rule"],"use":"Do not use a universal edibility test for unknown plants. In a real emergency, focus on water, shelter, and signaling; people can go weeks without food.","not":"Do not rely on color, taste, smell, animal behavior, or cooking.","call":"Call Poison Control at 1-800-222-1222 for any mistake.","rel":["plant_safe_positive_id","hungry_in_woods"],"src":["atp3-50-21","poison-control"]},{"id":"toxic_berries_new_england","title":"Toxic berries and fruits in New England","domain":"foraging","also":["baneberry","doll's eyes","pokeweed berries","nightshade","yew berries","virginia creeper berries"],"def":"Several New England berries are poisonous, including baneberry, pokeweed, bittersweet nightshade, yew, and Virginia creeper.","look":["baneberry: white or red berries with a dark dot on stalks","pokeweed: dark purple berries on pink stems","bittersweet nightshade: red egg-shaped berries on a vine","yew: red cup-shaped fruit with a toxic seed"],"use":"Teach children not to eat any wild berry, and keep these plants out of reach. Leave unknown berries alone.","not":"Do not eat unknown berries or pokeweed, and do not use berry color as a rule.","alike":["Blueberries and blackberries: well-known edibles with a crown on blueberries","Wild raspberries: hollow when picked, thorny canes","Do not guess; confirm in person"],"call":"Call Poison Control at 1-800-222-1222 for any berry eaten by mistake.","rel":["berries_edible_new_england","plant_safe_positive_id"],"src":["poison-control","atp3-50-21"]},{"id":"berries_edible_new_england","title":"Blueberries, blackberries, and raspberries","domain":"foraging","also":["wild blueberries","blackberries","raspberry canes","wild berries Maine"],"def":"Wild blueberries, blackberries, and raspberries are common New England fruits with few dangerous look-alikes, but always confirm them in person.","look":["blueberry: small blue berry with a five-pointed crown on the end","blackberry and raspberry: clusters of tiny drupelets on thorny canes; raspberries pull off hollow","grows in sunny clearings, edges, and bogs"],"use":"Pick only fruits you recognized in person, wash them, and pick where it is legal and where there is no spray.","not":"Do not eat berries that do not match all features, and do not pick on private land without permission.","alike":["Bittersweet nightshade: red egg-shaped berries on a vine","Pokeweed: purple berries on pink stems","Baneberry: white or red berries with dots"],"region":"Wild lowbush blueberry barrens are a Maine specialty; check the land rules before you pick.","call":"Call Poison Control at 1-800-222-1222 for mistaken ingestion.","rel":["toxic_berries_new_england","plant_safe_positive_id"],"src":["atp3-50-21","poison-control"]},{"id":"morel_true_vs_false","title":"True morel versus false morel","domain":"foraging","also":["Morchella","false morel","Gyromitra","brain mushroom","morel hunting"],"def":"True morels have a honeycomb cap attached to a hollow stem, while false morels have a wrinkled, brain-like cap and cottony or chambered inside and can be toxic.","look":["true morel: pitted honeycomb cap, hollow from tip to base when cut lengthwise","false morel: wrinkled, lobed cap that hangs free, with cottony or chambered interior","grows in spring under trees"],"use":"Have an expert show you in person, and cut every specimen in half lengthwise. Cook any morel thoroughly; never eat raw.","not":"Do not eat a morel-like mushroom whose inside is not fully hollow, and do not eat it raw.","alike":["False morel (Gyromitra): toxic, cap hangs free","Half-free morel: edible but easy to confuse"],"call":"Call Poison Control at 1-800-222-1222 after a mistaken ingestion.","rel":["mushrooms_never_from_photo","amanita_death_cap"],"src":["poison-control","atp3-50-21"]},{"id":"fiddleheads_ostrich_fern","title":"Fiddleheads (ostrich fern)","domain":"foraging","also":["fiddlehead fern","ostrich fern","bracken fern","edible ferns"],"def":"Fiddleheads are the coiled young fronds of the ostrich fern, a spring food in Maine; they must be identified correctly and cooked thoroughly or they can cause illness.","look":["a smooth stem with a deep U-shaped groove on the inside","brown papery scales on the coil","grows in clumps of about three from a single crown, near rivers"],"use":"Learn them in person, pick small amounts, rinse off the brown scales, and cook thoroughly per public-health guidance (boil about 15 minutes or steam 10 to 12). If you are unsure, skip them.","not":"Do not eat them raw or undercooked, and do not eat other fern species.","alike":["Bracken fern: hairy stem with no deep groove, not recommended","Cinnamon fern: woolly coil with hairs","Other ferns: do not eat"],"region":"Maine and the Northeast have a spring fiddlehead season along rivers; check state rules on harvest on public land.","call":"Get care for vomiting or diarrhea after eating fiddleheads.","rel":["plant_safe_positive_id","mushrooms_never_from_photo"],"src":["cdc","atp3-50-21"]},{"id":"acorns_leaching","title":"Acorns need proper leaching","domain":"foraging","also":["eat acorns","acorn flour","tannins in acorns","white oak acorns"],"def":"Acorns are high in tannins that taste bitter and upset the stomach, so they must be shelled, ground, and leached in many changes of water before use.","look":["bitter, astringent taste when raw","white oak acorns have less tannin","process with a sourced method only"],"use":"If you want to use acorns, follow a sourced method and expect hours of leaching. In a survival situation, they are not a first food.","not":"Do not eat acorns raw or with a short soak.","rel":["wild_nuts_new_england","hungry_in_woods"],"src":["atp3-50-21"]},{"id":"wild_nuts_new_england","title":"Wild nuts: hazelnut, beechnut, walnut, butternut","domain":"foraging","also":["nuts you can eat","black walnut","butternut","beechnut","hickory"],"def":"Hazelnuts, beechnuts, hickory nuts, black walnuts, and butternuts are native New England nuts, but they need positive identification and proper processing.","look":["each tree has distinct leaves, bark, and husk","black walnut and butternut have thick, stain-prone husks","many nuts need drying and shelling"],"use":"Identify the tree in person, check for allergies, shell and eat only sound nuts.","not":"Do not eat moldy or discolored nuts, and do not eat a nut unless you know the tree.","region":"Butternut is threatened by canker and is protected in some places; check local rules.","rel":["acorns_leaching","plant_safe_positive_id"],"src":["atp3-50-21","usfs"]},{"id":"cattail_lookalikes","title":"Cattail and its look-alikes","domain":"foraging","also":["Typha","bulrush","cattail shoots","wild iris lookalike"],"def":"Cattails are tall wetland plants with brown sausage-shaped spikes, but young shoots can be confused with poisonous wild iris.","look":["brown cylindrical flower spike above long flat leaves","grows in standing water or marshes","young shoots smell like cucumber, not musty"],"use":"Learn them with an expert; cattails absorb pollutants, so use only from clean water.","not":"Do not eat anything from polluted water, and do not eat a plant you cannot tell from iris.","alike":["Wild iris (blue flag): flat, blue-green fans, no spike, toxic","Other marsh plants: do not guess"],"call":"Call Poison Control at 1-800-222-1222 for a mistaken ingestion.","rel":["plant_safe_positive_id","water_hemlock"],"src":["atp3-50-21","poison-control"]},{"id":"dandelion_greens","title":"Dandelion and plantain greens","domain":"foraging","also":["dandelion","edible weeds","plantain leaves"],"def":"Dandelion and broadleaf plantain are common lawn and field weeds that can be eaten as greens when picked from clean, unsprayed places.","look":["dandelion: toothed rosette leaves and a single hollow stem with one yellow flower","plantain: oval ribbed leaves in a rosette with a spike of seeds","picked far from roads, pets, and chemicals"],"use":"Pick young leaves from clean, unsprayed ground, wash them, and cook or eat as a small addition, not as free calories.","not":"Do not pick from roadsides, treated lawns, or dog areas.","alike":["Cat's ear and hawkweed: look similar and are less well studied","Other rosette plants: confirm in person"],"rel":["plant_safe_positive_id"],"src":["atp3-50-21","usda-nrcs"]},{"id":"poison_contact_eating_smoke","title":"Plants that poison by contact, eating, or smoke","domain":"foraging","also":["giant hogweed","wild parsnip burns","stinging nettle","poisonous plants overview"],"def":"Plants can harm by contact (poison ivy, wild parsnip, giant hogweed), by eating (hemlocks, baneberry), or by smoke (burning poison ivy).","look":["wild parsnip and giant hogweed sap causes burns in sunlight","poison ivy oil causes a rash","hemlocks and baneberry are poisonous when eaten"],"use":"Learn the plants of your area, wear long sleeves and gloves in brush, and wash exposed skin after contact. Keep children and pets from unknown plants.","not":"Do not burn unknown brush, and do not touch sap from large umbrella plants without gloves.","region":"Giant hogweed and wild parsnip occur in New England; avoid contact with their sap and sunlight.","call":"Call 911 for trouble breathing or severe reactions; call Poison Control at 1-800-222-1222.","rel":["poison_ivy_id","poison_hemlock"],"src":["cdc","nih-medline"]},{"id":"fly_agaric","title":"Fly agaric","domain":"fungi","also":["Amanita muscaria","red mushroom with white spots","toadstool"],"def":"Fly agaric is a red or orange Amanita mushroom with white warts that is poisonous and related to the deadly Amanitas.","look":["red or orange cap with white warts, white gills, a ring on the stem and a bulb at the base","warts are remnants of a veil and can wash off in rain","grows on the ground under birch and conifers"],"use":"Learn it as a warning. Toxic. Related to the deadly Amanitas.","not":"Never eat a wild mushroom from a photo, an app, or this note. Spore prints, cutting it open, and an expert in person come first, and even then some look-alikes kill.","alike":["Death cap: Olive-green to pale cap, white gills, a skirt-like ring and a cup (volva) at the base. One cap can kill. Symptoms start many hours later, after which it is already working on the liver","Destroying angel: Pure white cap, gills, ring and stem, with a cup at the base that may be buried. Deadly. Looks like button mushrooms and young puffballs"],"call":"If someone may have eaten it, call Poison Control at 1-800-222-1222, or 911 for trouble breathing, seizures, or collapse.","rel":["amanita_death_cap"],"src":["poison-control","usfs","nih-medline"],"ask":"Tell me about fly agaric"},{"id":"deadly_galerina","title":"Deadly galerina","domain":"fungi","also":["Galerina marginata","funeral bell","autumn skullcap"],"def":"Deadly galerina is a small brown mushroom on rotting wood that contains the same liver toxins as the death cap.","look":["small brown mushroom on rotting wood with a thin ring and rusty brown spores","cap 1 to 4 cm, sticky when wet","rusty brown spore print"],"use":"Learn it as a warning. Deadly. Grows on the same logs as honey mushrooms.","not":"Never eat a wild mushroom from a photo, an app, or this note. Spore prints, cutting it open, and an expert in person come first, and even then some look-alikes kill.","alike":["Honey mushroom: Clusters of honey-coloured caps on wood with a ring; white spores. The deadly galerina looks like it"],"call":"If someone may have eaten it, call Poison Control at 1-800-222-1222, or 911 for trouble breathing, seizures, or collapse.","rel":["honey_mushroom"],"src":["poison-control","usfs","nih-medline"],"ask":"Tell me about deadly galerina"},{"id":"webcaps","title":"Webcaps (Cortinarius)","domain":"fungi","also":["Cortinarius","cortinarius","webcap"],"def":"Webcaps are brown Cortinarius mushrooms with a cobweb veil, and some damage the kidneys days after eating.","look":["rusty-brown spores, a web-like veil on young caps, often on the ground in woods","rusty-brown spore print","cobweb-like veil between cap edge and stem on young caps"],"use":"Learn it as a warning. Some are deadly to the kidneys. Never eat a brown mushroom you cannot identify.","not":"Never eat a wild mushroom from a photo, an app, or this note. Spore prints, cutting it open, and an expert in person come first, and even then some look-alikes kill.","alike":["Chanterelle: Golden or orange funnel with blunt forked ridges that run down the stem, not true gills; fruity smell. Jack-o'-lantern has true gills, grows in clusters on wood and is toxic"],"call":"If someone may have eaten it, call Poison Control at 1-800-222-1222, or 911 for trouble breathing, seizures, or collapse.","rel":["chanterelle_vs_lookalikes"],"src":["poison-control","usfs","nih-medline"],"ask":"Tell me about webcaps"},{"id":"chicken_of_the_woods","title":"Chicken of the woods","domain":"fungi","also":["Laetiporus","sulphur shelf","chicken mushroom","Laetiporus sulphureus"],"def":"Chicken of the woods is a bright orange and yellow shelf fungus on trees with pores, not gills.","look":["bright orange and yellow shelves with no gills on trees, soft when young","no gills; tiny pores underneath","overlapping shelves on oak or other hardwood"],"use":"Use it as an identification and look-alike lesson; only an expert who sees it in person can confirm it. Some people react badly, and growths on conifers or eucalyptus can be harmful.","not":"Never eat a wild mushroom from a photo, an app, or this note. Spore prints, cutting it open, and an expert in person come first, and even then some look-alikes kill.","call":"If someone may have eaten it, call Poison Control at 1-800-222-1222, or 911 for trouble breathing, seizures, or collapse.","src":["poison-control","usfs","nih-medline"],"ask":"Tell me about chicken of the woods"},{"id":"hen_of_the_woods","title":"Hen of the woods (maitake)","domain":"fungi","also":["maitake","Grifola frondosa","sheep's head"],"def":"Hen of the woods is a large gray-brown clustered mushroom at the base of oaks, with pores instead of gills.","look":["big clump of grey-brown overlapping fronds at the base of oaks","pores instead of gills","many small spoon-shaped caps in one clump","grows at the base of oaks in fall"],"use":"Use it as an identification and look-alike lesson; only an expert who sees it in person can confirm it.","not":"Never eat a wild mushroom from a photo, an app, or this note. Spore prints, cutting it open, and an expert in person come first, and even then some look-alikes kill.","call":"If someone may have eaten it, call Poison Control at 1-800-222-1222, or 911 for trouble breathing, seizures, or collapse.","src":["poison-control","usfs","nih-medline"],"ask":"Tell me about hen of the woods"},{"id":"giant_puffball","title":"Puffball","domain":"fungi","also":["puffball","Calvatia","puffballs","Calvatia gigantea"],"def":"A giant puffball is a round white mushroom with no stem or gills that is solid white inside when young.","look":["round white ball with no stem or gills","solid white inside when cut","no stem and no gills","solid, pure white inside when young"],"use":"Use it as an identification and look-alike lesson; only an expert who sees it in person can confirm it. A young Amanita looks like a puffball. Cut it open: any outline of a cap and stem means leave it.","not":"Never eat a wild mushroom from a photo, an app, or this note. Spore prints, cutting it open, and an expert in person come first, and even then some look-alikes kill.","alike":["Death cap: Olive-green to pale cap, white gills, a skirt-like ring and a cup (volva) at the base. One cap can kill. Symptoms start many hours later, after which it is already working on the liver","Destroying angel: Pure white cap, gills, ring and stem, with a cup at the base that may be buried. Deadly. Looks like button mushrooms and young puffballs"],"call":"If someone may have eaten it, call Poison Control at 1-800-222-1222, or 911 for trouble breathing, seizures, or collapse.","rel":["amanita_death_cap"],"src":["poison-control","usfs","nih-medline"],"ask":"Tell me about puffball"},{"id":"lions_mane","title":"Lion's mane","domain":"fungi","also":["Hericium","bearded tooth","pom pom mushroom"],"def":"Lion's mane is a white mushroom of hanging icicle-like spines that grows on hardwood trees.","look":["white hanging icicle-like spines on trees","no cap and no gills","grows from wounds on beech, maple, or oak"],"use":"Use it as an identification and look-alike lesson; only an expert who sees it in person can confirm it.","not":"Never eat a wild mushroom from a photo, an app, or this note. Spore prints, cutting it open, and an expert in person come first, and even then some look-alikes kill.","call":"If someone may have eaten it, call Poison Control at 1-800-222-1222, or 911 for trouble breathing, seizures, or collapse.","src":["poison-control","usfs","nih-medline"],"ask":"Tell me about lion's mane"},{"id":"oyster_mushroom","title":"Oyster mushroom","domain":"fungi","also":["Pleurotus","oyster mushrooms","tree oyster","Pleurotus ostreatus"],"def":"The oyster mushroom is a gray-tan shelf mushroom on wood with gills running down to a short side stem.","look":["shelf-shaped grey-tan caps with gills running down to a short side stem, on wood","white to lilac spore print","grows in overlapping shelves on dead hardwood"],"use":"Use it as an identification and look-alike lesson; only an expert who sees it in person can confirm it. Do not confuse it with other shelf fungi that have gills.","not":"Never eat a wild mushroom from a photo, an app, or this note. Spore prints, cutting it open, and an expert in person come first, and even then some look-alikes kill.","alike":["Jack-o'-lantern: Orange clusters on wood or buried roots with true gills that run down the stem; glows faintly in the dark. Toxic. Causes severe vomiting"],"call":"If someone may have eaten it, call Poison Control at 1-800-222-1222, or 911 for trouble breathing, seizures, or collapse.","rel":["jack_o_lantern_mushroom"],"src":["poison-control","usfs","nih-medline"],"ask":"Tell me about oyster mushroom"},{"id":"turkey_tail","title":"Turkey tail","domain":"fungi","also":["Trametes versicolor","turkey tails"],"def":"Turkey tail is a thin, tough shelf fungus on dead wood with colored bands and white pores underneath.","look":["thin tough shelves with colored concentric bands and a white pore underside","tough and leathery, not fleshy","grows in overlapping rosettes on dead wood"],"use":"Use it as an identification lesson. Yehsa does not give doses or remedies with wild fungi.","not":"Never eat a wild mushroom from a photo, an app, or this note. Spore prints, cutting it open, and an expert in person come first, and even then some look-alikes kill.","call":"If someone may have eaten it, call Poison Control at 1-800-222-1222, or 911 for trouble breathing, seizures, or collapse.","src":["poison-control","usfs","nih-medline"],"ask":"Tell me about turkey tail"},{"id":"birch_polypore","title":"Birch polypore (razor strop)","domain":"fungi","also":["razor strop","Fomitopsis betulina","birch bracket"],"def":"Birch polypore is a rounded gray-white shelf fungus on dead birch, used historically as a razor strop and tinder.","look":["rounded grey-white shelf on dead birch","the pore side is white","used as a strop","smooth white pore surface underneath","grows only on dead birch"],"use":"Use it as an identification lesson. Yehsa does not give doses or remedies with wild fungi. Survival history only. Do not eat it.","not":"Never eat a wild mushroom from a photo, an app, or this note. Spore prints, cutting it open, and an expert in person come first, and even then some look-alikes kill.","call":"If someone may have eaten it, call Poison Control at 1-800-222-1222, or 911 for trouble breathing, seizures, or collapse.","src":["poison-control","usfs","nih-medline"],"ask":"Tell me about birch polypore"},{"id":"reishi","title":"Reishi (hemlock varnish shelf)","domain":"fungi","also":["hemlock varnish shelf","Ganoderma","lingzhi","Ganoderma tsugae"],"def":"Reishi, or hemlock varnish shelf, is a glossy red-brown shelf fungus on hemlock and other conifers.","look":["glossy varnished red-brown shelf on a stalk or the side of a tree","shiny, varnished-looking top","grows on hemlock stumps and logs"],"use":"Use it as an identification lesson. Yehsa does not give doses or remedies with wild fungi.","not":"Never eat a wild mushroom from a photo, an app, or this note. Spore prints, cutting it open, and an expert in person come first, and even then some look-alikes kill.","call":"If someone may have eaten it, call Poison Control at 1-800-222-1222, or 911 for trouble breathing, seizures, or collapse.","src":["poison-control","usfs","nih-medline"],"ask":"Tell me about reishi"},{"id":"honey_mushroom","title":"Honey mushroom","domain":"fungi","also":["Armillaria","honey fungus","bootlace fungus"],"def":"Honey mushrooms are clusters of honey-colored capped mushrooms with a ring that grow on wood and roots.","look":["clusters of honey-coloured caps on wood with a ring","white spores","ring on the stem","black bootlace-like cords under bark"],"use":"Use it as an identification and look-alike lesson; only an expert who sees it in person can confirm it. The deadly galerina looks like it.","not":"Never eat a wild mushroom from a photo, an app, or this note. Spore prints, cutting it open, and an expert in person come first, and even then some look-alikes kill.","alike":["Deadly galerina: Small brown mushroom on rotting wood with a thin ring and rusty brown spores. Deadly. Grows on the same logs as honey mushrooms"],"call":"If someone may have eaten it, call Poison Control at 1-800-222-1222, or 911 for trouble breathing, seizures, or collapse.","rel":["deadly_galerina"],"src":["poison-control","usfs","nih-medline"],"ask":"Tell me about honey mushroom"},{"id":"shaggy_mane","title":"Shaggy mane","domain":"fungi","also":["Coprinus comatus","lawyer's wig","inky cap"],"def":"Shaggy mane is a tall white shaggy-capped mushroom that melts into black ink as it ages.","look":["tall white cylinder cap with shaggy scales that melts into ink","gills turn black and dissolve from the bottom up","grows in lawns and disturbed ground"],"use":"Use it as an identification and look-alike lesson; only an expert who sees it in person can confirm it.","not":"Never eat a wild mushroom from a photo, an app, or this note. Spore prints, cutting it open, and an expert in person come first, and even then some look-alikes kill.","call":"If someone may have eaten it, call Poison Control at 1-800-222-1222, or 911 for trouble breathing, seizures, or collapse.","src":["poison-control","usfs","nih-medline"],"ask":"Tell me about shaggy mane"},{"id":"bolete","title":"Bolete","domain":"fungi","also":["Boletus","boletes","porcini","king bolete"],"def":"A bolete is a fleshy mushroom with a sponge of pores instead of gills under the cap.","look":["fat stem with a sponge of pores instead of gills under the cap","pores instead of gills under the cap","some bruise blue when cut"],"use":"Use it as an identification and look-alike lesson; only an expert who sees it in person can confirm it. Red-pored and bitter ones are toxic. Do not eat on a photo.","not":"Never eat a wild mushroom from a photo, an app, or this note. Spore prints, cutting it open, and an expert in person come first, and even then some look-alikes kill.","call":"If someone may have eaten it, call Poison Control at 1-800-222-1222, or 911 for trouble breathing, seizures, or collapse.","src":["poison-control","usfs","nih-medline"],"ask":"Tell me about bolete"},{"id":"green_spored_parasol","title":"Green-spored parasol","domain":"fungi","also":["Chlorophyllum molybdites","false parasol","green-spored lepiota","vomiter"],"def":"The green-spored parasol is a large lawn mushroom whose gills turn green with age, and it causes the most mushroom poisonings in North America.","look":["big scaly cap with a ring","gills turn green with age","lawns","greenish spore print","large ring on the stem"],"use":"Learn it as a warning. The most common mushroom poisoning in North America.","not":"Never eat a wild mushroom from a photo, an app, or this note. Spore prints, cutting it open, and an expert in person come first, and even then some look-alikes kill.","call":"If someone may have eaten it, call Poison Control at 1-800-222-1222, or 911 for trouble breathing, seizures, or collapse.","src":["poison-control","usfs","nih-medline"],"ask":"Tell me about green-spored parasol"},{"id":"hedgehog_mushroom","title":"Hedgehog mushroom","domain":"fungi","also":["Hydnum repandum","sweet tooth","hedgehog"],"def":"The hedgehog mushroom is a pale orange mushroom with soft spines under the cap instead of gills.","look":["pale orange cap with soft spines instead of gills","small spines under the cap instead of gills","grows on the ground in woods"],"use":"Use it as an identification and look-alike lesson; only an expert who sees it in person can confirm it.","not":"Never eat a wild mushroom from a photo, an app, or this note. Spore prints, cutting it open, and an expert in person come first, and even then some look-alikes kill.","call":"If someone may have eaten it, call Poison Control at 1-800-222-1222, or 911 for trouble breathing, seizures, or collapse.","src":["poison-control","usfs","nih-medline"],"ask":"Tell me about hedgehog mushroom"},{"id":"tinder_fungus","title":"Tinder fungus","domain":"fungi","also":["horse hoof fungus","Fomes fomentarius","amadou","hoof fungus"],"def":"Tinder fungus is a hoof-shaped gray woody shelf on birch and beech whose inner layer was used to carry fire.","look":["hoof-shaped grey woody shelf on birch and beech","used for tinder","hard, hoof-shaped, gray with bands","brown felt-like layer inside"],"use":"Use it as an identification lesson. Yehsa does not give doses or remedies with wild fungi. Survival use for fire only.","not":"Never eat a wild mushroom from a photo, an app, or this note. Spore prints, cutting it open, and an expert in person come first, and even then some look-alikes kill.","call":"If someone may have eaten it, call Poison Control at 1-800-222-1222, or 911 for trouble breathing, seizures, or collapse.","src":["poison-control","usfs","nih-medline"],"ask":"Tell me about tinder fungus"},{"id":"chaga","title":"Chaga","domain":"fungi","also":["Inonotus obliquus","clinker fungus","birch conk"],"def":"Chaga is a black, cracked, charcoal-like growth on birch that is orange-brown inside.","look":["black charcoal-like crust on birch with an orange inside","cracked black outer crust","rusty orange-brown inside"],"use":"Use it as an identification lesson. Yehsa does not give doses or remedies with wild fungi.","not":"Never eat a wild mushroom from a photo, an app, or this note. Spore prints, cutting it open, and an expert in person come first, and even then some look-alikes kill.","call":"If someone may have eaten it, call Poison Control at 1-800-222-1222, or 911 for trouble breathing, seizures, or collapse.","src":["poison-control","usfs","nih-medline"],"ask":"Tell me about chaga"},{"id":"day_hike_essentials","title":"Day-hike essentials checklist","domain":"gear","also":["ten essentials","what to bring hiking","hiking checklist","day pack list"],"def":"The day-hike essentials are the few items that let you get through an unplanned night: navigation, light, sun protection, first aid, a knife, fire, shelter, extra food, extra water, and extra clothes.","look":["map and compass as well as a phone","headlamp with spare batteries","an emergency blanket or bivy and a warm layer"],"use":"Pack the same essentials for every hike, even a short one, and leave a trip plan with someone at home.","not":"Do not skip the essentials because the trail is short or familiar; most rescues start on day hikes.","steps":["Navigation: map, compass, charged phone.","Headlamp and spare batteries.","Sun protection.","First-aid kit.","Knife or multi-tool.","Fire starter.","Emergency shelter.","Extra food.","Extra water or a filter.","Extra warm, dry layer."],"rel":["clothing_layers_wet","headlamp_red_light","first_aid_kit_contents"],"src":["nps","ready"]},{"id":"deer_hunt_day_kit","title":"Deer-hunt day kit","domain":"gear","also":["what to bring deer hunting","hunting pack list","deer hunting gear checklist"],"def":"A deer-hunt day kit covers the hunt itself, getting an animal out, and getting yourself home: license and tags, orange, a sharp knife, gloves, a drag rope, light, water, and first aid.","look":["license, tags, and a pen or zip ties for tagging","hunter orange hat and vest","knife, disposable gloves, and a drag rope"],"use":"Pack it the night before, add a headlamp and spare batteries for the walk out in the dark, and tell someone where you will sit.","not":"Do not leave license and tags in the truck, or rely on a phone light to track or walk out.","rel":["hunt_before_you_go","field_dressing_deer"],"src":["ihea","nps"]},{"id":"kit_72_hour","title":"72-hour bag, car kit, and home outage kit","domain":"gear","also":["go bag","bug out bag","72 hour kit","emergency kit","car emergency kit","home emergency kit"],"def":"A 72-hour kit holds what each person needs for three days without help: water, food, light, radio, first aid, medicines, warmth, copies of documents, and cash.","look":["a gallon of water per person per day","a week of prescription medicines where possible","a battery or hand-crank NOAA weather radio"],"use":"Keep a grab bag by the door, a smaller kit in each car with blankets and a scraper, and a home kit for outages; check food, water, and batteries twice a year.","not":"Do not pack only gadgets; water, medicines, and warm layers matter most. Do not store fuel in the living space.","rel":["day_hike_essentials"],"src":["ready","fema"]},{"id":"forgot_knife_light_fire","title":"Forgot your knife, light, or fire starter","domain":"gear","also":["forgot my knife","no flashlight","forgot lighter","no fire starter","improvise gear"],"def":"When a key item is left behind, safer substitutes and a changed plan beat improvising something risky: a phone light in short bursts, a multi-tool or sharp-edged stone, and turning back before dark.","look":["phone battery level","how much daylight is left","whether the trip still makes sense"],"use":"Shorten the trip, start back early, save phone battery for calls and short light, and borrow from a partner.","not":"Do not push on into the night without a light or try to make fire with fuel such as gasoline.","rel":["day_hike_essentials","headlamp_red_light"],"src":["nps","atp3-50-21"]},{"id":"clothing_layers_wet","title":"Clothing layers: wool and synthetics versus cotton","domain":"gear","also":["layering","cotton kills","what to wear hiking","wool vs cotton","base layer"],"def":"Layers let you adjust warmth: a base layer that moves sweat, an insulating layer, and a wind and rain shell; wool and synthetics stay warm when damp, while wet cotton pulls heat away fast.","look":["cotton jeans or a cotton hoodie on a cold, wet day","shivering when you stop","sweat-soaked base layer"],"use":"Take layers off before you sweat, put them on before you chill, and carry a dry spare insulating layer and hat in a waterproof bag.","not":"Do not wear cotton as your main layer in cold, wet, or windy weather.","rel":["day_hike_essentials"],"src":["nps","cdc","atp3-50-21"]},{"id":"headlamp_red_light","title":"Headlamp, spare batteries, and red mode","domain":"gear","also":["headlamp","red light mode","spare batteries","flashlight for camping"],"def":"A headlamp keeps your hands free; spare batteries or a charged backup, and a dim red mode that protects night vision, make it last the night.","look":["batteries tested before the trip","a red or dim setting","cold weather draining batteries"],"use":"Carry a headlamp and spares on every outing, keep batteries warm in cold weather, and use red mode around camp and when reading a map.","not":"Do not rely on a phone as your only light.","rel":["day_hike_essentials"],"src":["nps"]},{"id":"knife_safety_edge","title":"Knife safety and a basic edge","domain":"gear","also":["knife safety","sharpen a knife","cut away from yourself","dull knife"],"def":"Safe knife use means cutting away from your body and others, keeping a blood circle clear around you, and keeping the blade sharp so it does not slip.","look":["a clear arm's length around you","a firm grip and a stable work surface","a dull edge that skids instead of biting"],"use":"Cut away from your body, close or sheath the knife when not using it, and sharpen at a steady, shallow angle on a stone or rod.","not":"Do not cut toward your hand or leg, catch a falling knife, or pass an open blade edge-first.","call":"For a deep cut, press firmly with a clean cloth and get medical care if it gapes or will not stop bleeding.","rel":["first_aid_kit_contents"],"src":["atp3-50-21"]},{"id":"water_filter_care","title":"Water filter care","domain":"gear","also":["hollow fiber filter frozen","sawyer filter care","backflush filter","water filter cold"],"def":"Hollow-fiber water filters must be kept from freezing once wet, because ice can crack the fibers without any visible sign and let germs through.","look":["a filter used on a cold trip","slower flow over time","the maker's backflush syringe or instructions"],"use":"In freezing weather keep a used filter in an inside pocket and in your sleeping bag at night, and backflush it as the maker directs.","not":"Do not trust a filter that may have frozen; boil or disinfect the water instead.","rel":["day_hike_essentials"],"src":["cdc","epa"]},{"id":"first_aid_kit_contents","title":"First-aid kit contents","domain":"gear","also":["first aid kit list","what to put in a first aid kit","trauma kit","IFAK"],"def":"A useful first-aid kit matches your trip and training: bandages and gauze, tape, gloves, blister care, pain relievers, personal medicines, and for bleeding, pressure dressings and a commercial tourniquet if you have trained with it.","look":["personal medicines and an epinephrine auto-injector if prescribed","gloves and a pressure dressing","tweezers for ticks and splinters"],"use":"Build the kit around what you can use, keep it where you can reach it fast, and replace used and expired items after each trip.","not":"Do not carry items you do not know how to use as a substitute for training.","rel":["day_hike_essentials","knife_safety_edge"],"src":["atp4-02-11","ready"]},{"id":"stove_fuel_safety","title":"Stove and fuel safety","domain":"gear","also":["camp stove safety","propane safety","white gas stove","cooking in a tent"],"def":"Camp stoves and fuel are safe used outdoors in open air, set on a stable surface away from tents and brush, with fuel stored cool and closed.","look":["a stable, flat base","no tent fabric, overhanging branches, or dry grass nearby","fuel canisters away from heat and sun"],"use":"Cook outside, light the stove before leaning over it, let it cool before refueling, and pack fuel apart from food.","not":"Never cook or heat with a stove inside a tent, vestibule, car, or home; carbon monoxide can kill.","call":"Get fresh air and call 911 for headache, dizziness, or confusion near a stove or heater.","rel":[],"src":["cpsc","nps"]},{"id":"boot_fit_blisters","title":"Boot fit and blister prevention","domain":"gear","also":["blisters hiking","hiking boot fit","hot spot on foot","prevent blisters"],"def":"Blisters come from friction, heat, and moisture; boots that fit, dry socks, and treating hot spots early prevent most of them.","look":["a warm, rubbing hot spot","heel lifting in the boot","wet socks"],"use":"Break boots in before a trip, wear wool or synthetic socks, stop at the first hot spot, and cover it with tape or moleskin.","not":"Do not keep walking on a hot spot, or pop a blister without clean hands and a clean cover.","call":"See a clinician for a blister that is red, hot, swollen, or draining pus, especially with diabetes.","rel":["day_hike_essentials"],"src":["nps","cdc"]},{"id":"sleeping_bag_ratings","title":"Sleeping bag temperature ratings","domain":"gear","also":["sleeping bag rating","how warm a sleeping bag","sleeping pad R value","cold at night camping"],"def":"A sleeping bag's temperature rating is a lab estimate; most people need a bag rated colder than the night, plus an insulated pad under them.","look":["the comfort versus limit rating","a pad's insulation (R-value) for cold ground","damp or compressed insulation"],"use":"Choose a bag rated below the expected low, add a warm pad, wear a dry hat and base layer, and eat before bed.","not":"Do not sleep in sweaty clothes or put a down bag in a damp stuff sack for days.","rel":["clothing_layers_wet"],"src":["nps","atp3-50-21"]},{"id":"pack_fit","title":"Fitting a backpack","domain":"gear","also":["backpack fit","hip belt","pack hurts shoulders","adjust a pack"],"def":"A pack fits when the hip belt carries most of the weight on the hip bones and the shoulder straps hug without carrying the load.","look":["hip belt centered on the hip bones","load lifters snug at an angle","heavy items close to the back"],"use":"Loosen everything, buckle the hip belt first, then snug the shoulder straps, load lifters, and sternum strap. Pack heavy items close to your spine.","not":"Do not carry the weight on your shoulders alone or overload for a day trip.","rel":["day_hike_essentials"],"src":["nps"]},{"id":"field_repair_kit","title":"Field repair: tape, cord, and needle","domain":"gear","also":["repair kit","fix a torn jacket","broken strap","duct tape repair"],"def":"A small repair kit of tape, cord, a needle and strong thread, safety pins, and a few zip ties fixes most broken straps, torn shells, and gear failures.","look":["duct or repair tape wrapped on a bottle or pole","spare cord and a buckle","a needle with heavy thread"],"use":"Patch holes with tape on both sides, sew or pin torn straps, lash broken parts with cord, and keep a wet sleeping bag in a dry bag.","not":"Do not ignore a small tear in a shell before rain; tape it now.","rel":["day_hike_essentials","knife_safety_edge"],"src":["atp3-50-21"]},{"id":"rope_cordage_basics","title":"Rope and cordage basics","domain":"gear","also":["paracord","what rope to carry","cordage","rope for camping"],"def":"A length of strong cord lets you hang a tarp, rig a clothesline, lash a splint, or hang food; knowing a few knots makes it useful.","look":["about 50 feet of thin, strong cord","rope rated for the job if it holds people","fraying or melted spots"],"use":"Carry cord for camp jobs and learn a bowline, a taut-line hitch, and two half hitches.","not":"Do not use utility cord for climbing, rappelling, or holding a person.","rel":["field_repair_kit"],"src":["atp3-50-21"]},{"id":"binoculars_rangefinder","title":"Binoculars and rangefinders in practice","domain":"gear","also":["binoculars","rangefinder","glassing","how far is that deer"],"def":"Binoculars help you identify animals and people before acting; a rangefinder measures distance to keep shots within your practiced range.","look":["a steady rest when glassing","identifying the whole animal","range checks on landmarks before game appears"],"use":"Glass from a rest, range a few landmarks around your stand, and use binoculars, not a rifle scope, to look at things you are not sure of.","not":"Do not use a rifle scope to scan people or unknown movement.","rel":["hunt_target_beyond"],"src":["ihea"]},{"id":"trekking_poles","title":"Trekking poles","domain":"gear","also":["hiking poles","walking sticks","trekking pole height"],"def":"Trekking poles take strain off knees on descents, add balance on stream crossings and ice, and can hold up a tarp.","look":["elbow at about a right angle on flat ground","longer for downhill, shorter for uphill","tips and baskets for snow"],"use":"Adjust the length to the slope, use the straps correctly, and plant poles ahead on crossings.","not":"Do not rely on poles to stop a slide on steep ice; turn back or use proper traction.","rel":["stream_crossing_choice"],"src":["nps"]},{"id":"saw_hatchet_safety","title":"Saw and hatchet safety","domain":"gear","also":["hatchet safety","folding saw","chopping wood safely","axe safety"],"def":"A folding saw is safer and more efficient than a hatchet for most camp wood; both need a clear swing zone and a stable work position.","look":["a clear arc with no people or branches","wood on a stable base, not held by your foot","sharp tool with a sheath or guard"],"use":"Saw dead, down wood, kneel or stand so a missed swing goes into the ground, and sheath tools when done.","not":"Do not chop toward your legs, swing while tired, or cut standing live trees where it is not allowed.","call":"Press firmly on a deep cut and get medical care; call 911 for bleeding that will not stop.","rel":["knife_safety_edge"],"src":["atp3-50-21","usfs"]},{"id":"winter_travel_gear","title":"Winter travel gear","domain":"gear","also":["snowshoes","microspikes","ice cleats","winter hiking gear"],"def":"Winter trails need traction such as microspikes or snowshoes, insulated boots, extra layers, and more daylight planning.","look":["ice under snow on trails","deep snow that makes you posthole","short daylight and fast cooling"],"use":"Carry traction, a warm spare layer, an insulated bottle, and a headlamp, and turn back early.","not":"Do not walk on frozen lakes or rivers unless you know the ice is safe and thick.","rel":["clothing_layers_wet","turnaround_time"],"src":["nps","nws"]},{"id":"phone_battery_backup","title":"Phone battery and backup power","domain":"gear","also":["phone battery dying","power bank","save phone battery","charge phone outdoors"],"def":"A phone drains fast in cold and when searching for signal; a charged power bank and battery-saving settings keep it working for calls and maps.","look":["battery level and temperature","airplane mode when you don't need signal","a power bank and cable in a dry bag"],"use":"Keep the phone warm in an inside pocket, turn on low-power or airplane mode, dim the screen, and carry a charged power bank.","not":"Do not let the phone die before you send a location or call for help when you need it.","rel":["gps_vs_map","satellite_sos_messenger"],"src":["ready","nps"]},{"id":"satellite_sos_messenger","title":"Satellite SOS and messengers","domain":"gear","also":["satellite SOS","personal locator beacon","PLB","inReach","emergency beacon"],"def":"Satellite SOS devices and some phones can send an emergency message from places with no cell signal; a personal locator beacon alerts search and rescue directly.","look":["a clear view of the sky","the device registered and tested before the trip","battery charged"],"use":"Learn how to send an SOS before you need it, keep it on your body, and use it only for real emergencies.","not":"Do not assume a phone has satellite service in your area without checking.","call":"Use SOS for life-threatening emergencies; otherwise text or call when you can.","rel":["phone_battery_backup"],"src":["noaa","nps"]},{"id":"whistle_mirror_signal","title":"Whistle and signal mirror","domain":"gear","also":["emergency whistle","signal mirror","three whistle blasts"],"def":"A whistle carries farther than your voice and takes little energy; a signal mirror flashes sunlight to aircraft or searchers miles away.","look":["three blasts or three flashes as a distress signal","a whistle on the pack strap or jacket","sunlight for a mirror"],"use":"Blow three blasts and repeat; aim the mirror flash at aircraft or distant searchers using your fingers as a sight.","not":"Do not use distress signals as a joke or game near other people.","rel":["day_hike_essentials"],"src":["atp3-50-21","nps"]},{"id":"insect_repellent_use","title":"Insect repellent and tick-treated clothing","domain":"gear","also":["bug spray","DEET","permethrin","picaridin","mosquito repellent"],"def":"EPA-registered repellents such as DEET, picaridin, or oil of lemon eucalyptus on skin, and permethrin on clothing, reduce tick and mosquito bites.","look":["the EPA registration on the label","permethrin for clothes and gear, never skin","age limits on the label for children"],"use":"Use repellent on exposed skin as the label directs, treat boots and pants with permethrin, and do a tick check after.","not":"Do not put permethrin on skin, spray repellent on a child's hands, or use oil of lemon eucalyptus on children under three.","rel":["kids_prevention_rules"],"src":["cdc","epa"]},{"id":"water_carry_capacity","title":"How much water to carry","domain":"gear","also":["how much water hiking","water bottles","hydration bladder"],"def":"How much water you need depends on heat, effort, and distance; a rough start is about a half liter per hour of moderate hiking, more in heat.","look":["dark urine or thirst","hot, dry, or high-altitude conditions","reliable water sources along the route"],"use":"Carry enough to reach the next sure source plus extra, and a filter or tablets to treat more.","not":"Do not ration water to the point of dehydration in heat; drink and plan a shorter trip.","rel":["water_filter_care","day_hike_essentials"],"src":["nps","cdc"]},{"id":"hunt_before_you_go","title":"Before you hunt: license, tags, orange, and this year's rules","domain":"hunting","also":["hunting license","deer tag","what do I need to hunt","hunter orange","blaze orange","hunting regulations"],"def":"Before a hunt you need a valid license and any tags for the animal, the hunter orange your state requires, and this season's official rules, which change every year.","look":["license and tags on you, not at home","orange hat and vest where the state requires it","the current year's regulation page from the state wildlife agency"],"use":"Read the state wildlife agency's current page for seasons, bag limits, legal methods, and orange rules before every season, and carry the license and tags while you hunt.","not":"Do not rely on last year's dates or limits, a forum post, or a remembered rule. Yehsa does not store season dates or bag limits because they go stale.","steps":["Buy or renew the license and tags for this season.","Read the state agency's current rules for the area and weapon.","Pack hunter orange and wear it as the rules require.","Tell someone where you will be and when you will be back."],"rel":["hunt_firearm_safety","hunt_legal_light_note"],"src":["state-regs-link","ihea"]},{"id":"hunt_legal_light_note","title":"Legal shooting light","domain":"hunting","also":["shooting hours","legal shooting time","half hour before sunrise","when can I shoot"],"def":"Legal shooting light is the window each day when hunting is allowed; many states use about 30 minutes before sunrise to 30 minutes after sunset, but the exact rule is set by each state and sometimes by species.","look":["sunrise and sunset for your exact spot","the state's own rule for the species","enough light to identify the animal and what is beyond it"],"use":"Check your state's current rule, then work out the times for your location; Yehsa's sun tool can show sunrise and sunset for where you are if you turn position on.","not":"Do not shoot in poor light even inside legal hours if you cannot identify the animal and the background. Do not assume the 30-minute rule applies to every state or species.","rel":["hunt_before_you_go"],"src":["state-regs-link","nws"]},{"id":"hunt_firearm_safety","title":"Firearm safety in the field","domain":"hunting","also":["gun safety","hunting gun safety","muzzle control","treat every gun as loaded","firearm rules"],"def":"Field firearm safety comes down to four habits: treat every gun as loaded, keep the muzzle pointed in a safe direction, keep your finger off the trigger until you are ready to shoot, and be sure of your target and what is beyond it.","look":["muzzle never sweeps a person, including yourself","finger rests along the frame, outside the trigger guard","action open and unloaded when crossing, climbing, or riding"],"use":"Unload before crossing a fence, climbing a stand, entering a vehicle, or entering camp. Use a haul line to raise or lower an unloaded gun.","not":"Do not lean a loaded gun against a tree or vehicle, shoot at a sound or movement, or shoot at a flat hard surface or water where a bullet can skip.","steps":["Point the muzzle in a safe direction.","Keep your finger off the trigger.","Identify the target fully.","Know what is behind and beyond it.","Unload before obstacles, stands, and vehicles."],"call":"If someone is shot, call 911 at once, put firm direct pressure on the wound, and use a tourniquet on a limb if pressure does not stop heavy bleeding.","rel":["hunt_target_beyond","hunt_fence_crossing","tree_stand_safety"],"src":["ihea","state-regs-link"]},{"id":"hunt_target_beyond","title":"Know your target and what is beyond it","domain":"hunting","also":["identify before you shoot","not sure what it is","is it a deer","backstop","what is behind the target"],"def":"Before any shot you must be certain of the species, sex if it matters for your tag, and that a safe backstop such as rising ground stops the bullet; anything uncertain means no shot.","look":["whole animal seen, not just a patch of brown or a sound","no house, road, trail, or person in the line of fire","a hill or earth bank behind the animal"],"use":"When unsure of the animal or the shot, do not shoot. Wait for a clear view or let it walk.","not":"Do not shoot at a skyline animal on a ridge top, at movement in brush, or toward another hunter's orange.","rel":["hunt_firearm_safety","hunt_shot_placement"],"src":["ihea"]},{"id":"hunt_shot_placement","title":"Shot placement and what to do after the shot","domain":"hunting","also":["where to shoot a deer","ethical shot","vital zone","heart lung shot","after the shot"],"def":"An ethical shot aims at the heart and lungs from a broadside or slightly quartering-away angle within the range you have practiced, so the animal goes down quickly.","look":["the animal standing still and broadside","a clear lane with no branches in the path","a range you have confirmed on paper"],"use":"After the shot, watch where the animal goes, mark the spot where it stood and the last place you saw it, and wait quietly before following unless you see it fall.","not":"Do not take long, running, or head-on shots you have not practiced, and do not rush after a hit animal; pushing it can make it run farther.","steps":["Note where the animal stood when hit.","Mark the last place you saw it.","Listen for a crash.","Wait before tracking, longer if the hit looked far back.","Start at the hit site and look for hair and blood."],"rel":["hunt_blood_trail","hunt_lost_animal"],"src":["ihea"]},{"id":"hunt_blood_trail","title":"Tracking a hit deer and reading a blood trail","domain":"hunting","also":["blood trail","tracking a wounded deer","following blood","lost blood trail","how long to wait before tracking"],"def":"Following a hit deer means starting at the spot it stood, finding hair and blood, and moving slowly from sign to sign while marking each spot.","look":["bright red, frothy blood often means a lung hit","dark blood or green matter can mean a gut hit and a longer wait","drops on both sides of the trail, smears on brush at body height"],"use":"Mark each blood spot with tape or tissue so you can see the line of travel, and look ahead and around the last sign when it thins out.","not":"Do not walk on the trail itself, track in the dark alone in rough country, or give up after the first gap; circle the last sign first.","steps":["Start at the hit site.","Mark every sign you find.","Move slowly and look ahead.","When it stops, circle out from the last mark.","Bring a partner and a light if it gets late."],"rel":["hunt_lost_animal","hunt_shot_placement"],"src":["ihea"]},{"id":"hunt_lost_animal","title":"When you cannot find the animal","domain":"hunting","also":["can't find my deer","lost the blood trail","wounded deer lost","deer ran off"],"def":"When a hit animal cannot be found, the ethical next steps are a careful grid search, a second person's eyes, and, where the state allows it, a leashed tracking dog.","look":["the last marked sign","water, thick cover, and downhill paths nearby","birds such as crows or ravens gathering"],"use":"Search in widening loops from the last sign, check thick cover and water, and come back at first light if needed. Check your state's rules on tagging and on tracking dogs.","not":"Do not trespass to follow an animal without asking the landowner, and do not shoot another animal before you have made every effort.","rel":["hunt_blood_trail","hunt_before_you_go"],"src":["ihea","state-regs-link"]},{"id":"field_dressing_deer","title":"Field dressing a deer","domain":"hunting","also":["gutting a deer","field dress","clean a deer","how to gut a deer"],"def":"Field dressing removes the internal organs soon after the kill so the body heat can escape and the meat cools quickly.","look":["gloves on, sharp knife, clean water or wipes","belly opened shallow so the gut is not cut","body cavity propped open to cool"],"use":"Tag the animal first if your state requires it, open the body from the pelvis toward the ribs with the blade edge up, remove the organs, then prop the cavity open in shade.","not":"Do not cut into the stomach or intestines, handle the brain or spinal cord bare-handed, or leave the carcass in sun or a closed truck bed.","steps":["Tag the animal if required.","Put on gloves.","Cut shallow from the pelvis to the ribs, edge up.","Free and roll out the organs.","Wipe out blood and hair; prop open and keep it cool."],"rel":["meat_care_temperature","cwd_awareness"],"src":["usda-fsis","cdc","ihea"]},{"id":"meat_care_temperature","title":"Keeping game meat cool and spotting spoiled meat","domain":"hunting","also":["meat care warm weather","is my deer meat spoiled","hanging a deer","cooling venison","game meat spoiled"],"def":"Game meat stays safe when it is cooled below 40 °F (4 °C) quickly; in warm weather that means skinning, quartering, and icing within hours.","look":["air temperature above 40 °F means the clock is running","a sour or rotten smell, slime, or green color means spoiled","meat kept clean, dry, and shaded"],"use":"In warm weather, skin and quarter the animal, bag the meat, and put it on ice or in a cooler or cold storage the same day. In cold weather hang it in shade, protected from animals.","not":"Do not leave a carcass in the sun or a warm vehicle overnight, and do not eat meat that smells sour or rotten; cooking does not make spoiled meat safe.","rel":["field_dressing_deer","game_cooking_temps"],"src":["usda-fsis"]},{"id":"cwd_awareness","title":"Chronic wasting disease (CWD) and deer","domain":"hunting","also":["CWD","chronic wasting disease","zombie deer","sick looking deer","deer disease"],"def":"Chronic wasting disease is a fatal prion disease of deer, elk, and moose; no human case has been confirmed, but health agencies advise people not to eat meat from an infected animal.","look":["a thin, drooling, stumbling, or unafraid deer","animals found dead","areas where your state reports CWD"],"use":"Do not shoot or handle animals that look sick, wear gloves while dressing, avoid the brain, spine, eyes, spleen, and lymph nodes, and test animals from CWD areas before eating.","not":"Do not eat meat from an animal that tests positive, and do not saw through the spine or skull with tools used for meat.","call":"Report a sick-looking deer to your state wildlife agency.","rel":["field_dressing_deer","hunt_before_you_go"],"src":["cdc","usgs","state-regs-link"]},{"id":"game_cooking_temps","title":"Cooking venison and wild game safely","domain":"hunting","also":["venison temperature","cook deer meat","ground venison temperature","wild game cooking"],"def":"Game meat is safest cooked to a measured temperature: whole cuts of venison to at least 145 °F (63 °C) with a 3-minute rest, ground venison to 160 °F (71 °C), and wild birds to 165 °F (74 °C).","look":["a food thermometer in the thickest part","ground meat cooked through","juices and color are not a reliable test"],"use":"Use a thermometer, keep raw game apart from cooked food, and wash hands and boards after handling raw meat.","not":"Do not judge doneness by color, and do not eat bear, wild boar, or other carnivore meat undercooked; they can carry trichinella.","rel":["meat_care_temperature","small_game_tularemia"],"src":["usda-fsis","cdc"]},{"id":"tree_stand_safety","title":"Tree-stand safety","domain":"hunting","also":["tree stand","deer stand fall","safety harness","full body harness","climbing a stand"],"def":"Tree-stand safety means staying attached to the tree from the moment you leave the ground until you are back on it, with a full-body harness and a lifeline or tether.","look":["full-body harness worn and connected","stand straps and chains checked before each season","gun or bow raised with a haul line, unloaded"],"use":"Inspect the stand, wear a harness connected to a lifeline while climbing, keep three points of contact, and pull up your unloaded gun or bow with a rope.","not":"Do not climb with a loaded gun, use a waist belt only, or use a stand left on the tree for years without checking its straps.","call":"If someone falls, call 911; do not move them if the neck or back may be hurt, and if they hang in a harness, get their weight off the straps quickly.","rel":["hunt_firearm_safety"],"src":["ihea"]},{"id":"hunt_fence_crossing","title":"Crossing fences and obstacles with a firearm","domain":"hunting","also":["crossing a fence with a gun","climbing over a log with a gun","crossing a stream with a rifle"],"def":"Crossing a fence, ditch, log, or stream with a firearm is safe only with the action open and the gun unloaded, set down on the far side with the muzzle pointed away.","look":["action open and chamber empty","muzzle pointed away from you and others","gun laid down before you climb"],"use":"Unload, open the action, slide the gun under or across, cross yourself, then pick it up by the stock. With a partner, one holds both guns while the other crosses.","not":"Do not climb over with a gun in your hand, pull a gun toward you by the muzzle, or jump a ditch with a loaded gun.","rel":["hunt_firearm_safety"],"src":["ihea"]},{"id":"small_game_tularemia","title":"Small game: rabbits, squirrels, and tularemia","domain":"hunting","also":["rabbit fever","tularemia","cleaning rabbits","squirrel hunting safety"],"def":"Tularemia is a bacterial disease people can catch from handling or eating rabbits, hares, and rodents; gloves and thorough cooking prevent most cases.","look":["a rabbit or squirrel that is slow, sick, or found dead","white spots on the liver","small cuts on your hands while cleaning"],"use":"Wear gloves when skinning and cleaning, cook the meat thoroughly, and wash hands and tools afterward.","not":"Do not handle sick or dead animals bare-handed, and do not eat rabbit or squirrel undercooked.","call":"See a doctor for fever, a sore that will not heal, or swollen glands after handling wild rabbits or rodents, and say you handled game.","rel":["game_cooking_temps"],"src":["cdc"]},{"id":"waterfowl_rules_link","title":"Waterfowl and migratory birds have their own rules","domain":"hunting","also":["duck hunting rules","goose hunting","migratory bird hunting","duck stamp","waterfowl regulations"],"def":"Ducks, geese, and other migratory birds are hunted under federal rules plus state rules, which differ from deer rules, including shot type and a federal duck stamp for many hunters.","look":["a federal duck stamp and state permits where required","non-toxic shot required for waterfowl","birds identified in flight before the shot"],"use":"Read the US Fish and Wildlife Service and your state's current waterfowl pages before the season.","not":"Do not shoot a bird you cannot identify, and do not use lead shot for waterfowl.","rel":["hunt_before_you_go"],"src":["fws","state-regs-link"]},{"id":"turkey_hunting_safety","title":"Turkey hunting safety","domain":"hunting","also":["turkey hunting","spring turkey safety","gobbler hunting","turkey call safety"],"def":"Turkey hunting has its own risks because hunters wear camouflage and use calls, so another hunter can mistake a person for a bird.","look":["no red, white, or blue clothing, which can look like a gobbler's head","a tree trunk wider than your shoulders at your back","a clear view of the whole bird and its beard before the shot"],"use":"Sit against a wide tree, call out loudly to an approaching hunter instead of moving, and carry a harvested bird out wrapped in orange.","not":"Do not stalk a gobbling sound, shoot at sound or movement, or wave to an approaching hunter.","rel":["hunt_target_beyond"],"src":["ihea"]},{"id":"quartering_packing_out","title":"Quartering and packing out game","domain":"hunting","also":["quarter a deer","pack out meat","gutless method","boning out a deer"],"def":"Quartering means cutting a large animal into its four legs plus the backstraps, neck, and other meat so it can be carried out in loads and cooled faster.","look":["clean game bags for each quarter","a sharp knife and a spare blade","a pack frame or sled for heavy loads"],"use":"Skin one side at a time, take the front and hind quarters, backstraps, and tenderloins, bag each piece, and hang or lay the bags in shade to cool before carrying.","not":"Do not leave meat in a pile on the ground in the sun, and check your state's evidence-of-sex and tagging rules before you separate parts.","rel":["field_dressing_deer","meat_care_temperature"],"src":["usda-fsis","ihea","state-regs-link"]},{"id":"skinning_hanging_deer","title":"Skinning and hanging a deer","domain":"hunting","also":["skin a deer","hang a deer","how long to hang venison","deer gambrel"],"def":"Skinning removes the hide so meat can cool and stay clean; hanging lets the carcass cool and drain in cold, shaded, animal-proof conditions.","look":["a stable gambrel or rope and a strong limb or beam","air at or below 40 °F (4 °C) for hanging","hair kept off the meat"],"use":"Hang by the hind legs or the head, skin from the top down with the blade edge out, and keep the carcass cold and covered from flies and animals.","not":"Do not hang meat in temperatures above 40 °F for long, and do not let pets or wildlife reach it.","rel":["meat_care_temperature","basic_butcher_cuts"],"src":["usda-fsis","ihea"]},{"id":"basic_butcher_cuts","title":"Basic venison butchering cuts","domain":"hunting","also":["butcher a deer","venison cuts","backstrap","tenderloin","deer processing at home"],"def":"Home butchering divides a deer into a few simple groups: backstraps and tenderloins for steaks, hind-quarter roasts, shoulder and neck for stew, and trim for grinding.","look":["silver skin and fat trimmed off","a clean, cold work surface","meat wrapped airtight and labeled with date"],"use":"Work cold and clean, trim fat, silver skin, and bloodshot meat, wrap tightly, label, and freeze.","not":"Do not saw through bone or the spine in CWD areas, and do not leave meat warm on the counter while you work.","rel":["skinning_hanging_deer","cwd_awareness","game_cooking_temps"],"src":["usda-fsis","cdc"]},{"id":"tag_transport_checkin","title":"Tagging, transport, and checking in game","domain":"hunting","also":["tag a deer","check in deer","register harvest","transport deer legally"],"def":"Most states require you to tag an animal right away, keep the tag with it during transport, and report or check in the harvest within a set time.","look":["the tag filled out and attached as your state requires","the state's online, phone, or station check-in","rules on moving carcasses from CWD areas"],"use":"Read your state agency's current tagging and check-in page before the season and follow it exactly.","not":"Do not guess the deadline or carry an untagged animal; rules differ by state and change.","rel":["hunt_before_you_go","cwd_awareness"],"src":["state-regs-link"]},{"id":"cwd_processor_request","title":"Using a processor when CWD is a concern","domain":"hunting","also":["deer processor CWD","individual processing","commercial processing venison"],"def":"If you hunt where chronic wasting disease is found, ask a processor to process your animal by itself so its meat is not mixed with others.","look":["the processor's policy on batch versus individual processing","test results before you eat the meat","how they dispose of bones and trimmings"],"use":"Ask for individual processing, get the animal tested, and keep the meat frozen and unused until the result comes back.","not":"Do not eat meat from an animal that tests positive.","rel":["cwd_awareness"],"src":["cdc","state-regs-link"]},{"id":"recover_game_water_cover","title":"Recovering game in water or thick cover","domain":"hunting","also":["deer in the water","deer in a swamp","retrieve deer thick brush"],"def":"Getting an animal out of water, swamp, or thick cover comes after your own safety: cold water and deep mud can kill.","look":["water depth, current, and temperature","ice that may not hold","dark or difficult ground near nightfall"],"use":"Bring a partner and a rope, wait for light if needed, and reach the animal from shore or shallow water where you can.","not":"Do not wade into deep, fast, or ice-cold water or walk onto thin ice for an animal.","call":"Call 911 if anyone falls through ice or into cold water.","rel":["hunt_lost_animal"],"src":["nws","ihea"]},{"id":"ground_blind_safety","title":"Ground blind safety","domain":"hunting","also":["ground blind","pop-up blind","hunting blind safety"],"def":"A ground blind hides you at ground level, but it also hides you from other hunters, so safe setup matters.","look":["orange on the outside of the blind where required","a clear, safe shooting lane","a known exit route"],"use":"Put orange on and around the blind as your state requires, know your shooting lanes and backstops, and keep the gun pointed out the window only when ready.","not":"Do not run a heater with an open flame inside a closed blind; carbon monoxide builds fast.","rel":["hunt_firearm_safety"],"src":["ihea","cpsc"]},{"id":"youth_hunter_mentor","title":"Hunting with a young or new hunter","domain":"hunting","also":["take a kid hunting","mentor hunt","youth hunter","new hunter safety"],"def":"Mentoring a new or young hunter means close supervision, short trips, and teaching safety before success.","look":["the new hunter within arm's reach when handling a gun","a completed hunter-education course where required","warm clothes, snacks, and a short plan"],"use":"Keep sessions short and comfortable, review the firearm rules often, and check your state's youth and apprentice rules.","not":"Do not hand an untrained person a loaded gun, or push a tired or cold child to stay out.","rel":["hunt_firearm_safety","hunt_before_you_go"],"src":["ihea","state-regs-link"]},{"id":"bear_moose_camp_safety","title":"Black bear and moose around camps and carcasses","domain":"hunting","also":["bear at my deer","bear near camp","moose charge","bear safety hunting"],"def":"Black bears are drawn to carcasses, gut piles, and camp food, and a moose can charge if crowded, especially a cow with a calf or a bull in the rut.","look":["fresh bear sign near a gut pile or meat pole","a moose with ears back and hackles raised","food or meat left out at camp"],"use":"Hang meat away from sleeping areas, store food sealed, approach a kill carefully and make noise, and give moose plenty of room.","not":"Do not approach a bear on a carcass or a moose at close range, and do not run from a bear.","rel":["meat_care_temperature"],"src":["nps","state-regs-link"]},{"id":"field_dressing_birds","title":"Field dressing birds","domain":"hunting","also":["clean a turkey","gut a pheasant","field dress grouse","dress a duck"],"def":"Birds keep best when the crop and entrails are removed soon after the kill and the body is cooled.","look":["gloves on","crop and intestines removed","the bird kept cool and dry"],"use":"Remove the entrails and crop, wipe the cavity, and cool the bird quickly; pluck or skin at home.","not":"Do not leave birds in a warm vest or pile them in a closed bag in warm weather.","rel":["game_cooking_temps"],"src":["usda-fsis","fws"]},{"id":"lead_ammo_awareness","title":"Lead versus non-lead ammunition","domain":"hunting","also":["lead bullet fragments","copper bullets","non-toxic shot","lead in venison"],"def":"Lead bullets can break into small fragments in meat, and scavengers such as eagles can be poisoned by lead in gut piles; non-lead options exist.","look":["fragments spread several inches from the wound channel","federal non-toxic shot rules for waterfowl","local rules on lead ammunition"],"use":"Trim generously around the wound channel, consider copper or other non-lead ammunition, and follow any rules where you hunt.","not":"Do not feed trimmings from around a lead wound channel to children or pets.","rel":["waterfowl_rules_link"],"src":["fws","cdc"]},{"id":"hunting_ethics_waste","title":"Hunting ethics: no waste, respect for land and people","domain":"hunting","also":["hunting ethics","fair chase","wanton waste","respect landowners"],"def":"Ethical hunting means taking only shots you can make cleanly, using the animal well, and respecting landowners, other hunters, and the law.","look":["permission in hand on private land","a plan to recover and use the meat","courtesy to others in the field"],"use":"Practice before the season, pass on doubtful shots, recover and use what you take, and leave gates and land as you found them.","not":"Do not waste meat, shoot from roads where it is illegal, or interfere with other hunters.","rel":["land_access_trespass"],"src":["ihea","state-regs-link"]},{"id":"land_access_trespass","title":"Land access, permission, and trespass","domain":"hunting","also":["hunting private land","landowner permission","posted land","trespass hunting"],"def":"Hunting on private land needs the owner's permission, and posting and trespass rules differ from state to state; Yehsa has no property-owner map.","look":["posted signs or paint marks on trees","a written or verbal permission you can show","public land boundaries on official maps"],"use":"Ask permission early, carry the owner's contact, learn your state's posting rules, and check official public-land maps.","not":"Do not cross onto land you are not sure about to follow game without permission.","rel":["hunt_lost_animal","hunting_ethics_waste"],"src":["state-regs-link"]},{"id":"trapping_regulated","title":"Trapping is tightly regulated","domain":"hunting","also":["trapping license","how to trap","trap rules","snare rules"],"def":"Trapping usually needs its own license or education course and has strict rules on trap types, placement, checking times, and seasons.","look":["the state's trapper-education requirement","trap check intervals","rules that protect pets and non-target animals"],"use":"Take your state's trapper-education course and follow its current rules.","not":"Yehsa does not give trap-setting instructions; do not set traps or snares without the license and training.","rel":["hunt_before_you_go"],"src":["state-regs-link","ihea"]},{"id":"game_camera_etiquette","title":"Game cameras: etiquette and privacy","domain":"hunting","also":["trail camera","game camera privacy","cellular trail cam"],"def":"Trail cameras record whatever passes, including people, so place them where you have permission and think about privacy.","look":["the landowner's permission","trails used by hikers or neighbors","state rules on cameras during the season"],"use":"Get permission, aim cameras at game trails rather than paths people use, and check whether your state limits cellular cameras.","not":"Do not record people without consent where it is prohibited, or share images that show others.","rel":["land_access_trespass"],"src":["state-regs-link"]},{"id":"wind_scent_hunting","title":"Wind direction and your scent","domain":"hunting","also":["wind direction hunting","scent cone","deer smell me","play the wind"],"def":"Deer rely on smell, and your scent drifts downwind in a widening cone, so hunters set up with the wind blowing from the deer toward them.","look":["wind direction from a light feather, milkweed fluff, or powder","thermals rising in the morning warmth and sinking in the evening","deer approaching from downwind"],"use":"Check the wind before you walk in, approach and sit so the wind carries your scent away from where deer travel, and move if it shifts.","not":"Do not walk your stand trail with the wind at your back toward the deer.","rel":["deer_sign_reading"],"src":["ihea","nws"]},{"id":"dragging_deer_safety","title":"Dragging a deer without hurting yourself","domain":"hunting","also":["drag a deer","heart attack dragging deer","deer sled","moving a deer out"],"def":"Dragging a deer is hard work that strains the back and heart, especially in cold weather and for people who do not exercise.","look":["chest pain, shortness of breath, or dizziness","a long or uphill drag","help available nearby"],"use":"Use a sled or cart, get help, take frequent breaks, and quarter a large animal rather than drag it far.","not":"Do not push through chest pain or breathlessness.","call":"Call 911 for chest pain, pain spreading to the arm or jaw, or fainting.","rel":["quartering_packing_out"],"src":["cdc","ihea"]},{"id":"hunting_alone_plan","title":"Hunting alone: leave a plan","domain":"hunting","also":["solo hunting","hunting alone safety","tell someone where I hunt"],"def":"A solo hunter should leave a plan with someone: where you will park and sit, when you will be back, and when they should call for help.","look":["a marked map or pin of your stand","a check-in time","a charged phone and a light"],"use":"Leave the plan, carry a whistle, light, and first aid, and stick to your return time or update it.","not":"Do not change areas without telling your contact.","call":"Your contact should call 911 if you miss the agreed time and cannot be reached.","rel":["hunt_before_you_go","tree_stand_safety"],"src":["nps","ihea"]},{"id":"deer_scat","title":"Deer scat","domain":"hunting","also":["deer droppings","deer poop","deer pellets","deer poo","deer dung","deer sign"],"def":"Deer scat is a pile of small, dark, oval or acorn-shaped pellets, often 20 to 50 together, that shows where deer have fed or bedded.","look":["pellets about 1/2 to 3/4 inch (1.5 to 2 cm) long, often with a small point or dimple at one end","dark and shiny when fresh, dull and dry or crumbly when old","in winter pellets are hard and separate; on spring and summer greens they can clump into a soft mass"],"use":"Fresh, glossy pellets mean deer were there within a day or so. Many piles near trails, food, and thick cover suggest a regular use area, and piles in a bedding area mean deer rest there. Use it with tracks, rubs, and scrapes, not alone.","not":"Scat cannot tell you a buck from a doe or how big the deer is. Do not touch or sniff scat with bare hands; use a stick, and wash your hands after. Do not camp next to a latrine or fresh bear sign.","steps":["Check freshness: shiny and moist means recent, dry and faded means days or weeks.","Look for more piles along a line to find a travel route.","Note nearby food (acorns, browse) and bedding cover.","Note the spot if you want to come back."],"alike":["Rabbit scat: round, flattened pea-sized balls, not oval with a point","Moose scat: same shape but much larger, about an inch (2.5 cm) or more, and woody","Elk scat: larger and rounder than deer, rare in New England"],"rel":["deer_track","deer_rub","deer_scrape"],"src":["usfs","nps","cdc"],"ask":"Tell me about deer scat"},{"id":"deer_track","title":"Deer tracks","domain":"hunting","also":["deer track","deer prints","deer hoof print","whitetail track","deer sign","slot"],"def":"A deer track is a split, heart-shaped hoof print made by two pointed toes, about 2 to 3 1/2 inches (5 to 9 cm) long.","look":["two teardrop toes forming a heart with the point toward travel","two dewclaw dots behind the print in mud, snow, or when running","an alternating walking line, with hind feet landing in or near the front prints"],"use":"The pointed end shows the direction of travel. Sharp edges and loose crumbs mean a fresh track; rounded, rained-on, or leaf-filled edges mean an old one. Many tracks in a line usually mark a travel route between bedding and food.","not":"Track size alone does not reliably tell a buck from a doe. Do not follow a track onto land where you do not have permission.","steps":["Find the pointed end to tell direction.","Check the edges for freshness.","Follow the line a short way to see if it joins a trail.","Look for scat, rubs, and scrapes along it."],"alike":["Moose track: same shape but over 4 inches (10 cm) long","Domestic goat, sheep, or pig: rounder toes; pigs leave dewclaws set wide","Turkey or dog: toes and claws, not two hooves"],"rel":["deer_scat","deer_rub","deer_scrape"],"src":["usfs","nps","state-dnr"],"ask":"Tell me about deer tracks"},{"id":"deer_rub","title":"Deer rubs","domain":"hunting","also":["buck rub","antler rub","rubs on trees","scraped bark","deer sign","rub line"],"def":"A rub is a sapling or small tree where a buck has scraped off bark with his antlers, mostly in fall before and during the rut.","look":["bark stripped from one side of a small tree, often 1 to 4 inches (2.5 to 10 cm) thick, from knee to waist height","pale fresh wood, shredded bark curls on the ground, and broken twigs","several rubs in a line along a trail, called a rub line"],"use":"Fresh rubs mean a buck has used the area this season. A line of rubs often shows a travel route, and the rubbed side tends to face the direction he was coming from. Big rubs on thick trees usually come from mature bucks.","not":"Rubs do not mean a buck is there now. Last year's rubs are gray and healed.","steps":["Check if the wood is pale and moist (fresh) or gray (old).","Look for more rubs in a line.","Note which side is rubbed to guess direction of travel.","Check nearby for scrapes and tracks."],"alike":["Beaver chewing: tooth marks and chips, often cut through near the ground","Porcupine feeding: patches chewed high on trees, with tooth marks","Moose rubs: much higher and on bigger trees"],"rel":["deer_scrape","deer_track","deer_scat"],"src":["usfs","state-dnr"],"ask":"Tell me about deer rubs"},{"id":"deer_scrape","title":"Deer scrapes","domain":"hunting","also":["buck scrape","deer scrape","scrape under a branch","licking branch","deer sign","mock scrape"],"def":"A scrape is a patch of bare earth that a buck paws clear under an overhanging branch and marks with scent, mostly in the weeks before the rut.","look":["a pawed oval of bare dirt, often 1 to 3 feet (30 to 90 cm) across","a chewed or broken licking branch about head height above it","fresh tracks and a musky smell in it when it is active"],"use":"Scrapes are scent posts that bucks and does visit. A fresh, damp scrape clear of leaves shows recent use; scrapes along field edges and trails show travel routes. Many hunters watch them from downwind.","not":"Do not walk through or touch a scrape; your scent can make deer avoid it. Do not assume a buck visits it in daylight.","steps":["Check if leaves have blown back in (older) or the dirt is fresh.","Look for the licking branch above it.","Find tracks in the dirt for direction.","Set up downwind of it, using the scent cone in Hunt."],"alike":["Turkey scratching: smaller scattered patches with no licking branch","Squirrel digging: small holes, not a pawed oval"],"rel":["deer_rub","deer_track","deer_scat"],"src":["usfs","state-dnr"],"ask":"Tell me about deer scrapes"},{"id":"deer_sign_reading","title":"Reading deer sign","domain":"hunting","also":["deer sign","signs of deer","how to scout for deer","deer scouting","where are the deer"],"def":"Deer sign is the tracks, scat, rubs, scrapes, beds, and browsed plants that deer leave, and reading it shows where they travel, feed, and rest.","look":["trails and tracks between thick cover and food","scat piles, oval beds pressed in leaves or snow","rubs and scrapes in fall"],"use":"Sign is strongest where several kinds come together: a trail with fresh tracks, scat, and rubs near food or a pinch point. Fresh sign matters more than old sign.","not":"Do not scout through bedding areas during the season; you will push deer out. Respect property lines and posted land.","steps":["Walk edges between cover and food and look for trails.","Check freshness of tracks and scat.","Look for rub lines and scrapes in fall.","Note what you find, then check the wind before you pick a stand."],"rel":["deer_scat","deer_track","deer_rub","deer_scrape"],"src":["usfs","state-dnr"],"ask":"Tell me about reading deer sign"},{"id":"panic_attack_help","title":"Panic attack: what to do","domain":"mental","also":["panic attack","can't breathe panic","heart racing anxiety","freaking out"],"def":"A panic attack is a sudden wave of fear with a racing heart, fast breathing, shaking, or a sense of doom; it peaks within minutes and passes.","look":["fast breathing, tingling hands, chest tightness","a strong urge to flee","symptoms that ease within about 20 minutes"],"use":"Sit down, breathe out slowly, longer than you breathe in, name five things you can see, and remind yourself it will pass. Stay with someone who is panicking and speak calmly.","not":"Do not assume chest pain is panic if the person has heart risks, is older, or the pain spreads to the arm or jaw; treat it as a medical emergency.","steps":["Sit or stand still somewhere steady.","Breathe in for 4, out for 6, for a few minutes.","Name what you see, hear, and feel.","Remind yourself the wave passes."],"call":"Call 911 for chest pain, fainting, or trouble breathing that does not ease. Call or text 988 any time for the Suicide & Crisis Lifeline; veterans can press 1. Call 911 if someone is in immediate danger.","rel":["scared_lost_calm","when_get_help"],"src":["nimh","samhsa"]},{"id":"scared_lost_calm","title":"Scared or lost: calming down so you can act","domain":"mental","also":["I am scared","I think we are lost and I'm scared","afraid in the woods","calm down"],"def":"Fear in a bad situation is normal; slowing your breathing and taking one small practical step at a time brings back clear thinking.","look":["racing thoughts and an urge to hurry","a group arguing or splitting up","darkness or weather adding pressure"],"use":"Stop, sit, breathe slowly, then do the next useful thing: check water, warmth, and shelter, look at the map, and decide together.","not":"Do not rush off, split up, or make big decisions in the first minutes of fear.","call":"Call 911 if you have signal and are lost or hurt.","rel":["lost_stop_plan","panic_attack_help"],"src":["atp3-50-21","nimh"]},{"id":"suicidal_thoughts_help","title":"Thoughts of suicide or not wanting to be here","domain":"mental","also":["I don't want to be here","suicidal","want to die","friend talking about suicide","kill myself"],"def":"Thoughts of suicide or of not wanting to be alive are a sign of serious pain and deserve immediate support, not judgment.","look":["talk of being a burden or wanting to die","giving things away or saying goodbye","access to a gun, pills, or other means"],"use":"Take it seriously, stay with the person if it is safe, ask directly whether they are thinking of suicide, listen, and help them call or text 988. Move guns and pills away if you safely can.","not":"Do not leave a person at risk alone, promise to keep it secret, or argue about whether they really mean it.","call":"Call or text 988 any time for the Suicide & Crisis Lifeline; veterans can press 1. Call 911 if someone is in immediate danger.","rel":["when_get_help","helping_friend_crisis"],"src":["988","vcl","samhsa"]},{"id":"acute_stress_close_call","title":"Shaken after a close call, crash, or bad hunt","domain":"mental","also":["acute stress","shaken up after accident","can't stop thinking about it","trauma after close call"],"def":"After a frightening event it is common to feel shaky, numb, jumpy, or replay it for days; for most people these reactions fade over a few weeks.","look":["trouble sleeping and replaying the event","feeling on edge or numb","avoiding the place or activity"],"use":"Get safe, warm, and fed, talk with someone you trust, keep simple routines, and give it time.","not":"Do not use alcohol or drugs to blot it out, and do not push yourself to retell every detail if you do not want to.","call":"Seek help if reactions last more than a few weeks or interfere with daily life. Call or text 988 any time for the Suicide & Crisis Lifeline; veterans can press 1. Call 911 if someone is in immediate danger.","rel":["when_get_help","grief_after_loss"],"src":["va-ptsd","samhsa"]},{"id":"grief_after_loss","title":"Grief after a death, and grief after a kill","domain":"mental","also":["grief","someone died","sad after killing a deer","hunter remorse","grieving"],"def":"Grief is the natural response to loss; it can come in waves of sadness, anger, guilt, or numbness, and some hunters feel a quieter grief after a kill.","look":["waves of feeling that come and go","tiredness and poor sleep","guilt or replaying what happened"],"use":"Let the feelings come, talk with people who care, keep basic routines, and honor the loss in your own way.","not":"Do not judge yourself for how you grieve or how long it takes.","call":"Reach out to a clinician if grief stays crushing for months or you have thoughts of harming yourself. Call or text 988 any time for the Suicide & Crisis Lifeline; veterans can press 1. Call 911 if someone is in immediate danger.","rel":["acute_stress_close_call"],"src":["nimh","samhsa"]},{"id":"when_get_help","title":"When to get professional mental health help","domain":"mental","also":["need a therapist","mental health help","find counseling","988 lifeline"],"def":"Professional help makes sense when distress lasts for weeks, gets in the way of work, sleep, or family, or includes thoughts of self-harm.","look":["low mood or worry most days for two weeks or more","drinking or drug use to cope","thoughts of death or self-harm"],"use":"Talk to a doctor or a licensed counselor; the 988 Lifeline is free, confidential, and available 24/7 by call or text.","not":"Do not wait for it to get worse before reaching out.","call":"Call or text 988 any time for the Suicide & Crisis Lifeline; veterans can press 1. Call 911 if someone is in immediate danger.","rel":["suicidal_thoughts_help"],"src":["988","nimh","samhsa"]},{"id":"exhaustion_bad_decisions","title":"Exhaustion, poor sleep, and bad decisions in the field","domain":"mental","also":["too tired to think","sleep deprived","fatigue mistakes","exhausted hiking"],"def":"Fatigue, cold, hunger, and poor sleep slow thinking and make people take risks they would never take rested.","look":["clumsiness and short temper","pushing on to reach a goal despite warning signs","forgetting simple steps"],"use":"Stop, eat, drink, warm up, and rest before any big decision; set a turnaround time and keep it.","not":"Do not drive, climb, or handle firearms when you are exhausted.","rel":["scared_lost_calm"],"src":["atp3-50-21","cdc"]},{"id":"alcohol_outdoors_risk","title":"Alcohol and drugs as a way to cope outdoors","domain":"mental","also":["drinking at camp","alcohol and hypothermia","drunk hunting","using to cope"],"def":"Alcohol and drugs can feel like relief, but outdoors they raise the risk of hypothermia, falls, drowning, and firearm accidents, and they deepen low mood afterward.","look":["drinking to sleep or calm down","drinking around water, fire, or firearms","needing more to get the same effect"],"use":"Keep alcohol away from firearms, boats, and climbing, and look for other ways to unwind: food, warmth, talk, and rest.","not":"Do not mix alcohol with firearms, driving, or cold-weather travel.","call":"SAMHSA's National Helpline, 1-800-662-4357, is free and confidential. Call or text 988 any time for the Suicide & Crisis Lifeline; veterans can press 1. Call 911 if someone is in immediate danger.","rel":["when_get_help"],"src":["samhsa","cdc"]},{"id":"helping_friend_crisis","title":"Helping a friend in crisis","domain":"mental","also":["friend in crisis","how to help someone struggling","listen to a friend","someone is not okay"],"def":"Helping a friend in crisis mostly means staying with them, listening without fixing, and connecting them with help.","look":["a friend withdrawing or talking about hopelessness","sudden changes in behavior","talk of suicide"],"use":"Ask how they are and listen, say you care, ask directly about suicide if you are worried, and help them call or text 988 or a professional.","not":"Do not lecture, minimize their feelings, or take over their choices.","call":"Call or text 988 any time for the Suicide & Crisis Lifeline; veterans can press 1. Call 911 if someone is in immediate danger.","rel":["suicidal_thoughts_help"],"src":["988","samhsa"]},{"id":"anxiety_before_event","title":"Anxiety before a storm, trip, or hunt","domain":"mental","also":["nervous before trip","storm anxiety","worried about hunt","pre-trip anxiety"],"def":"Worry before a storm or a big trip is common; preparing, planning, and calming the body bring it down to a useful level.","look":["racing thoughts at night","tight chest or upset stomach","checking the forecast over and over"],"use":"Make a short checklist, do one preparation step, then do something calming such as slow breathing or a walk.","not":"Do not let worry push you into skipping sleep or food before a trip.","call":"Talk to a clinician if anxiety gets in the way of daily life. Call or text 988 any time for the Suicide & Crisis Lifeline; veterans can press 1. Call 911 if someone is in immediate danger.","rel":["grounding_breathing"],"src":["nimh","samhsa"]},{"id":"grounding_breathing","title":"Slow breathing and grounding","domain":"mental","also":["breathing exercise","grounding technique","5 4 3 2 1","calm my nerves"],"def":"Slow breathing and grounding are simple ways to calm a racing body and mind: breathe out longer than in, and notice what is around you.","look":["breathing in for about four counts, out for six","naming five things you see, four you hear, three you can touch","shoulders dropping as the body settles"],"use":"Sit or stand steady, breathe slowly for a few minutes, and name what you sense around you.","not":"This does not replace medical care for chest pain or trouble breathing.","rel":["panic_attack_help","anxiety_before_event"],"src":["nimh","va-ptsd"]},{"id":"low_mood_winter","title":"Low mood in short winter days or isolation","domain":"mental","also":["winter blues","seasonal depression","SAD","sad in winter"],"def":"Many people feel lower in short, dark days or in isolation; some have seasonal affective disorder, a form of depression that returns each winter.","look":["low energy, oversleeping, and craving carbohydrates in winter","loss of interest that lasts weeks","pulling away from people"],"use":"Get outside in daylight, move your body, keep regular sleep and meals, and stay in touch with people.","not":"Do not ignore weeks of low mood or thoughts of self-harm.","call":"See a clinician if low mood lasts two weeks or more. Call or text 988 any time for the Suicide & Crisis Lifeline; veterans can press 1. Call 911 if someone is in immediate danger.","rel":["when_get_help","loneliness_help"],"src":["nimh"]},{"id":"loneliness_help","title":"Loneliness","domain":"mental","also":["lonely","isolated","no one to talk to"],"def":"Loneliness is the painful feeling of being disconnected; it is common and it affects health, and small regular contact helps.","look":["long stretches without talking to anyone","feeling unseen even around people","low mood or poor sleep"],"use":"Reach out to one person today, join a regular activity, help someone else, and keep in touch on a schedule.","not":"Do not wait for others to reach out first.","call":"988 is also there if you just need to talk. Call or text 988 any time for the Suicide & Crisis Lifeline; veterans can press 1. Call 911 if someone is in immediate danger.","rel":["low_mood_winter"],"src":["samhsa","nimh"]},{"id":"anger_conflict_group","title":"Anger and conflict in a family or group under stress","domain":"mental","also":["arguing in group","family fighting during outage","hunt party conflict","losing temper"],"def":"Stress, hunger, cold, and fatigue shorten tempers; groups do better when they pause, meet basic needs, and decide calmly.","look":["raised voices and blame","people splitting off","decisions made in anger"],"use":"Take a break, eat and warm up, let each person speak, and agree on one next step together.","not":"Do not make safety decisions in the middle of a fight, and keep firearms unloaded when tempers rise.","call":"Call 911 if anyone is threatened or hurt.","rel":["exhaustion_bad_decisions"],"src":["samhsa","atp3-50-21"]},{"id":"shame_after_mistake","title":"Shame after a mistake","domain":"mental","also":["I messed up","feel ashamed","my fault","guilt after mistake"],"def":"After a mistake, shame can feel overwhelming; owning what happened, making it right where you can, and learning from it is healthier than self-punishment.","look":["replaying the mistake","hiding it from others","harsh self-talk"],"use":"Name what happened, take one step to repair or learn, and talk to someone you trust.","not":"Do not punish yourself with risky behavior or isolation.","call":"Call or text 988 any time for the Suicide & Crisis Lifeline; veterans can press 1. Call 911 if someone is in immediate danger.","rel":["acute_stress_close_call","when_get_help"],"src":["samhsa","va-ptsd"]},{"id":"caregiver_burnout","title":"Caregiver or parent burnout in a long outage","domain":"mental","also":["burned out parent","caregiver stress","exhausted caring for family"],"def":"Caring for others through a long outage or crisis drains people; burnout shows up as exhaustion, irritability, and feeling numb.","look":["no time to eat or sleep yourself","snapping at people you care for","feeling hopeless or numb"],"use":"Share tasks, take short breaks, eat and sleep when you can, and ask neighbors or relatives for help.","not":"Do not skip your own medicines, food, or rest.","call":"Call or text 988 any time for the Suicide & Crisis Lifeline; veterans can press 1. Call 911 if someone is in immediate danger.","rel":["check_older_relatives"],"src":["samhsa","cdc"]},{"id":"trauma_find_clinician","title":"Finding help for lasting trauma","domain":"mental","also":["PTSD","trauma therapy","find a therapist","nightmares months later"],"def":"When nightmares, flashbacks, or avoidance last more than a month after a frightening event, it may be post-traumatic stress, and effective treatment exists.","look":["flashbacks or nightmares","avoiding reminders","feeling on edge most of the time"],"use":"Talk to a doctor or a licensed mental health professional; veterans can use VA services, and SAMHSA's helpline can point to local care.","not":"Do not try to manage it alone with alcohol or drugs.","call":"SAMHSA's National Helpline, 1-800-662-4357. Call or text 988 any time for the Suicide & Crisis Lifeline; veterans can press 1. Call 911 if someone is in immediate danger.","rel":["acute_stress_close_call","when_get_help"],"src":["va-ptsd","samhsa","nimh"]},{"id":"morale_routines","title":"Routines that keep morale up","domain":"mental","also":["keep spirits up","morale in survival","daily routine crisis"],"def":"Simple routines such as regular meals, daylight, movement, shared tasks, and time with others keep morale steady through long hard periods.","look":["meals at regular times","a daily walk or chore outside","a moment to talk or laugh together"],"use":"Set a daily rhythm, give everyone a job, and mark small successes.","not":"Do not let days blur into no structure for weeks.","rel":["low_mood_winter"],"src":["atp3-50-21","samhsa"]},{"id":"veterans_support","title":"Support for veterans","domain":"mental","also":["veterans crisis line","veteran struggling","VA mental health"],"def":"Veterans and their families can reach the Veterans Crisis Line by calling 988 and pressing 1, by text, or by chat, and VA offers mental health care.","look":["a veteran withdrawing or drinking more","anniversary dates of hard events","talk of hopelessness"],"use":"Call 988 and press 1, or text 838255, and connect with VA mental health services.","not":"Do not wait for a crisis to reach out.","call":"Veterans Crisis Line: dial 988 then press 1, or text 838255. Call 911 if someone is in immediate danger.","rel":["suicidal_thoughts_help"],"src":["vcl","va-ptsd"]},{"id":"stress_after_disaster","title":"Stress after a disaster","domain":"mental","also":["disaster stress","after the storm stress","can't cope after flood"],"def":"After a disaster, people often feel anxious, sad, angry, or numb, have trouble sleeping, and worry about money and home; support and time help most recover.","look":["trouble sleeping or concentrating","headaches or stomach upset","feeling overwhelmed by cleanup and paperwork"],"use":"Take care of basics, stay connected, limit news, take breaks from cleanup, and use crisis counseling if you need it.","not":"Do not ignore lasting distress or thoughts of self-harm.","call":"SAMHSA's Disaster Distress Helpline: call or text 1-800-985-5990. Call or text 988 any time for the Suicide & Crisis Lifeline; veterans can press 1. Call 911 if someone is in immediate danger.","rel":["acute_stress_close_call"],"src":["samhsa","fema"]},{"id":"map_orient_compass","title":"Orienting a map with a compass","domain":"navigation","also":["set the map","orient the map","line up map and compass","turn the map to north","map and compass basics"],"def":"Orienting a map means turning it so north on the map points to north on the ground, after allowing for declination, so the map matches what you see.","look":["the map's north arrow or meridian lines","the compass needle settled and away from metal","known features ahead lining up with the map"],"use":"Lay the compass on the map, line its edge with a north-south line, and turn map and compass together until the needle points to north, adjusted for the declination printed on the map.","not":"Do not orient the map next to a vehicle, rifle, or phone, which can pull the needle. Do not forget declination on an older map.","steps":["Find north on the map.","Set the compass for the map's declination.","Lay the compass edge on a north-south line.","Turn the map until the needle lines up.","Check that real features match the map."],"rel":["bearing_take_follow","north_types"],"src":["fm3-25-26","usgs"]},{"id":"declination_basics","title":"Declination: magnetic versus true north","domain":"navigation","also":["compass doesn't match the map","compass and map disagree","magnetic variation","declination angle","adjust for declination"],"def":"Declination is the angle between where a compass needle points (magnetic north) and true north on the map; it differs by place and slowly changes over the years.","look":["the declination diagram and year printed on the map","a compass with an adjustable declination setting","bearings that drift off by the same few degrees"],"use":"Look up current declination for your area from NOAA, set it on your compass or add or subtract it, and note the year of the value you used.","not":"Do not trust an old map's printed value without checking its year, and do not hard-code one number for a whole region.","rel":["map_orient_compass","north_types"],"src":["fm3-25-26","noaa","usgs"]},{"id":"north_types","title":"True north, magnetic north, and grid north","domain":"navigation","also":["grid north","true north vs magnetic north","three norths","which north"],"def":"True north points to the North Pole, magnetic north is where a compass needle points, and grid north follows the vertical grid lines printed on a map; the small angles between them matter over distance.","look":["the three-arrow diagram in a topographic map's margin","grid lines (UTM) on the map","the compass needle"],"use":"Use the map's diagram to convert between them, and be consistent: plot and follow bearings in the same north.","not":"Do not mix a grid bearing from the map with a magnetic bearing from the compass without converting.","rel":["declination_basics"],"src":["fm3-25-26"]},{"id":"bearing_take_follow","title":"Taking and following a compass bearing","domain":"navigation","also":["follow a bearing","take a bearing","walk a compass heading","shoot a bearing","azimuth"],"def":"A bearing is the direction to a target measured in degrees clockwise from north; you take it from the map or a landmark, then walk it by sighting from object to object.","look":["the direction-of-travel arrow on the compass","the needle boxed in the orienting arrow","a tree or rock on the line ahead"],"use":"Set the bearing, hold the compass level in front of you, turn until the needle sits in the orienting arrow, pick a landmark on the line, walk to it, and repeat.","not":"Do not walk with your eyes on the compass the whole way, and do not take bearings near metal or a running vehicle.","steps":["Set the bearing on the compass.","Box the needle in the orienting arrow.","Pick a landmark on the line.","Walk to it.","Repeat until you reach the target."],"rel":["map_orient_compass","aiming_off_handrails"],"src":["fm3-25-26"]},{"id":"contour_terrain_features","title":"Contour lines and terrain features","domain":"navigation","also":["contour lines","topo map lines","reading a topographic map","saddle ridge valley","squiggly lines on a map"],"def":"Contour lines join points of equal elevation, so their shape and spacing show the land: close lines are steep, wide lines are gentle, and Vs pointing uphill mark streams and draws.","look":["contour interval printed in the margin","closed rings for hilltops, with tick marks for depressions","Vs pointing uphill for valleys and draws, downhill for spurs and ridges"],"use":"Match the five main shapes, hill, saddle, valley, ridge, and depression, to what you see, and use them to plan routes that avoid steep ground.","not":"Do not read a tight cluster of lines as a trail; it is a steep slope or cliff.","rel":["map_distance_pace","aiming_off_handrails"],"src":["fm3-25-26","usgs"]},{"id":"map_distance_pace","title":"Measuring distance and keeping a pace count","domain":"navigation","also":["pace count","how far have I walked","measure distance on a map","pacing"],"def":"Distance on a map is measured against its scale bar, and on the ground you track it with a pace count: the number of your double steps in 100 meters on your normal stride.","look":["the scale bar in the map margin","your own tested pace count","more paces uphill, in brush, snow, or the dark"],"use":"Measure your pace count on a known 100 m course, count every second step while walking, and tie a knot or move a bead at each 100 m.","not":"Do not use someone else's pace count, and do not forget to add paces for slopes and rough ground.","rel":["bearing_take_follow","contour_terrain_features"],"src":["fm3-25-26"]},{"id":"gps_vs_map","title":"GPS and phone versus map and compass","domain":"navigation","also":["GPS not working","phone died navigation","do I need a compass if I have a phone","GPS in canyon"],"def":"A GPS or phone gives a fast position but needs battery and sky view; a paper map and baseplate compass keep working when the screen dies or the signal drops.","look":["battery below half on a long day","deep canyons, heavy cover, or cliffs blocking the fix","a printed map of the area in your pack"],"use":"Carry a paper map and compass as backup, keep the phone warm and in power-saving mode, and check your position on the map at each landmark.","not":"Do not head out with only a phone, and do not trust a position that jumps around in thick cover.","rel":["map_orient_compass","lost_stop_plan"],"src":["fm3-25-26","nps","usgs"]},{"id":"lost_stop_plan","title":"Lost? Stop, think, observe, plan","domain":"navigation","also":["I'm lost","what to do if lost","turned around in the woods","don't know where I am","STOP lost"],"def":"When you realize you are lost, the first job is to stop moving, calm down, and work from your last known point; staying put is usually safest if you cannot work it out.","look":["the last place you were sure of","streams, ridges, or roads you crossed","how much daylight, water, and warmth you have"],"use":"Sit down, breathe, look and listen, retrace on the map if you can, and if not, stay put, make yourself visible and heard, and prepare for the night.","not":"Do not keep walking hoping it turns familiar, split up a group, or travel at night in rough country.","steps":["Stop where you are.","Think back to your last known point.","Observe: landmarks, sun, sounds, daylight.","Plan: retrace a sure route or stay and signal."],"call":"Call 911 if you have signal; a text can go through when a call will not.","rel":["gps_vs_map","aiming_off_handrails"],"src":["nps","usfs","atp3-50-21"]},{"id":"aiming_off_handrails","title":"Handrails, catching features, and aiming off","domain":"navigation","also":["handrail navigation","catching feature","aiming off","terrain association","follow a ridgeline"],"def":"Terrain association uses long features to guide you: a handrail is something you walk alongside, a catching feature stops you if you overshoot, and aiming off means deliberately aiming to one side of a target on a line feature.","look":["a stream, ridge, trail, or field edge running your way","a road, river, or lake beyond your target","a known side to turn toward when you hit the line"],"use":"Pick a handrail toward your goal, note a catching feature past it, and when heading for a point on a stream or trail, aim a little to one side so you know which way to turn.","not":"Do not assume a stream leads to help; it can lead into cliffs, swamps, or thick brush.","rel":["bearing_take_follow","contour_terrain_features"],"src":["fm3-25-26"]},{"id":"phone_compass_unreliable","title":"When a phone compass is unreliable","domain":"navigation","also":["phone compass wrong","calibrate phone compass","compass app not accurate"],"def":"A phone's compass is a magnetic sensor that metal, magnets in cases, vehicles, and a skipped calibration can throw off by many degrees.","look":["a magnetic phone case or mount","readings that swing when you move near a truck or rifle","a calibration prompt"],"use":"Calibrate by moving the phone in a figure-eight away from metal, remove magnetic cases, and cross-check against a baseplate compass or the sun.","not":"Do not trust a phone compass inside a vehicle or next to steel.","rel":["gps_vs_map"],"src":["fm3-25-26"]},{"id":"stream_crossing_choice","title":"Stream crossings: when to go around","domain":"navigation","also":["crossing a river","ford a stream","safe to cross a creek","fast water crossing"],"def":"A stream is safe to cross only when it is shallow, slow, and has a clear landing; knee-deep fast water can knock an adult down.","look":["water above the knee or moving faster than a walk","muddy, rising water after rain","rapids, logjams, or falls downstream"],"use":"Scout for a wide, shallow, braided spot, unbuckle the pack's hip belt, face upstream with a stick or partner, and shuffle your feet.","not":"Do not cross in flood, above a logjam or falls, or barefoot on sharp rock, and do not tie yourself into a rope across fast water.","rel":["aiming_off_handrails"],"src":["nps","atp3-50-21"]},{"id":"compass_parts","title":"Parts of a baseplate compass","domain":"navigation","also":["baseplate compass","orienting arrow","compass housing","direction of travel arrow"],"def":"A baseplate compass has a clear base with a direction-of-travel arrow, a rotating housing marked in degrees with an orienting arrow and lines, and a magnetic needle whose red end points to magnetic north.","look":["the red end of the needle","the degree ring on the housing","a declination adjustment on better models"],"use":"Learn which arrow is which at home: you set bearings with the housing and walk where the direction-of-travel arrow points.","not":"Do not store a compass next to magnets or speakers, which can weaken or reverse the needle.","rel":["bearing_take_follow","map_orient_compass"],"src":["fm3-25-26"]},{"id":"night_navigation","title":"Navigating at night","domain":"navigation","also":["walking in the dark","night hike navigation","lost at night"],"def":"Moving at night is slower and riskier; it works only on a known trail or a sure handrail with a good light and a careful bearing.","look":["a bright headlamp and spare batteries","a trail, road, or stream edge to follow","landmarks you can find by light"],"use":"Shorten legs between landmarks, count paces, check the compass often, and stop and camp if the ground gets rough.","not":"Do not travel cross-country at night in steep or unknown terrain if you can safely wait for light.","rel":["lost_stop_plan","headlamp_red_light"],"src":["fm3-25-26","nps"]},{"id":"sun_direction_rough","title":"Rough direction from the sun","domain":"navigation","also":["sun direction","find north without compass","shadow stick","which way is east"],"def":"The sun gives only a rough direction: it rises in the east, sets in the west, and in the northern hemisphere is generally to the south at midday, with big seasonal shifts.","look":["a stick's shadow tip moving from west to east over 15-20 minutes","time of day and season","clear enough sky to see shadows"],"use":"Mark a shadow tip, wait 15 minutes, mark again; the line from first to second mark runs roughly west to east. Use it as a check, not a precise bearing.","not":"Do not treat sun directions as exact, especially near sunrise, sunset, or in summer when the sun rises well north of east.","rel":["stars_north","phone_compass_unreliable"],"src":["fm3-25-26","atp3-50-21"]},{"id":"stars_north","title":"Stars as a rough north reference","domain":"navigation","also":["north star","Polaris","big dipper north","find north at night"],"def":"In the northern hemisphere the North Star, Polaris, sits almost due north; the two outer stars of the Big Dipper's cup point to it.","look":["the Big Dipper's pointer stars","a moderately bright star alone in its area","clear sky away from bright lights"],"use":"Follow the pointer stars about five times their gap to Polaris, then pick a ground landmark below it to hold your direction.","not":"Do not use it as a substitute for a compass on long, precise routes.","rel":["sun_direction_rough","night_navigation"],"src":["fm3-25-26","nasa"]},{"id":"mark_route_self","title":"Marking a route for yourself","domain":"navigation","also":["mark my trail","flagging tape","find my way back","blaze a trail"],"def":"Marking your own route with removable flagging or noted landmarks makes the return trip easier, especially in thick woods or snow.","look":["bright, removable flagging tape","waypoints saved only if you chose to","landmarks noted at each turn"],"use":"Tie flagging at eye level where you can see the next one, look back often so you know the return view, and remove the flagging on your way out.","not":"Do not cut blazes into trees or leave flagging behind on land where it is not allowed.","rel":["aiming_off_handrails","lost_stop_plan"],"src":["fm3-25-26","usfs"]},{"id":"whiteout_fog_navigation","title":"Whiteout or fog: stay put or follow a sure handrail","domain":"navigation","also":["lost in fog","whiteout","can't see in snowstorm","fog navigation"],"def":"In fog or a whiteout you lose landmarks and depth; most often the safest choice is to stop, shelter, and wait unless a sure handrail leads you out.","look":["no visible landmarks beyond a few yards","snow or fog hiding drop-offs","a trail, fence, or stream you can follow by touch or sight"],"use":"Stop, get warm and sheltered, and wait it out, or follow a known handrail with compass and pace count, staying together.","not":"Do not head cross-country toward ridges, cornices, cliffs, or frozen lakes you cannot see.","rel":["lost_stop_plan","aiming_off_handrails"],"src":["nws","fm3-25-26"]},{"id":"altimeter_navigation","title":"Altimeter or barometer as a rough navigation aid","domain":"navigation","also":["altimeter navigation","barometer altitude","elevation to find location"],"def":"An altimeter estimates your height from air pressure, and matching that height to a contour on the map helps narrow down where you are along a trail or slope.","look":["a known elevation to calibrate at the trailhead","weather changes shifting the reading","a contour line that matches your height"],"use":"Calibrate at a known height, recheck at known points, and combine the reading with the trail, stream, or ridge you are on.","not":"Do not trust an altimeter alone during a changing storm; pressure swings change the reading.","rel":["contour_terrain_features"],"src":["fm3-25-26","nws"]},{"id":"map_scale_limits","title":"Map scale and what a map does not show","domain":"navigation","also":["map scale","1:24000","zoom limits","what a map pack shows"],"def":"A map's scale sets how much detail it can show; a 1:24,000 topographic map shows small streams and contours, while a small-scale map leaves out trails, cliffs, and new roads.","look":["the scale and date in the margin","missing new trails, logging roads, or beaver flooding","contour interval size"],"use":"Use the largest-scale map you can get for foot travel and expect changes on the ground since the map's date.","not":"Do not assume a map pack shows roads, buildings, or land ownership unless it says so.","rel":["map_distance_pace","gps_vs_map"],"src":["usgs","fm3-25-26"]},{"id":"vehicle_vs_foot_travel","title":"Driving versus walking when the road is not on the map","domain":"navigation","also":["car stuck on back road","leave the car or walk","unmarked forest road"],"def":"On unmapped back roads the vehicle is shelter, a big visible target, and a supply cache, so staying with it is often safer than walking out.","look":["fuel, weather, and daylight left","distance to the last known road or house","whether anyone knows your route"],"use":"Stay with the vehicle when stuck unless help is close and the way is sure; walking out is safer by daylight on a known road.","not":"Do not run the engine for warmth with the exhaust blocked by snow.","call":"Call 911 if you have signal; a text may get through when a call will not.","rel":["lost_stop_plan"],"src":["ready","nws"]},{"id":"resection_intersection","title":"Resection and intersection","domain":"navigation","also":["triangulation","resection","find my position with compass","intersection navigation"],"def":"Resection finds your own position by taking bearings to two or three landmarks you can identify on the map and drawing back-bearings; intersection finds a distant point from two known spots.","look":["two or three distinct, mapped landmarks far apart in direction","back-bearings: add or subtract 180°","lines crossing in a small triangle"],"use":"Take bearings to the landmarks, convert to back-bearings for the map, draw the lines, and you are near where they cross.","not":"Do not use landmarks that are close together in direction; the lines cross at a shallow angle and mislead.","rel":["bearing_take_follow","north_types"],"src":["fm3-25-26"]},{"id":"grid_coordinates","title":"Reading grid coordinates on a map","domain":"navigation","also":["UTM coordinates","grid reference","read right then up","give my location coordinates"],"def":"Grid coordinates locate a point using the map's grid lines: read the easting (left to right) first, then the northing (bottom to top).","look":["the grid line labels along the map edges","a coordinate scale or ruler","the datum and zone printed in the margin"],"use":"Read right, then up; give the coordinates and the datum to rescuers if asked, or read latitude and longitude from your phone.","not":"Do not mix up datums or give only partial numbers to rescuers.","rel":["map_scale_limits"],"src":["fm3-25-26","usgs"]},{"id":"turnaround_time","title":"Turnaround time and trip plans","domain":"navigation","also":["turnaround time","trip plan","leave a plan","how late to hike"],"def":"A turnaround time is the hour you turn back no matter where you are, set so you are out before dark or bad weather; a trip plan tells someone your route and return.","look":["sunset time and forecast","your pace on the way in","who has your plan"],"use":"Set the turnaround time before you start, keep it, and leave your route and return time with someone who will call for help.","not":"Do not push past the turnaround to reach a summit or spot.","rel":["lost_stop_plan","day_hike_essentials"],"src":["nps","usfs"]},{"id":"ramps","title":"Ramps (wild leek)","domain":"plants","also":["wild leek","Allium tricoccum","ramp"],"def":"Ramps are wild leeks with two or three broad smooth leaves in spring and a strong onion-garlic smell.","look":["two or three broad smooth leaves per plant in spring, red-purple stalk base, strong onion and garlic smell","every leaf smells of onion when crushed"],"use":"Learn it as an identification first. Eat it only after you have matched every feature in person, ideally with someone who knows the plant, from ground that was not sprayed or beside a busy road, and start with a small amount. Check smell on every leaf. False hellebore and lily of the valley grow in the same woods and are deadly.","not":"Do not eat it on a photo match or a single feature, and do not eat it if you cannot rule out its look-alikes.","alike":["False hellebore (Indian poke): Big pleated leaves that wrap the stem in a spiral; wet woods and meadows. No onion smell. Sometimes mistaken for ramps. Deadly","Lily of the valley: Two smooth upright leaves, small white bells on an arching stem, red berries. Mistaken for ramps. Every part is deadly"],"rel":["false_hellebore","lily_of_valley"],"src":["usda-nrcs","usfs","atp3-50-21"],"ask":"Tell me about ramps"},{"id":"false_hellebore","title":"False hellebore (Indian poke)","domain":"plants","also":["Indian poke","Veratrum","green hellebore","corn lily","Veratrum viride"],"def":"False hellebore is a wetland plant with large pleated leaves spiraling up the stem, and it is deadly.","look":["big pleated leaves that wrap the stem in a spiral","wet woods and meadows","no onion smell","no onion smell at all"],"use":"Learn it so you can avoid it and warn others. Sometimes mistaken for ramps. Deadly.","not":"Never eat, brew, chew, or burn any part of it, and wash your hands after touching it. Do not trust a photo or a taste test.","alike":["Ramps (wild leek): Two or three broad smooth leaves per plant in spring, red-purple stalk base, strong onion and garlic smell. Check smell on every leaf. False hellebore and lily of the valley grow in the same woods and are deadly"],"call":"If someone may have eaten it, call Poison Control at 1-800-222-1222, or 911 for trouble breathing, seizures, or collapse.","rel":["ramps"],"src":["usda-nrcs","usfs","atp3-50-21","poison-control"],"ask":"Tell me about false hellebore"},{"id":"lily_of_valley","title":"Lily of the valley","domain":"plants","also":["lily of the valley","Convallaria","May bells","Convallaria majalis"],"def":"Lily of the valley is a garden and wild plant with small white bell flowers, and every part is deadly to the heart.","look":["two smooth upright leaves, small white bells on an arching stem, red berries","no onion smell, unlike ramps"],"use":"Learn it so you can avoid it and warn others. Mistaken for ramps. Every part is deadly.","not":"Never eat, brew, chew, or burn any part of it, and wash your hands after touching it. Do not trust a photo or a taste test.","alike":["Ramps (wild leek): Two or three broad smooth leaves per plant in spring, red-purple stalk base, strong onion and garlic smell. Check smell on every leaf. False hellebore and lily of the valley grow in the same woods and are deadly"],"call":"If someone may have eaten it, call Poison Control at 1-800-222-1222, or 911 for trouble breathing, seizures, or collapse.","rel":["ramps"],"src":["usda-nrcs","usfs","atp3-50-21","poison-control"],"ask":"Tell me about lily of the valley"},{"id":"chicory","title":"Chicory","domain":"plants","also":["blue sailors","Cichorium","coffee weed","succory","Cichorium intybus"],"def":"Chicory is a roadside plant with sky-blue flowers on stiff stems whose leaves and roasted roots are used as food.","look":["sky blue flowers on stiff, nearly leafless stems along roadsides","milky sap","flowers close by afternoon"],"use":"Learn it as an identification first. Eat it only after you have matched every feature in person, ideally with someone who knows the plant, from ground that was not sprayed or beside a busy road, and start with a small amount.","not":"Do not eat it on a photo match or a single feature, and do not eat it if you cannot rule out its look-alikes.","alike":["Dandelion: Rosette of toothed leaves, one yellow flower per hollow stalk, milky sap"],"rel":["dandelion_greens"],"src":["usda-nrcs","usfs","atp3-50-21"],"ask":"Tell me about chicory"},{"id":"red_clover","title":"Red clover","domain":"plants","also":["Trifolium pratense","clover"],"def":"Red clover is a common field plant with round pink-purple flower heads and three leaflets marked with a pale V.","look":["pink-purple round flower heads","three leaflets with a pale V mark","upright, taller than white clover"],"use":"Learn it as an identification first. Eat it only after you have matched every feature in person, ideally with someone who knows the plant, from ground that was not sprayed or beside a busy road, and start with a small amount.","not":"Do not eat it on a photo match or a single feature, and do not eat it if you cannot rule out its look-alikes.","alike":["White clover: Low creeping plant, white round flower heads, three leaflets often with a pale band"],"rel":["white_clover"],"src":["usda-nrcs","usfs","atp3-50-21"],"ask":"Tell me about red clover"},{"id":"white_clover","title":"White clover","domain":"plants","also":["Trifolium repens","Dutch clover","lawn clover"],"def":"White clover is a low creeping lawn plant with round white flower heads and three leaflets.","look":["low creeping plant, white round flower heads, three leaflets often with a pale band","stems creep and root along the ground"],"use":"Learn it as an identification first. Eat it only after you have matched every feature in person, ideally with someone who knows the plant, from ground that was not sprayed or beside a busy road, and start with a small amount.","not":"Do not eat it on a photo match or a single feature, and do not eat it if you cannot rule out its look-alikes.","alike":["Red clover: Pink-purple round flower heads; three leaflets with a pale V mark"],"rel":["red_clover"],"src":["usda-nrcs","usfs","atp3-50-21"],"ask":"Tell me about white clover"},{"id":"burdock","title":"Burdock","domain":"plants","also":["Arctium","gobo","great burdock","beggar's buttons"],"def":"Burdock is a large weed with huge heart-shaped leaves and hooked burrs that stick to clothing; its first-year root is eaten cooked.","look":["very large heart-shaped leaves, hooked burr heads, purple thistle-like flowers","leaves pale and woolly underneath"],"use":"Learn it as an identification first. Eat it only after you have matched every feature in person, ideally with someone who knows the plant, from ground that was not sprayed or beside a busy road, and start with a small amount. Young leaves can be mistaken for foxglove, which is deadly.","not":"Do not eat it on a photo match or a single feature, and do not eat it if you cannot rule out its look-alikes.","alike":["Foxglove: Fuzzy leaves in a rosette, tall spike of tubular pink-purple bells. Deadly to the heart. Often confused with comfrey in the first year"],"rel":["foxglove"],"src":["usda-nrcs","usfs","atp3-50-21"],"ask":"Tell me about burdock"},{"id":"foxglove","title":"Foxglove","domain":"plants","also":["Digitalis","fairy gloves","purple foxglove","Digitalis purpurea"],"def":"Foxglove is a garden and wild plant with a tall spike of tubular pink-purple flowers, and every part is deadly to the heart.","look":["fuzzy leaves in a rosette, tall spike of tubular pink-purple bells","spotted throat inside each bell"],"use":"Learn it so you can avoid it and warn others. Deadly to the heart. Often confused with comfrey in the first year.","not":"Never eat, brew, chew, or burn any part of it, and wash your hands after touching it. Do not trust a photo or a taste test.","alike":["Burdock: Very large heart-shaped leaves, hooked burr heads, purple thistle-like flowers. Young leaves can be mistaken for foxglove, which is deadly","Comfrey: Rough hairy leaves, bell flowers in curled clusters. Contains liver-damaging compounds. Do not eat or brew it"],"call":"If someone may have eaten it, call Poison Control at 1-800-222-1222, or 911 for trouble breathing, seizures, or collapse.","rel":["burdock","comfrey"],"src":["usda-nrcs","usfs","atp3-50-21","poison-control"],"ask":"Tell me about foxglove"},{"id":"comfrey","title":"Comfrey","domain":"plants","also":["Symphytum","knitbone","boneset","Symphytum officinale"],"def":"Comfrey is a hairy-leaved garden plant with curled clusters of bell flowers that contains liver-damaging compounds.","look":["rough hairy leaves, bell flowers in curled clusters","leaves run down onto the stem as wings"],"use":"Learn it so you can avoid it and warn others. Contains liver-damaging compounds. Do not eat or brew it.","not":"Do not eat, brew, or chew any part of it, and wash skin and tools that touched the sap.","alike":["Foxglove: Fuzzy leaves in a rosette, tall spike of tubular pink-purple bells. Deadly to the heart. Often confused with comfrey in the first year"],"call":"If someone may have eaten it, call Poison Control at 1-800-222-1222, or 911 for trouble breathing, seizures, or collapse.","rel":["foxglove"],"src":["usda-nrcs","usfs","atp3-50-21","poison-control"],"ask":"Tell me about comfrey"},{"id":"iris_flag","title":"Wild iris (blue flag, yellow flag)","domain":"plants","also":["blue flag","yellow flag","flag iris","Iris versicolor"],"def":"Wild iris, or blue flag, is a wetland plant with flat sword-shaped leaves in a fan, and it is poisonous.","look":["flat sword-shaped leaves in a fan","blue-violet or yellow flowers","wet ground","leaves flat and folded like a fan, not round like cattail"],"use":"Learn it so you can avoid it and warn others. Toxic if eaten. Often mistaken for cattail shoots.","not":"Do not eat, brew, or chew any part of it, and wash skin and tools that touched the sap.","alike":["Cattail: Tall blade leaves, brown sausage-shaped seed head; wet places. Iris leaves look alike before flowering and are toxic"],"call":"If someone may have eaten it, call Poison Control at 1-800-222-1222, or 911 for trouble breathing, seizures, or collapse.","rel":["cattail_lookalikes"],"src":["usda-nrcs","usfs","atp3-50-21","poison-control"],"ask":"Tell me about wild iris"},{"id":"wild_strawberry","title":"Wild strawberry","domain":"plants","also":["Fragaria","woodland strawberry","wild strawberries","Fragaria virginiana"],"def":"Wild strawberry is a low native plant whose tiny red berries carry their seeds on the outside and taste like small garden strawberries.","look":["three toothed leaflets, white five-petal flowers, tiny red berries with seeds on the outside","runners that root along the ground"],"use":"Learn it as an identification first. Eat it only after you have matched every feature in person, ideally with someone who knows the plant, from ground that was not sprayed or beside a busy road, and start with a small amount.","not":"Do not eat it on a photo match or a single feature, and do not eat it if you cannot rule out its look-alikes.","src":["usda-nrcs","usfs","atp3-50-21"],"ask":"Tell me about wild strawberry"},{"id":"brambles","title":"Blackberry and raspberry (Rubus)","domain":"plants","also":["blackberry","raspberry","Rubus","blackcap","dewberry"],"def":"Brambles are the prickly canes of blackberries and raspberries, whose berries are built from many small beads.","look":["arching prickly canes, toothed compound leaves, clustered berries made of tiny beads","raspberries pull off hollow like a cap; blackberries keep a white core"],"use":"Learn it as an identification first. Eat it only after you have matched every feature in person, ideally with someone who knows the plant, from ground that was not sprayed or beside a busy road, and start with a small amount.","not":"Do not eat it on a photo match or a single feature, and do not eat it if you cannot rule out its look-alikes.","src":["usda-nrcs","usfs","atp3-50-21"],"ask":"Tell me about blackberry and raspberry"},{"id":"blueberry","title":"Blueberry","domain":"plants","also":["lowbush blueberry","wild blueberry","huckleberry","Vaccinium angustifolium"],"def":"Lowbush blueberry is a small shrub of sunny barrens and woods whose blue berries end in a five-point crown.","look":["low shrub, small oval leaves, blue berries with a five-point crown at the tip","many tiny seeds inside, not one stone"],"use":"Learn it as an identification first. Eat it only after you have matched every feature in person, ideally with someone who knows the plant, from ground that was not sprayed or beside a busy road, and start with a small amount.","not":"Do not eat it on a photo match or a single feature, and do not eat it if you cannot rule out its look-alikes.","src":["usda-nrcs","usfs","atp3-50-21"],"ask":"Tell me about blueberry"},{"id":"cranberry","title":"Cranberry","domain":"plants","also":["wild cranberry","bog cranberry","Vaccinium macrocarpon"],"def":"Cranberry is a trailing evergreen vine of bogs whose sour red berries ripen in fall.","look":["trailing evergreen vine in bogs, tiny leaves, red berries","berries bounce and have air pockets inside"],"use":"Learn it as an identification first. Eat it only after you have matched every feature in person, ideally with someone who knows the plant, from ground that was not sprayed or beside a busy road, and start with a small amount.","not":"Do not eat it on a photo match or a single feature, and do not eat it if you cannot rule out its look-alikes.","src":["usda-nrcs","usfs","atp3-50-21"],"ask":"Tell me about cranberry"},{"id":"elderberry","title":"Elderberry","domain":"plants","also":["elder","Sambucus","black elderberry","elderflower","Sambucus canadensis"],"def":"Elderberry is a shrub with flat clusters of tiny white flowers and dark purple berries that are only safe to eat cooked and ripe.","look":["opposite compound leaves, flat clusters of white flowers, dark purple (or red) berries, pithy stems","stems have soft white pith inside"],"use":"Learn it as an identification first. Eat it only after you have matched every feature in person, ideally with someone who knows the plant, from ground that was not sprayed or beside a busy road, and start with a small amount. Raw berries, leaves and stems are toxic. Cook the berries.","not":"Do not eat it on a photo match or a single feature, and do not eat it if you cannot rule out its look-alikes.","alike":["Water hemlock: Wet ground; clustered tuberous roots; leaves with sharp toothed leaflets and side veins that run to the notches. One of the most toxic plants in North America. Every part is deadly","Pokeweed: Purple-red stems, large leaves, drooping clusters of dark purple berries. Berries, roots and mature leaves are toxic"],"rel":["water_hemlock","pokeweed"],"src":["usda-nrcs","usfs","atp3-50-21"],"ask":"Tell me about elderberry"},{"id":"pokeweed","title":"Pokeweed","domain":"plants","also":["poke","pokeberry","poke salad","inkberry","Phytolacca","Phytolacca americana"],"def":"Pokeweed is a tall plant with purple-red stems and drooping clusters of dark berries, and its berries, roots, and mature leaves are poisonous.","look":["purple-red stems, large leaves, drooping clusters of dark purple berries","can grow taller than a person in one season"],"use":"Learn it so you can avoid it and warn others. Berries, roots and mature leaves are toxic.","not":"Do not eat, brew, or chew any part of it, and wash skin and tools that touched the sap.","alike":["Elderberry: Opposite compound leaves, flat clusters of white flowers, dark purple (or red) berries, pithy stems. Raw berries, leaves and stems are toxic. Cook the berries"],"call":"If someone may have eaten it, call Poison Control at 1-800-222-1222, or 911 for trouble breathing, seizures, or collapse.","rel":["elderberry"],"src":["usda-nrcs","usfs","atp3-50-21","poison-control"],"ask":"Tell me about pokeweed"},{"id":"staghorn_sumac","title":"Staghorn sumac","domain":"plants","also":["red sumac","sumac berries","sumac lemonade","Rhus typhina"],"def":"Staghorn sumac is a shrub with velvety twigs and upright cones of red fuzzy berries; it is not poison sumac.","look":["fuzzy velvet twigs, long compound leaves, upright red fuzzy berry cones","berries are red and point up, never white and drooping"],"use":"Learn it as an identification first. Eat it only after you have matched every feature in person, ideally with someone who knows the plant, from ground that was not sprayed or beside a busy road, and start with a small amount. Poison sumac has white drooping berries and grows in wet ground.","not":"Do not eat it on a photo match or a single feature, and do not eat it if you cannot rule out its look-alikes.","alike":["Poison sumac: Wet ground, smooth stems, leaves with a red stalk, drooping white-grey berries. Skin contact causes a severe rash"],"rel":["poison_sumac"],"src":["usda-nrcs","usfs","atp3-50-21"],"ask":"Tell me about staghorn sumac"},{"id":"virginia_creeper","title":"Virginia creeper","domain":"plants","also":["five-leaved ivy","woodbine","Parthenocissus","Parthenocissus quinquefolia"],"def":"Virginia creeper is a climbing vine with five leaflets spread like a hand, often confused with poison ivy, and its berries are poisonous.","look":["five leaflets spread like a hand","climbing vine with tendrils","tendrils end in small sticky pads","dark blue berries on red stalks in fall"],"use":"Learn it so you can avoid it and warn others. Berries are toxic. Sometimes mistaken for poison ivy.","not":"Do not eat, brew, or chew any part of it, and wash skin and tools that touched the sap.","alike":["Poison ivy: Three leaflets, the middle one on a longer stalk; hairy vine on trees; leaves red in autumn. Leaves of three. Skin contact causes a rash. Smoke from burning it is dangerous"],"call":"If someone may have eaten it, call Poison Control at 1-800-222-1222, or 911 for trouble breathing, seizures, or collapse.","rel":["poison_ivy_id"],"src":["usda-nrcs","usfs","atp3-50-21","poison-control"],"ask":"Tell me about virginia creeper"},{"id":"stinging_nettle","title":"Stinging nettle","domain":"plants","also":["nettle","nettles","Urtica","Urtica dioica"],"def":"Stinging nettle is a plant covered in fine stinging hairs that burn the skin on contact; cooking or drying removes the sting.","look":["opposite toothed leaves with stinging hairs, square stem, small green flower strings","a burning, tingling rash right after you brush it"],"use":"Learn it as an identification first. Eat it only after you have matched every feature in person, ideally with someone who knows the plant, from ground that was not sprayed or beside a busy road, and start with a small amount. Stings on touch. Cooking removes the sting.","not":"Do not eat it on a photo match or a single feature, and do not eat it if you cannot rule out its look-alikes.","src":["usda-nrcs","usfs","atp3-50-21"],"ask":"Tell me about stinging nettle"},{"id":"lambsquarters","title":"Lambsquarters","domain":"plants","also":["goosefoot","pigweed","wild spinach","Chenopodium","Chenopodium album"],"def":"Lambsquarters is a common garden weed whose diamond-shaped leaves have a white mealy coating underneath.","look":["diamond-shaped leaves with a white mealy powder underneath","water beads on the leaves"],"use":"Learn it as an identification first. Eat it only after you have matched every feature in person, ideally with someone who knows the plant, from ground that was not sprayed or beside a busy road, and start with a small amount.","not":"Do not eat it on a photo match or a single feature, and do not eat it if you cannot rule out its look-alikes.","src":["usda-nrcs","usfs","atp3-50-21"],"ask":"Tell me about lambsquarters"},{"id":"wood_sorrel","title":"Wood sorrel","domain":"plants","also":["sour grass","Oxalis","yellow wood sorrel","sheep sorrel","Oxalis stricta"],"def":"Wood sorrel is a small plant with heart-shaped leaflets in threes and a sour, lemony taste from oxalic acid.","look":["heart-shaped leaflets in threes like a clover, small yellow or pink five-petal flowers","sour taste","leaflets fold down at night"],"use":"Learn it as an identification first. Eat it only after you have matched every feature in person, ideally with someone who knows the plant, from ground that was not sprayed or beside a busy road, and start with a small amount. Eat only small amounts.","not":"Do not eat it on a photo match or a single feature, and do not eat it if you cannot rule out its look-alikes.","alike":["White clover: Low creeping plant, white round flower heads, three leaflets often with a pale band"],"rel":["white_clover"],"src":["usda-nrcs","usfs","atp3-50-21"],"ask":"Tell me about wood sorrel"},{"id":"jewelweed","title":"Jewelweed","domain":"plants","also":["spotted touch-me-not","touch-me-not","Impatiens capensis"],"def":"Jewelweed is a soft wet-ground plant with orange spotted trumpet flowers and seed pods that burst when touched.","look":["orange or yellow spotted trumpet flowers, pale watery stems, leaves bead up water","seed pods burst when touched","grows near water and often near poison ivy"],"use":"Older manuals and folk use mention it, but Yehsa does not give doses or treatments with wild plants. Use it as an identification lesson, and use tested first-aid supplies for care.","not":"Do not swallow, brew, or put it on a wound on a photo match; identify it in person first, and ask a clinician before using any plant as medicine.","src":["usda-nrcs","usfs","atp3-50-21"],"ask":"Tell me about jewelweed"},{"id":"bracken","title":"Bracken fern","domain":"plants","also":["bracken fern","brake fern","Pteridium","Pteridium aquilinum"],"def":"Bracken is a large common fern with triangular fronds; it is toxic and not a safe fiddlehead.","look":["large triangular fronds on a single stalk, fuzzy coiled shoots, open ground","young shoots are fuzzy, not smooth and grooved"],"use":"Learn it so you can avoid it and warn others. Toxic and linked to cancer. Do not eat.","not":"Do not eat, brew, or chew any part of it, and wash skin and tools that touched the sap.","alike":["Ostrich fern (fiddleheads): Tightly coiled fiddlehead with a smooth U-shaped groove on the inside of the stem, papery brown scales. Fiddleheads must be cooked. Bracken is not safe to eat"],"call":"If someone may have eaten it, call Poison Control at 1-800-222-1222, or 911 for trouble breathing, seizures, or collapse.","rel":["fiddleheads_ostrich_fern"],"src":["usda-nrcs","usfs","atp3-50-21","poison-control"],"ask":"Tell me about bracken fern"},{"id":"common_milkweed","title":"Common milkweed","domain":"plants","also":["milkweed","Asclepias syriaca","monarch plant"],"def":"Common milkweed is a tall plant with milky sap, broad paired leaves, and warty pods, and it is toxic raw.","look":["thick stem with milky white sap, big opposite oval leaves, pink ball flower clusters, warty pods","pods full of silky seeds in fall"],"use":"Learn it so you can avoid it and warn others. Toxic raw. Only a trained forager should use it, and not by photo.","not":"Do not eat, brew, or chew any part of it, and wash skin and tools that touched the sap.","alike":["Dogbane: Red-tinged stems with milky sap, pointed opposite leaves, tiny white bells, slim paired pods. Toxic to the heart. Looks like milkweed"],"call":"If someone may have eaten it, call Poison Control at 1-800-222-1222, or 911 for trouble breathing, seizures, or collapse.","rel":["dogbane"],"src":["usda-nrcs","usfs","atp3-50-21","poison-control"],"ask":"Tell me about common milkweed"},{"id":"dogbane","title":"Dogbane","domain":"plants","also":["Indian hemp","hemp dogbane","Apocynum","Apocynum cannabinum"],"def":"Dogbane is a milky-sapped plant with red-tinged stems and slim paired pods that is poisonous to the heart and looks like milkweed.","look":["red-tinged stems with milky sap, pointed opposite leaves, tiny white bells, slim paired pods","branches near the top, unlike young milkweed","smooth leaves without milkweed's fine hair"],"use":"Learn it so you can avoid it and warn others. Toxic to the heart. Looks like milkweed.","not":"Do not eat, brew, or chew any part of it, and wash skin and tools that touched the sap.","alike":["Common milkweed: Thick stem with milky white sap, big opposite oval leaves, pink ball flower clusters, warty pods. Toxic raw. Only a trained forager should use it, and not by photo"],"call":"If someone may have eaten it, call Poison Control at 1-800-222-1222, or 911 for trouble breathing, seizures, or collapse.","rel":["common_milkweed"],"src":["usda-nrcs","usfs","atp3-50-21","poison-control"],"ask":"Tell me about dogbane"},{"id":"mullein","title":"Mullein","domain":"plants","also":["common mullein","flannel leaf","cowboy toilet paper","Verbascum","Verbascum thapsus"],"def":"Mullein is a tall roadside plant with large, soft, gray, fuzzy leaves and a yellow flower spike in its second year.","look":["large grey fuzzy leaves in a rosette and a tall yellow flower spike in the second year","dry stalks stand through winter"],"use":"Older manuals and folk use mention it, but Yehsa does not give doses or treatments with wild plants. Use it as an identification lesson, and use tested first-aid supplies for care.","not":"Do not swallow, brew, or put it on a wound on a photo match; identify it in person first, and ask a clinician before using any plant as medicine.","src":["usda-nrcs","usfs","atp3-50-21"],"ask":"Tell me about mullein"},{"id":"st_johns_wort","title":"St. John's wort","domain":"plants","also":["Hypericum","St Johns wort","goatweed","Hypericum perforatum"],"def":"St. John's wort is a yellow-flowered plant whose leaves show tiny see-through dots when held to the light.","look":["opposite small leaves with see-through dots when held to light","yellow five-petal flowers that stain purple","flowers bleed a red stain when crushed"],"use":"Older manuals and folk use mention it, but Yehsa does not give doses or treatments with wild plants. Use it as an identification lesson, and use tested first-aid supplies for care. Interacts with many medicines and causes sun sensitivity.","not":"Do not swallow, brew, or put it on a wound on a photo match; identify it in person first, and ask a clinician before using any plant as medicine.","src":["usda-nrcs","usfs","atp3-50-21"],"ask":"Tell me about st. john's wort"},{"id":"self_heal","title":"Self-heal","domain":"plants","also":["heal-all","Prunella","selfheal","Prunella vulgaris"],"def":"Self-heal is a low lawn and trail plant with a square stem and a spiky purple flower head.","look":["low plant, square stem, spiky purple flower head with ruffled lips","opposite leaves on a square stem"],"use":"Older manuals and folk use mention it, but Yehsa does not give doses or treatments with wild plants. Use it as an identification lesson, and use tested first-aid supplies for care.","not":"Do not swallow, brew, or put it on a wound on a photo match; identify it in person first, and ask a clinician before using any plant as medicine.","src":["usda-nrcs","usfs","atp3-50-21"],"ask":"Tell me about self-heal"},{"id":"goldenrod","title":"Goldenrod","domain":"plants","also":["Solidago","goldenrods"],"def":"Goldenrod is a tall late-summer plant with plumes of small yellow flowers; it is often blamed for hay fever caused by ragweed.","look":["tall plume of tiny yellow flowers in late summer, alternate narrow leaves","stands in old fields and roadsides by the thousands"],"use":"Older manuals and folk use mention it, but Yehsa does not give doses or treatments with wild plants. Use it as an identification lesson, and use tested first-aid supplies for care.","not":"Do not swallow, brew, or put it on a wound on a photo match; identify it in person first, and ask a clinician before using any plant as medicine.","src":["usda-nrcs","usfs","atp3-50-21"],"ask":"Tell me about goldenrod"},{"id":"white_snakeroot","title":"White snakeroot","domain":"plants","also":["snakeroot","Ageratina","milk sickness plant","Ageratina altissima"],"def":"White snakeroot is a woodland plant with fuzzy white fall flowers that poisons livestock and can pass into their milk.","look":["opposite toothed leaves on a branching stem, fuzzy white flower clusters in autumn","grows in shade at woods edges"],"use":"Learn it so you can avoid it and warn others. Poisons livestock and milk. Do not eat.","not":"Do not eat, brew, or chew any part of it, and wash skin and tools that touched the sap.","call":"If someone may have eaten it, call Poison Control at 1-800-222-1222, or 911 for trouble breathing, seizures, or collapse.","src":["usda-nrcs","usfs","atp3-50-21","poison-control"],"ask":"Tell me about white snakeroot"},{"id":"jerusalem_artichoke","title":"Jerusalem artichoke","domain":"plants","also":["sunchoke","sunroot","Helianthus tuberosus"],"def":"Jerusalem artichoke is a tall wild sunflower whose knobby underground tubers are edible.","look":["tall rough sunflower-like plant with small yellow flowers and knobby tubers","leaves rough like sandpaper"],"use":"Learn it as an identification first. Eat it only after you have matched every feature in person, ideally with someone who knows the plant, from ground that was not sprayed or beside a busy road, and start with a small amount.","not":"Do not eat it on a photo match or a single feature, and do not eat it if you cannot rule out its look-alikes.","src":["usda-nrcs","usfs","atp3-50-21"],"ask":"Tell me about jerusalem artichoke"},{"id":"evening_primrose","title":"Evening primrose","domain":"plants","also":["Oenothera","common evening primrose","Oenothera biennis"],"def":"Evening primrose is a tall plant with four-petal yellow flowers that open at dusk.","look":["tall plant with four-petal yellow flowers that open at dusk, reddish stem","first-year rosette with a pink-tinged midrib"],"use":"Learn it as an identification first. Eat it only after you have matched every feature in person, ideally with someone who knows the plant, from ground that was not sprayed or beside a busy road, and start with a small amount.","not":"Do not eat it on a photo match or a single feature, and do not eat it if you cannot rule out its look-alikes.","src":["usda-nrcs","usfs","atp3-50-21"],"ask":"Tell me about evening primrose"},{"id":"pineapple_weed","title":"Pineapple weed","domain":"plants","also":["wild chamomile","disc mayweed","Matricaria discoidea"],"def":"Pineapple weed is a low weed of packed paths whose petal-less yellow-green flower cones smell like pineapple when crushed.","look":["low plant with feathery leaves, yellow-green cone flowers with no petals","smells like pineapple when crushed","grows in hard, trampled ground"],"use":"Learn it as an identification first. Eat it only after you have matched every feature in person, ideally with someone who knows the plant, from ground that was not sprayed or beside a busy road, and start with a small amount.","not":"Do not eat it on a photo match or a single feature, and do not eat it if you cannot rule out its look-alikes.","src":["usda-nrcs","usfs","atp3-50-21"],"ask":"Tell me about pineapple weed"},{"id":"wild_bergamot","title":"Wild bergamot","domain":"plants","also":["bee balm","Monarda","horsemint","Monarda fistulosa"],"def":"Wild bergamot is a mint-family wildflower with lavender shaggy flower heads and an oregano-like smell.","look":["square stem, lavender shaggy flower heads, minty oregano smell","square stem and paired leaves like other mints"],"use":"Older manuals and folk use mention it, but Yehsa does not give doses or treatments with wild plants. Use it as an identification lesson, and use tested first-aid supplies for care.","not":"Do not swallow, brew, or put it on a wound on a photo match; identify it in person first, and ask a clinician before using any plant as medicine.","src":["usda-nrcs","usfs","atp3-50-21"],"ask":"Tell me about wild bergamot"},{"id":"mayapple","title":"Mayapple","domain":"plants","also":["American mandrake","Podophyllum","umbrella plant","Podophyllum peltatum"],"def":"Mayapple is a spring woodland plant with umbrella-like leaves, and every part except the fully ripe fruit is poisonous.","look":["umbrella-like lobed leaves, a single white flower under the leaves, one green-yellow fruit","grows in large colonies on the forest floor"],"use":"Learn it so you can avoid it and warn others. Everything except the ripe fruit is toxic.","not":"Do not eat, brew, or chew any part of it, and wash skin and tools that touched the sap.","call":"If someone may have eaten it, call Poison Control at 1-800-222-1222, or 911 for trouble breathing, seizures, or collapse.","src":["usda-nrcs","usfs","atp3-50-21","poison-control"],"ask":"Tell me about mayapple"},{"id":"bloodroot","title":"Bloodroot","domain":"plants","also":["Sanguinaria","red puccoon","Sanguinaria canadensis"],"def":"Bloodroot is an early-spring wildflower with one lobed leaf and a white flower whose root bleeds red-orange sap, and it is poisonous.","look":["one clasped rounded lobed leaf and a white eight-petal flower in early spring","red-orange sap","leaf wraps the flower stalk as it opens"],"use":"Learn it so you can avoid it and warn others. Toxic.","not":"Do not eat, brew, or chew any part of it, and wash skin and tools that touched the sap.","call":"If someone may have eaten it, call Poison Control at 1-800-222-1222, or 911 for trouble breathing, seizures, or collapse.","src":["usda-nrcs","usfs","atp3-50-21","poison-control"],"ask":"Tell me about bloodroot"},{"id":"baneberry","title":"Baneberry","domain":"plants","also":["doll's eyes","white baneberry","red baneberry","Actaea","Actaea pachypoda"],"def":"Baneberry, or doll's eyes, is a woodland plant whose white or red berries on thick red stalks are deadly.","look":["compound toothed leaves, a white or red berry cluster on thick red stalks (doll's eyes)","each white berry has a black dot like an eye"],"use":"Learn it so you can avoid it and warn others. Berries are deadly.","not":"Never eat, brew, chew, or burn any part of it, and wash your hands after touching it. Do not trust a photo or a taste test.","call":"If someone may have eaten it, call Poison Control at 1-800-222-1222, or 911 for trouble breathing, seizures, or collapse.","src":["usda-nrcs","usfs","atp3-50-21","poison-control"],"ask":"Tell me about baneberry"},{"id":"jimsonweed","title":"Jimsonweed","domain":"plants","also":["Datura","thorn apple","devil's trumpet","locoweed","Datura stramonium"],"def":"Jimsonweed is a rank-smelling weed with large white trumpet flowers and spiny seed pods, and every part is deadly.","look":["large white trumpet flowers, spiny egg-shaped seed pods, strong smell","grows in disturbed ground and barnyards"],"use":"Learn it so you can avoid it and warn others. Every part is deadly.","not":"Never eat, brew, chew, or burn any part of it, and wash your hands after touching it. Do not trust a photo or a taste test.","call":"If someone may have eaten it, call Poison Control at 1-800-222-1222, or 911 for trouble breathing, seizures, or collapse.","src":["usda-nrcs","usfs","atp3-50-21","poison-control"],"ask":"Tell me about jimsonweed"},{"id":"bittersweet_nightshade","title":"Bittersweet nightshade","domain":"plants","also":["climbing nightshade","woody nightshade","Solanum dulcamara"],"def":"Bittersweet nightshade is a climbing vine with small purple star flowers and red egg-shaped berries that are poisonous.","look":["climbing vine, purple flowers with a yellow cone, red egg-shaped berries","green berries turn orange, then red"],"use":"Learn it so you can avoid it and warn others. Berries are toxic.","not":"Do not eat, brew, or chew any part of it, and wash skin and tools that touched the sap.","call":"If someone may have eaten it, call Poison Control at 1-800-222-1222, or 911 for trouble breathing, seizures, or collapse.","src":["usda-nrcs","usfs","atp3-50-21","poison-control"],"ask":"Tell me about bittersweet nightshade"},{"id":"monkshood","title":"Monkshood","domain":"plants","also":["Aconitum","wolfsbane","aconite"],"def":"Monkshood is a garden and wild plant with hooded blue-purple flowers, and every part is deadly, even through the skin.","look":["deeply cut leaves and tall spikes of hooded blue-purple flowers","top petal shaped like a monk's hood"],"use":"Learn it so you can avoid it and warn others. Deadly. Even skin contact can numb or harm.","not":"Never eat, brew, chew, or burn any part of it, and wash your hands after touching it. Do not trust a photo or a taste test.","call":"If someone may have eaten it, call Poison Control at 1-800-222-1222, or 911 for trouble breathing, seizures, or collapse.","src":["usda-nrcs","usfs","atp3-50-21","poison-control"],"ask":"Tell me about monkshood"},{"id":"giant_hogweed","title":"Giant hogweed","domain":"plants","also":["hogweed","Heracleum mantegazzianum"],"def":"Giant hogweed is a huge carrot-family plant whose sap, with sunlight, causes severe burns and blisters on skin.","look":["huge: stem 5-10 cm wide with purple blotches and stiff hairs, umbrella flower head up to 1 m","can be taller than a person, with a flower umbrella over a meter across"],"use":"Learn it so you can avoid it and warn others. Sap plus sunlight causes severe burns. Do not touch.","not":"Do not eat, brew, or chew any part of it, and wash skin and tools that touched the sap.","alike":["Cow parsnip: Big maple-like leaves, white flat umbrella, hairy hollow stem. Sap can cause burns on sunny skin","Poison hemlock: Smooth hairless stem with purple blotches, finely cut leaves, white umbrella flowers. Smells musty. Every part is deadly"],"call":"If someone may have eaten it, call Poison Control at 1-800-222-1222, or 911 for trouble breathing, seizures, or collapse.","rel":["cow_parsnip","poison_hemlock"],"src":["usda-nrcs","usfs","atp3-50-21","poison-control"],"ask":"Tell me about giant hogweed"},{"id":"cow_parsnip","title":"Cow parsnip","domain":"plants","also":["Heracleum maximum","Indian celery"],"def":"Cow parsnip is a large native carrot-family plant with maple-like leaves whose sap can burn sunlit skin.","look":["big maple-like leaves, white flat umbrella, hairy hollow stem","smaller than giant hogweed, with a greener, less blotched stem"],"use":"Learn it so you can avoid it and warn others. Sap can cause burns on sunny skin.","not":"Do not eat, brew, or chew any part of it, and wash skin and tools that touched the sap.","alike":["Giant hogweed: Huge: stem 5-10 cm wide with purple blotches and stiff hairs, umbrella flower head up to 1 m. Sap plus sunlight causes severe burns. Do not touch","Poison hemlock: Smooth hairless stem with purple blotches, finely cut leaves, white umbrella flowers. Smells musty. Every part is deadly"],"call":"If someone may have eaten it, call Poison Control at 1-800-222-1222, or 911 for trouble breathing, seizures, or collapse.","rel":["giant_hogweed","poison_hemlock"],"src":["usda-nrcs","usfs","atp3-50-21","poison-control"],"ask":"Tell me about cow parsnip"},{"id":"wild_parsnip","title":"Wild parsnip","domain":"plants","also":["Pastinaca","poison parsnip","Pastinaca sativa"],"def":"Wild parsnip is a yellow-flowered carrot-family roadside plant whose sap, with sunlight, causes burns and blisters.","look":["yellow umbrella flowers, grooved hollow stem, toothed leaflets","flat yellow umbrella flowers in midsummer"],"use":"Learn it so you can avoid it and warn others. Sap plus sunlight causes burns and blisters.","not":"Do not eat, brew, or chew any part of it, and wash skin and tools that touched the sap.","alike":["Poison hemlock: Smooth hairless stem with purple blotches, finely cut leaves, white umbrella flowers. Smells musty. Every part is deadly"],"call":"If someone may have eaten it, call Poison Control at 1-800-222-1222, or 911 for trouble breathing, seizures, or collapse.","rel":["poison_hemlock"],"src":["usda-nrcs","usfs","atp3-50-21","poison-control"],"ask":"Tell me about wild parsnip"},{"id":"skunk_cabbage","title":"Skunk cabbage","domain":"plants","also":["Symplocarpus","swamp cabbage","eastern skunk cabbage","Symplocarpus foetidus"],"def":"Skunk cabbage is a wetland plant with a mottled hooded flower in late winter and big leaves that smell skunky when torn; it is toxic raw.","look":["wet ground","mottled purple-maroon hooded flower in late winter","big cabbage-like leaves with a skunky smell","one of the first plants up in wet woods, even through snow"],"use":"Learn it so you can avoid it and warn others. Toxic raw.","not":"Do not eat, brew, or chew any part of it, and wash skin and tools that touched the sap.","alike":["False hellebore (Indian poke): Big pleated leaves that wrap the stem in a spiral; wet woods and meadows. No onion smell. Sometimes mistaken for ramps. Deadly"],"call":"If someone may have eaten it, call Poison Control at 1-800-222-1222, or 911 for trouble breathing, seizures, or collapse.","rel":["false_hellebore"],"src":["usda-nrcs","usfs","atp3-50-21","poison-control"],"ask":"Tell me about skunk cabbage"},{"id":"japanese_knotweed","title":"Japanese knotweed","domain":"plants","also":["knotweed","Fallopia japonica","Mexican bamboo","Reynoutria","Reynoutria japonica"],"def":"Japanese knotweed is an invasive plant with hollow, bamboo-like jointed canes that forms dense stands.","look":["hollow bamboo-like reddish canes, heart-shaped leaves, dense stands","zigzag stems with a leaf at each joint"],"use":"Learn it as an identification first. Eat it only after you have matched every feature in person, ideally with someone who knows the plant, from ground that was not sprayed or beside a busy road, and start with a small amount. Invasive. Do not spread it.","not":"Do not eat it on a photo match or a single feature, and do not eat it if you cannot rule out its look-alikes.","src":["usda-nrcs","usfs","atp3-50-21"],"ask":"Tell me about japanese knotweed"},{"id":"curly_dock","title":"Curly dock","domain":"plants","also":["yellow dock","sour dock","Rumex crispus","dock"],"def":"Curly dock is a common weed with long, wavy-edged leaves and a tall rust-red seed stalk.","look":["long leaves with wavy ruffled edges, tall rust-red seed stalk","papery sheath where each leaf meets the stem"],"use":"Learn it as an identification first. Eat it only after you have matched every feature in person, ideally with someone who knows the plant, from ground that was not sprayed or beside a busy road, and start with a small amount.","not":"Do not eat it on a photo match or a single feature, and do not eat it if you cannot rule out its look-alikes.","src":["usda-nrcs","usfs","atp3-50-21"],"ask":"Tell me about curly dock"},{"id":"wintergreen","title":"Wintergreen","domain":"plants","also":["teaberry","checkerberry","Gaultheria","Gaultheria procumbens"],"def":"Wintergreen is a low evergreen ground plant whose glossy leaves smell of wintergreen when crushed and whose berries are red.","look":["low evergreen with glossy leaves that smell of wintergreen when crushed","red berries","grows under pines and oaks in acid soil"],"use":"Learn it as an identification first. Eat it only after you have matched every feature in person, ideally with someone who knows the plant, from ground that was not sprayed or beside a busy road, and start with a small amount.","not":"Do not eat it on a photo match or a single feature, and do not eat it if you cannot rule out its look-alikes.","src":["usda-nrcs","usfs","atp3-50-21"],"ask":"Tell me about wintergreen"},{"id":"wild_rose","title":"Wild rose","domain":"plants","also":["rose hips","pasture rose","Rosa","multiflora rose","Rosa carolina"],"def":"Wild rose is a prickly shrub with five-petal pink flowers that leave red rose hips in fall.","look":["prickly canes, five-petal pink flowers, red rose hips","hips stay on the canes into winter"],"use":"Learn it as an identification first. Eat it only after you have matched every feature in person, ideally with someone who knows the plant, from ground that was not sprayed or beside a busy road, and start with a small amount. Hips have irritating hairs inside. Remove them.","not":"Do not eat it on a photo match or a single feature, and do not eat it if you cannot rule out its look-alikes.","src":["usda-nrcs","usfs","atp3-50-21"],"ask":"Tell me about wild rose"},{"id":"hawthorn","title":"Hawthorn","domain":"plants","also":["Crataegus","thornapple","haws","whitethorn"],"def":"Hawthorn is a thorny small tree with lobed leaves and small red apple-like fruits called haws.","look":["thorny small tree or shrub with lobed leaves and red apple-like haws","long straight thorns on the twigs"],"use":"Learn it as an identification first. Eat it only after you have matched every feature in person, ideally with someone who knows the plant, from ground that was not sprayed or beside a busy road, and start with a small amount.","not":"Do not eat it on a photo match or a single feature, and do not eat it if you cannot rule out its look-alikes.","src":["usda-nrcs","usfs","atp3-50-21"],"ask":"Tell me about hawthorn"},{"id":"mountain_laurel","title":"Mountain laurel","domain":"plants","also":["Kalmia","calico bush","spoonwood","Kalmia latifolia"],"def":"Mountain laurel is an evergreen shrub with clusters of pink-white cup flowers, and its leaves, flowers, and honey are poisonous.","look":["evergreen glossy leaves, clusters of pink-white cup flowers","forms dense thickets on rocky slopes"],"use":"Learn it so you can avoid it and warn others. Leaves, flowers and honey from it are toxic.","not":"Do not eat, brew, or chew any part of it, and wash skin and tools that touched the sap.","call":"If someone may have eaten it, call Poison Control at 1-800-222-1222, or 911 for trouble breathing, seizures, or collapse.","src":["usda-nrcs","usfs","atp3-50-21","poison-control"],"ask":"Tell me about mountain laurel"},{"id":"sphagnum","title":"Sphagnum moss","domain":"plants","also":["peat moss","bog moss","sphagnum moss","Sphagnum"],"def":"Sphagnum is the spongy bog moss that holds many times its weight in water.","look":["pale green to red spongy moss in bogs that holds a lot of water","grows in bogs in green, red, or brown carpets"],"use":"Older manuals and folk use mention it, but Yehsa does not give doses or treatments with wild plants. Use it as an identification lesson, and use tested first-aid supplies for care. Wild moss can carry germs. Do not put it on an open wound.","not":"Do not swallow, brew, or put it on a wound on a photo match; identify it in person first, and ask a clinician before using any plant as medicine.","src":["usda-nrcs","usfs","atp3-50-21"],"ask":"Tell me about sphagnum moss"},{"id":"usnea","title":"Old man's beard (Usnea)","domain":"plants","also":["old man's beard","beard lichen","Usnea lichen","Usnea"],"def":"Usnea, or old man's beard, is a pale green hair-like lichen on branches whose strands have a white elastic core.","look":["pale green hair-like lichen on branches","pull it and the core is a white elastic thread","dry strands make fine tinder"],"use":"Older manuals and folk use mention it, but Yehsa does not give doses or treatments with wild plants. Use it as an identification lesson, and use tested first-aid supplies for care.","not":"Do not swallow, brew, or put it on a wound on a photo match; identify it in person first, and ask a clinician before using any plant as medicine.","src":["usda-nrcs","usfs","atp3-50-21"],"ask":"Tell me about old man's beard"},{"id":"cleavers","title":"Cleavers","domain":"plants","also":["bedstraw","stickyweed","goosegrass","Galium","Galium aparine"],"def":"Cleavers is a sprawling plant whose square stems and narrow whorled leaves stick to clothing with tiny hooks.","look":["sprawling square stem with whorls of narrow leaves that cling by tiny hooks","sticks to your sleeve when you brush it"],"use":"Learn it as an identification first. Eat it only after you have matched every feature in person, ideally with someone who knows the plant, from ground that was not sprayed or beside a busy road, and start with a small amount.","not":"Do not eat it on a photo match or a single feature, and do not eat it if you cannot rule out its look-alikes.","src":["usda-nrcs","usfs","atp3-50-21"],"ask":"Tell me about cleavers"},{"id":"moonseed","title":"Canada moonseed","domain":"plants","also":["moonseed vine","Menispermum","yellow parilla","Menispermum canadense"],"def":"Canada moonseed is a climbing vine with grape-like berries that are deadly; each berry holds one crescent-shaped seed.","look":["climbing vine with big lobed leaves, dark blue-black berries each with a single crescent seed","no tendrils, unlike grape"],"use":"Learn it so you can avoid it and warn others. Looks like wild grape. Grapes have several seeds and tendrils. Moonseed has neither.","not":"Never eat, brew, chew, or burn any part of it, and wash your hands after touching it. Do not trust a photo or a taste test.","alike":["Wild grape: Climbing vine with tendrils, toothed lobed leaves, round berries in a bunch"],"call":"If someone may have eaten it, call Poison Control at 1-800-222-1222, or 911 for trouble breathing, seizures, or collapse.","rel":["wild_grape"],"src":["usda-nrcs","usfs","atp3-50-21","poison-control"],"ask":"Tell me about canada moonseed"},{"id":"wild_grape","title":"Wild grape","domain":"plants","also":["riverbank grape","fox grape","Vitis","Vitis riparia"],"def":"Wild grape is a climbing vine with tendrils, toothed lobed leaves, and bunches of small dark grapes.","look":["climbing vine with tendrils, toothed lobed leaves, round berries in a bunch","shreddy bark on older vines","several pear-shaped seeds per grape"],"use":"Learn it as an identification first. Eat it only after you have matched every feature in person, ideally with someone who knows the plant, from ground that was not sprayed or beside a busy road, and start with a small amount.","not":"Do not eat it on a photo match or a single feature, and do not eat it if you cannot rule out its look-alikes.","alike":["Canada moonseed: Climbing vine with big lobed leaves, dark blue-black berries each with a single crescent seed. Looks like wild grape. Grapes have several seeds and tendrils. Moonseed has neither"],"rel":["moonseed"],"src":["usda-nrcs","usfs","atp3-50-21"],"ask":"Tell me about wild grape"},{"id":"thistle","title":"Thistle","domain":"plants","also":["bull thistle","Cirsium","spear thistle","Cirsium vulgare"],"def":"Thistle is a spiny plant with round purple flower heads whose peeled young stems and roots are edible.","look":["spiny leaves and stem, round purple flower heads","fluffy seed heads in late summer"],"use":"Learn it as an identification first. Eat it only after you have matched every feature in person, ideally with someone who knows the plant, from ground that was not sprayed or beside a busy road, and start with a small amount.","not":"Do not eat it on a photo match or a single feature, and do not eat it if you cannot rule out its look-alikes.","src":["usda-nrcs","usfs","atp3-50-21"],"ask":"Tell me about thistle"},{"id":"spurge","title":"Spotted spurge (Euphorbia)","domain":"plants","also":["Euphorbia","spotted spurge","prostrate spurge","Euphorbia maculata"],"def":"Spotted spurge is a flat mat-forming weed whose milky sap irritates skin and which is toxic if eaten.","look":["flat mat of small oval leaves with a dark spot, milky sap","thin wiry stems, not fat and succulent"],"use":"Learn it so you can avoid it and warn others. Sap irritates. Mistaken for purslane.","not":"Do not eat, brew, or chew any part of it, and wash skin and tools that touched the sap.","alike":["Purslane: Flat mat of thick succulent paddle leaves with reddish stems; clear sap. Spurge has milky sap. Check the sap"],"call":"If someone may have eaten it, call Poison Control at 1-800-222-1222, or 911 for trouble breathing, seizures, or collapse.","rel":["purslane"],"src":["usda-nrcs","usfs","atp3-50-21","poison-control"],"ask":"Tell me about spotted spurge"},{"id":"purslane","title":"Purslane","domain":"plants","also":["Portulaca","pigweed","verdolaga","little hogweed","Portulaca oleracea"],"def":"Purslane is a low succulent weed with thick paddle-shaped leaves and reddish stems, a common edible green.","look":["flat mat of thick succulent paddle leaves with reddish stems","clear sap","clear watery sap, never milky"],"use":"Learn it as an identification first. Eat it only after you have matched every feature in person, ideally with someone who knows the plant, from ground that was not sprayed or beside a busy road, and start with a small amount. Spurge has milky sap. Check the sap.","not":"Do not eat it on a photo match or a single feature, and do not eat it if you cannot rule out its look-alikes.","alike":["Spotted spurge (Euphorbia): Flat mat of small oval leaves with a dark spot, milky sap. Sap irritates. Mistaken for purslane"],"rel":["spurge"],"src":["usda-nrcs","usfs","atp3-50-21"],"ask":"Tell me about purslane"},{"id":"chickweed","title":"Chickweed","domain":"plants","also":["Stellaria media","common chickweed","starweed"],"def":"Chickweed is a small, soft, sprawling weed with tiny white star flowers and a single line of hairs along the stem.","look":["low plant with small oval leaves and one line of hairs along the stem","tiny white deep-notched petals","stretchy inner thread when a stem is pulled apart"],"use":"Learn it as an identification first. Eat it only after you have matched every feature in person, ideally with someone who knows the plant, from ground that was not sprayed or beside a busy road, and start with a small amount.","not":"Do not eat it on a photo match or a single feature, and do not eat it if you cannot rule out its look-alikes.","src":["usda-nrcs","usfs","atp3-50-21"],"ask":"Tell me about chickweed"},{"id":"common_mallow","title":"Common mallow","domain":"plants","also":["cheeseweed","Malva","buttonweed","Malva neglecta"],"def":"Common mallow is a low weed with round lobed leaves and small pale pink flowers that leave cheese-wheel shaped seeds.","look":["round lobed leaves on long stalks, small pale pink flowers, round cheese-wheel fruits","slimy texture when the leaves are chewed or crushed"],"use":"Learn it as an identification first. Eat it only after you have matched every feature in person, ideally with someone who knows the plant, from ground that was not sprayed or beside a busy road, and start with a small amount.","not":"Do not eat it on a photo match or a single feature, and do not eat it if you cannot rule out its look-alikes.","src":["usda-nrcs","usfs","atp3-50-21"],"ask":"Tell me about common mallow"},{"id":"garlic_mustard","title":"Garlic mustard","domain":"plants","also":["Alliaria","hedge garlic","jack-by-the-hedge","Alliaria petiolata"],"def":"Garlic mustard is an invasive woodland plant whose heart-shaped leaves smell of garlic when crushed.","look":["heart-shaped toothed leaves smelling of garlic, small white four-petal flowers","first-year rosettes stay green through winter"],"use":"Learn it as an identification first. Eat it only after you have matched every feature in person, ideally with someone who knows the plant, from ground that was not sprayed or beside a busy road, and start with a small amount. Invasive. Do not spread it.","not":"Do not eat it on a photo match or a single feature, and do not eat it if you cannot rule out its look-alikes.","src":["usda-nrcs","usfs","atp3-50-21"],"ask":"Tell me about garlic mustard"},{"id":"shelter_site_hazards","title":"Where not to camp or build a shelter","domain":"shelter","also":["widowmaker","dead tree over camp","flood channel","rockfall","bad campsite"],"def":"Choose a shelter site away from hazards overhead and underfoot: dead branches, rockfall, flood channels, game trails, and low cold pockets.","look":["dead limbs or leaning trees overhead (widowmakers)","dry washes, gullies, and stream banks that can flood","loose rock above, ant nests, or a game trail through the spot"],"use":"Look up before you look down. Pick a flat, well-drained spot on a bench or low slope, near building materials and water but 200 feet (60 m) from it, out of the wind. Put the latrine downhill and downstream.","not":"Do not camp under dead trees or in a drainage, and do not camp right on the shore of a stream or lake.","call":"If a storm is coming, move away from tall lone trees and low channels.","rel":[],"src":["atp3-50-21","nps"]},{"id":"debris_hut_build","title":"Debris hut (how to build)","domain":"shelter","also":["leaf hut","insulated stick hut","hut made of leaves and sticks","debris shelter"],"def":"A debris hut is a small, wedge-shaped shelter of a ridgepole, ribs, and a thick layer of dry leaves or other debris, built to trap body heat.","look":["a long ridgepole on a stump, rock, or tripod","ribs steep enough to shed water","at least about 3 feet (1 m) of dry debris outside and 2 feet (60 cm) of bedding inside"],"use":"Build it when you need a warm shelter and have time and a lot of dry debris. Make it just big enough for your body, and close the entrance with a pile of debris or your pack.","not":"Do not build it in a drain or under dead trees. Do not burn a stove, charcoal, or a candle in a closed hut.","steps":["Prop a long ridgepole on a stump or a tripod.","Lean ribs along both sides of the pole, close together.","Cover the ribs with a lattice of small sticks so insulation does not fall in.","Pile 3 feet of dry leaves, grass, or ferns on top and cover with branches against wind.","Stuff the inside with bedding, crawl in feet first, and close the entrance."],"call":"Leave a way for air to move; fuel-burning devices make carbon monoxide.","rel":["lean_to_build"],"src":["atp3-50-21"]},{"id":"lean_to_build","title":"Lean-to with a fire reflector","domain":"shelter","also":["lean to shelter","three-sided shelter","lean-to fire reflector","a-frame lean-to"],"def":"A lean-to is a sloped roof with an open side, built against a crossbar between two trees or posts, often with a fire reflector wall opposite it.","look":["a crossbar between two supports at about chest height","a roof sloping toward the wind with the open side away from it","a fire reflector wall of logs or rocks a few feet in front"],"use":"Use it when you need a quick shelter in calm to moderate weather. Place the back to the wind, shingle the roof from the bottom up, and add a thick bed. Keep the fire a few steps out and low.","not":"Do not put a fire too close to the roof, and do not use a lean-to in strong winds from the open side.","call":"Check for dead limbs overhead and keep the fire small.","rel":["debris_hut_build"],"src":["atp3-50-21"]},{"id":"tarp_shelter_rig","title":"Rigging a tarp or poncho shelter","domain":"shelter","also":["tarp A-frame","poncho tent","how to set up a tarp","tarp lean-to"],"def":"A tarp shelter is a sheet of waterproof fabric pitched over a ridgeline and staked down; it is the fastest shelter to set up.","look":["a taut ridgeline between two trees at waist height","tarp draped over it with edges staked low","one end lowered into the wind"],"use":"Tie a ridgeline between two trees, drape the tarp over it, and stake the corners. Pitch the low end into the wind and keep the high end open for air. Put a ground sheet under you.","not":"Do not pitch it flat where water pools, or too high where wind can get under.","rel":[],"src":["atp3-50-21","ready"]},{"id":"ground_first_insulation","title":"Ground insulation: why the ground comes first","domain":"shelter","also":["bed of boughs","sleeping pad","insulate from the ground","warm bed"],"def":"The ground pulls heat out of you faster than the air does, so insulation under you matters before the roof.","look":["a 6 to 8 inch (15 to 20 cm) pressed layer of dry boughs, leaves, or grass","a pad or pack under your torso and hips","no direct contact with cold ground or snow"],"use":"Build the bed first, then the shelter. Pile dry leaves, pine boughs (cut ends down), or grass, add a pad or pack, and refresh each night.","not":"Do not lie on bare ground, rock, or snow.","rel":["debris_hut_build"],"src":["atp3-50-21"]},{"id":"shelter_door","title":"What I can use for a shelter door","domain":"shelter","also":["close the entrance","block the opening","door for a debris hut"],"def":"A shelter door is anything that closes the entrance against wind and cold, such as a pack, a debris pile, or a tarp.","look":["a gap just big enough to crawl in","a door that can be closed from the inside","air flow through a small gap"],"use":"Use your pack, a bundle of branches stuffed with leaves, a spare tarp, or a slab of snow. Close it from the inside after you crawl in, and leave a small gap for air.","not":"Do not seal a shelter airtight when burning a candle or stove.","rel":["debris_hut_build","carbon_monoxide_poisoning"],"src":["atp3-50-21"]},{"id":"wind_vs_insulation","title":"Stopping wind versus staying insulated","domain":"shelter","also":["windbreak","what keeps me warm","wind vs cold shelter"],"def":"A windbreak stops moving air from stealing heat, while insulation traps still air around you; a good shelter does both.","look":["windbreak: a wall, tarp, or log between you and the wind","insulation: dry layers, boughs, and a bed","moisture: wet insulation does not insulate"],"use":"Block the wind first, then add insulation under and around you. Keep it dry and make the space small to hold heat.","not":"Do not think a roof alone will keep you warm; the ground and wind steal the most heat.","rel":["ground_first_insulation","clothing_layers"],"src":["atp3-50-21"]},{"id":"clothing_layers","title":"Clothing as shelter: layering","domain":"shelter","also":["what to wear","dress in layers","wool or cotton","wet clothes","how to layer"],"def":"Layering uses a wicking base, a warm insulating middle, and a windproof, waterproof outer layer that you adjust to stay dry and warm.","look":["wool or synthetic base layers, not cotton","an insulating mid-layer like fleece or down","a shell for wind and rain, plus hat, gloves, and dry socks"],"use":"Vent before you sweat, add layers when you stop, and swap wet layers for dry ones as soon as you can. Keep a spare dry layer in a waterproof bag.","not":"Do not wear cotton in cold or wet weather; it holds water and chills you.","rel":["hypothermia_mild_weather"],"src":["atp3-50-21","cdc"]},{"id":"fuel_in_closed_shelter","title":"No fuel burning in a closed shelter","domain":"shelter","also":["stove in a tent","charcoal in a shelter","candle in a snow cave","carbon monoxide in a shelter"],"def":"Burning charcoal, a stove, a lantern, or even a candle in a closed shelter can fill it with carbon monoxide, which has no smell and can kill in your sleep.","look":["a closed tent, snow cave, car, or hut","headache and drowsiness","a flame that burns low or yellow from lack of air"],"use":"Cook and heat outside or in a well-ventilated vestibule, and leave a vent open at all times. Use a battery lantern inside. Carry a battery CO alarm in a tent when you can.","not":"Do not burn charcoal, a camp stove, or a heater in a tent, snow cave, or vehicle.","call":"Get out into fresh air and call 911 for headache, dizziness, or confusion in a closed space.","rel":["carbon_monoxide_poisoning"],"src":["cdc","cpsc","atp3-50-21"]},{"id":"stuck_in_car_snow","title":"Stuck in a car in a snowstorm","domain":"shelter","also":["stranded in snow","stay with the car","car in a snowbank","exhaust pipe blocked"],"def":"If stranded in a car in a snowstorm, staying with the vehicle is usually safest; keep the tailpipe clear and run the engine only a little.","look":["blowing or falling snow with low visibility","the exhaust pipe at risk of blocking","engine running in an enclosed space"],"use":"Call 911, tie a bright cloth to the antenna, and stay in the car. Run the engine about 10 minutes each hour with the tailpipe clear of snow and a window cracked. Keep moving your arms and legs and keep warm layers on.","not":"Do not leave the car in a whiteout unless help is clearly in sight, and do not let the tailpipe get blocked.","call":"Call 911; carbon monoxide can build up in a car with a blocked tailpipe.","rel":["carbon_monoxide_poisoning"],"src":["nws","fema","cdc"]},{"id":"snow_shelter_ventilation","title":"Snow shelters: tree-pit and ventilation","domain":"shelter","also":["tree well shelter","snow trench","snow cave vent","packed snow hut"],"def":"A snow shelter uses snow's insulating quality, and it needs a vent hole and a roof about a foot thick to be safe.","look":["a tree well with low branches overhead","a trench or cave with a roof at least 12 inches (30 cm) thick","a fist-sized vent hole in the roof"],"use":"Dig a pit under an evergreen, roof it with branches and snow, line the floor with boughs, and cut a vent. Keep a tool inside and keep the entrance lower than the sleeping area.","not":"Do not sweat while digging, and do not burn fuel inside. Keep the vent open.","call":"Check the vent often; snow can block it.","rel":["fuel_in_closed_shelter"],"src":["atp3-50-21"]},{"id":"space_blanket_bivy","title":"Space blanket and bivy: what they will and won't do","domain":"shelter","also":["emergency blanket","mylar blanket","bivy sack","survival blanket"],"def":"A space blanket is a thin reflective sheet that holds in some body heat; a bivy is a waterproof shell for a sleeping bag.","look":["a very light sheet that reflects heat back","a bivy keeps wind and rain off a bag","condensation builds inside if there is no vent"],"use":"Wrap a space blanket around you under clothes or in a shelter, with a pad or dry layers under you. Use it as a roof or wind block too. Add insulation; it does not warm by itself.","not":"Do not rely on it alone in cold or wet weather, and do not seal yourself in without a vent.","rel":["ground_first_insulation","hypothermia_stages"],"src":["atp3-50-21","cdc"]},{"id":"tent_storm_pitch","title":"Tent site and storm pitching","domain":"shelter","also":["set up a tent in the wind","tent in a storm","stake out a tent"],"def":"For a storm pitch, set the tent low and tight with the narrow end into the wind, and guy out every line.","look":["a flat, drained site away from dead trees","the door facing away from the wind","taut guy lines and deep stakes or rocks"],"use":"Choose a protected spot, stake every corner and guy line, and stow the pack inside. Put rocks or logs on the stakes in soft ground. Avoid ridges and open meadows.","not":"Do not camp under tall dead trees or in a dry wash during a storm.","rel":["shelter_site_hazards","tarp_shelter_rig"],"src":["nps","atp3-50-21"]},{"id":"fire_near_shelter","title":"Fire placement near a shelter","domain":"shelter","also":["how close should a fire be","fire next to tent","sparks on a tent"],"def":"Place a fire off the opening of a shelter and far enough that sparks cannot reach the roof or bedding.","look":["a fire 6 to 10 feet (2 to 3 m) from a tarp or tent","a reflector wall behind the fire","no overhanging branches"],"use":"Keep the fire small and downwind of the shelter, away from the door and dry fabric. Use a ring of rocks or a pit. Put it out before you sleep.","not":"Do not build a fire inside a tent or under the roof of a tarp.","rel":["lean_to_build","fire_site_choice"],"src":["atp3-50-21","nps"]},{"id":"shelter_for_conditions","title":"Shelter for rain, wind, snow, and bugs","domain":"shelter","also":["bug shelter","rain shelter","mosquito shelter"],"def":"Different weather needs a different shelter: a steep tarp for rain, a low wedge for wind, a snow shelter for deep snow, and netting for insects.","look":["rain: steep pitch and a drip line","wind: low and streamlined, back to the wind","snow: dug into the snowpack with a vent","insects: a fine mesh net or smoke"],"use":"Pick the shelter that fits what the weather is doing, and use netting or a head net when insects are bad.","not":"Do not rely on smoke to keep bugs away in a closed shelter.","rel":["tarp_shelter_rig","snow_shelter_ventilation"],"src":["atp3-50-21","cdc"]},{"id":"group_vs_solo_shelter","title":"Group versus solo shelter","domain":"shelter","also":["share body heat","sleeping together","shelter for two"],"def":"A group shelter shares body heat and takes less material per person; a solo shelter must be smaller and better insulated.","look":["two people sharing a bag or insulation hold heat better","a smaller space is warmer","shared watch duties"],"use":"Share a larger shelter where possible, huddle with insulation under all, and take turns keeping the vent and fire.","not":"Do not crowd so tightly that air cannot move.","rel":["debris_hut_build","wind_vs_insulation"],"src":["atp3-50-21"]},{"id":"insulation_how_much","title":"How much insulation is enough?","domain":"shelter","also":["thickness of debris","how thick should the leaves be"],"def":"In plain terms, thicker is warmer: about 3 feet of dry debris on a hut and 6 to 8 inches under you, with a small vent.","look":["3 feet (1 m) of debris on a hut","6 to 8 inches (15 to 20 cm) under you","dry, fluffy material, not wet or packed"],"use":"Add more until you can no longer feel the cold coming through, and keep it dry. Leave a vent.","not":"Do not use wet leaves or packed snow alone as a bed.","rel":["debris_hut_build","ground_first_insulation"],"src":["atp3-50-21"]},{"id":"bear_scat","title":"Bear scat","domain":"sign","also":["bear droppings","bear poop","bear dung","black bear scat","bear sign"],"def":"Black bear scat is a large tubular or piled dropping, often full of berries, seeds, nut shells, grass, or hair, that means a bear has been in the area.","look":["thick tubes about 1.5 to 2 inches (4 to 5 cm) wide, or loose piles","packed with berries, seeds, or grass in summer and fall"],"use":"Fresh, moist scat means a bear was there recently. Make noise, keep food sealed and away from camp, and consider moving on.","not":"Do not touch or sniff scat with bare hands; use a stick, and wash your hands after. Do not camp next to a latrine or fresh bear sign.","alike":["Coyote scat: thinner, twisted, full of hair and bone with tapered ends","Moose summer scat: loose cow-pie clumps of plant fiber"],"rel":["bear_track"],"src":["nps","usfs"],"ask":"Tell me about bear scat"},{"id":"coyote_scat","title":"Coyote or fox scat","domain":"sign","also":["coyote droppings","fox scat","fox poop","coyote poop","canine scat"],"def":"Coyote and fox scat is a twisted, rope-like dropping full of hair and small bones, with a tapered end, often left in the middle of a trail.","look":["coyote scat about 3/4 to 1 inch (2 to 2.5 cm) wide; fox scat thinner","packed with fur, bone, berries, or seeds"],"use":"Scat on a trail or at a junction is a territory marker. It tells you which predators use the area.","not":"Do not touch or sniff scat with bare hands; use a stick, and wash your hands after. Do not camp next to a latrine or fresh bear sign. Canine scat can carry tapeworm eggs.","alike":["Domestic dog: usually smooth, uniform, kibble-based, without hair","Bobcat scat: segmented, blunt ends, often partly buried"],"rel":["canine_track"],"src":["nps","cdc"],"ask":"Tell me about coyote or fox scat"},{"id":"moose_scat","title":"Moose scat","domain":"sign","also":["moose droppings","moose poop","moose nuggets","moose pellets"],"def":"Moose scat is a pile of large oval pellets of compressed wood fiber in winter, or soft clumps like a cow pie in summer.","look":["pellets about 1 to 1 1/2 inches (2.5 to 4 cm) long, much bigger than deer","sawdust-like texture when broken"],"use":"Fresh piles mean moose are using the area; give any moose plenty of room.","not":"Do not touch or sniff scat with bare hands; use a stick, and wash your hands after. Do not camp next to a latrine or fresh bear sign.","alike":["Deer scat: same shape, about half the size"],"rel":["moose_track","deer_scat"],"src":["nps","usfs"],"ask":"Tell me about moose scat"},{"id":"raccoon_scat","title":"Raccoon scat","domain":"sign","also":["raccoon droppings","raccoon poop","raccoon latrine","coon scat"],"def":"Raccoon scat is a blunt-ended, tubular dropping often full of seeds and shell bits, left in piles called latrines on logs, rocks, roofs, or at tree bases.","look":["dark tubes about 3/4 inch (2 cm) wide with blunt ends","many droppings of different ages in one spot"],"use":"A latrine means raccoons use the site regularly. Keep food and trash locked away.","not":"Raccoon latrines can carry roundworm eggs that seriously harm people. Do not touch, sweep, or kick them; keep children and pets away. Clean up only with gloves and a mask and follow CDC guidance.","alike":["Coyote scat: twisted with hair and bone, single on trails","Skunk scat: similar but smaller and more often full of insect parts"],"rel":["raccoon_track"],"src":["cdc","nps"],"ask":"Tell me about raccoon scat"},{"id":"rabbit_scat","title":"Rabbit or hare scat","domain":"sign","also":["rabbit droppings","rabbit poop","rabbit pellets","hare droppings","bunny poop"],"def":"Rabbit and hare scat is a scatter of round, slightly flattened, pea-sized pellets of chewed plant fiber.","look":["round, about 1/4 to 1/2 inch (0.6 to 1.3 cm) across, flattened like a thick coin","light brown and fibrous inside"],"use":"Lots of pellets near brush and browsed twigs mean rabbits or hares feed and hide there.","not":"Do not touch or sniff scat with bare hands; use a stick, and wash your hands after. Do not camp next to a latrine or fresh bear sign. Wear gloves when handling rabbits or hares, because of tularemia.","alike":["Deer scat: oval or acorn-shaped with a point, larger and darker","Woodchuck or squirrel: smaller, more oblong"],"rel":["rabbit_track"],"src":["nps","cdc"],"ask":"Tell me about rabbit or hare scat"},{"id":"bear_track","title":"Bear tracks","domain":"sign","also":["bear track","bear prints","bear paw print","black bear track","bear sign"],"def":"A black bear track is a wide print with five toes in an arc and a broad pad, the hind print looking like a flat-footed human foot.","look":["front print about 4 to 6 inches (10 to 15 cm) wide with claw dots","hind print longer, up to about 7 inches (18 cm), with a heel"],"use":"Fresh tracks mean a bear is close. Make noise, keep food sealed, and keep dogs leashed.","not":"Do not follow fresh bear tracks, especially to a carcass or with cubs nearby.","alike":["Human barefoot print: big toe on the inside and an arch","Raccoon: much smaller, long fingers"],"rel":["bear_scat","black_bear"],"src":["nps","usfs"],"ask":"Tell me about bear tracks"},{"id":"canine_track","title":"Coyote, fox, or dog tracks","domain":"sign","also":["coyote track","fox track","dog track","canine prints","wolf track"],"def":"A canine track has four toes with claw marks around a triangular pad, and an X shape can be drawn through the space between toes and pad.","look":["oval print; coyote about 2 1/2 inches (6 cm) long, fox smaller","wild canines walk in a straight, direct line; dogs wander"],"use":"A straight, purposeful line of oval prints is usually a coyote or fox; a zigzagging line beside a person's tracks is usually a dog.","not":"Track size alone does not separate a big fox from a small coyote or dog.","alike":["Bobcat: round print, no claw marks, three-lobed pad","Raccoon: five long fingers"],"rel":["coyote_scat","coyote"],"src":["nps","usfs"],"ask":"Tell me about coyote, fox, or dog tracks"},{"id":"raccoon_track","title":"Raccoon tracks","domain":"sign","also":["raccoon track","raccoon prints","coon track"],"def":"A raccoon track has five long, finger-like toes, like a small human handprint, usually in mud near water.","look":["front print about 2 to 3 inches (5 to 8 cm) with separated fingers","hind print longer, like a small foot"],"use":"Raccoon tracks near camp mean you should lock up food at night.","not":"Do not handle a raccoon that is active by day and acting oddly; it may have rabies.","alike":["Opossum: hind foot has a thumb pointing sideways","Skunk: shorter toes, five in an arc"],"rel":["raccoon_scat","raccoon"],"src":["nps","cdc"],"ask":"Tell me about raccoon tracks"},{"id":"moose_track","title":"Moose tracks","domain":"sign","also":["moose track","moose prints","moose hoof print"],"def":"A moose track is a large split-hoof print over 4 inches (10 cm) long, shaped like a deer track but much bigger.","look":["blunt or pointed heart shape, about 4 to 6 inches (10 to 15 cm) long","deep in mud or snow, with dewclaws often showing"],"use":"Fresh tracks mean moose are near; give them room, especially in fall and in calving season.","not":"Do not follow fresh moose tracks into thick cover.","alike":["Deer track: same shape but under about 3 1/2 inches (9 cm)","Cattle: rounder, wider toes"],"rel":["moose_scat","moose","deer_track"],"src":["nps","usfs"],"ask":"Tell me about moose tracks"},{"id":"turkey_track","title":"Turkey tracks","domain":"sign","also":["turkey track","turkey prints","bird tracks"],"def":"A wild turkey track is a large bird print with three long forward toes and a short back toe, about 4 to 5 inches (10 to 13 cm) long.","look":["middle toe longest and straight ahead","long stride of many prints in a line"],"use":"Fresh tracks near fields, roosts, or dusting spots mean turkeys use the area.","not":"Tracks do not tell a tom from a hen reliably; large tracks over about 4 1/2 inches are more often toms.","alike":["Great blue heron: longer back toe and slimmer toes","Grouse: smaller, about 2 inches (5 cm)"],"rel":["wild_turkey"],"src":["usfs","fws"],"ask":"Tell me about turkey tracks"},{"id":"bobcat_track","title":"Bobcat tracks","domain":"sign","also":["bobcat track","cat track","lynx track","bobcat prints"],"def":"A bobcat track is a round print about 2 inches (5 cm) across with four toes, no claw marks, and a three-lobed pad.","look":["round, not oval like a canine","leading edge of the pad has two notches making three lobes"],"use":"A round print with no claws is a cat; bobcats often walk with hind feet placed in the front prints.","not":"Do not track a bobcat closely to a den.","alike":["Canine: oval with claw marks and a triangular pad","House cat: smaller, about 1 1/2 inches (4 cm)"],"rel":["bobcat"],"src":["nps","usfs"],"ask":"Tell me about bobcat tracks"},{"id":"rabbit_track","title":"Rabbit or hare tracks","domain":"sign","also":["rabbit track","hare track","bunny prints","snowshoe hare track"],"def":"Rabbit and hare tracks come in groups of four: two long hind feet side by side in front of two small front feet, one behind the other.","look":["Y-shaped or triangle-shaped track group","snowshoe hare hind prints very large and splayed in snow"],"use":"The big hind prints land ahead of the front prints, so the wide end of the group points the way the animal went.","not":"Do not mistake the order: the large prints are in front because the hind feet swing past.","alike":["Squirrel: front prints side by side too, with clear toes and claws"],"rel":["rabbit_scat","snowshoe_hare"],"src":["nps","usfs"],"ask":"Tell me about rabbit or hare tracks"},{"id":"common_juniper","title":"Common juniper","domain":"trees","also":["juniper","Juniperus communis","juniper berries"],"def":"Common juniper is a low, spreading evergreen shrub with sharp needles in threes and blue berry-like cones.","look":["low spreading evergreen shrub with sharp needles in threes and blue berry-like cones","needles have a white stripe on top"],"use":"Knowing the tree helps you pick firewood, shelter sites, and landmarks. Do not mix it up with yew, which is deadly.","not":"Do not eat or brew any part of a tree you have not identified in person; some trees, like yew and wilted cherry leaves, are deadly.","src":["usfs","usda-nrcs"],"ask":"Tell me about common juniper"},{"id":"yew","title":"Yew (Canada yew)","domain":"trees","also":["Canada yew","ground hemlock","Taxus","yew berries","Taxus canadensis"],"def":"Canada yew is a low evergreen shrub with flat needles and red fleshy berries whose seeds, needles, and bark are deadly.","look":["flat dark green needles with two pale lines underneath, red fleshy cup berries","low shrub","red cup-shaped berry with a dark seed showing"],"use":"Knowing the tree helps you pick firewood, shelter sites, and landmarks. Needles, seeds and bark are deadly.","not":"Never eat or brew any part of it; it is deadly, and children are drawn to the red berries.","alike":["Balsam fir: Flat blunt needles with two white lines underneath, upright cones, smooth bark with resin blisters, spicy smell","Eastern hemlock (the tree): Flat short needles with two white lines underneath on tiny stalks, tiny cones, drooping top. The tree is not the poison hemlock plants. Poison and water hemlock are herbs with umbrella flowers"],"call":"If someone may have eaten it, call Poison Control at 1-800-222-1222, or 911 for trouble breathing, seizures, or collapse.","rel":["balsam_fir","eastern_hemlock"],"src":["usfs","usda-nrcs","poison-control"],"ask":"Tell me about yew"},{"id":"balsam_fir","title":"Balsam fir","domain":"trees","also":["fir","Abies balsamea","Christmas tree fir","balsam"],"def":"Balsam fir is a northern evergreen with flat, blunt, fragrant needles and resin blisters on smooth bark.","look":["flat blunt needles with two white lines underneath, upright cones, smooth bark with resin blisters, spicy smell","cones sit upright on top branches"],"use":"Resin blisters burn well as fire starter, and boughs make soft bedding.","not":"Do not eat or brew any part of a tree you have not identified in person; some trees, like yew and wilted cherry leaves, are deadly.","alike":["Red spruce: Square four-sided stiff needles that roll between your fingers, hanging cones, reddish scaly bark","Eastern hemlock (the tree): Flat short needles with two white lines underneath on tiny stalks, tiny cones, drooping top. The tree is not the poison hemlock plants. Poison and water hemlock are herbs with umbrella flowers","Yew (Canada yew): Flat dark green needles with two pale lines underneath, red fleshy cup berries; low shrub. Needles, seeds and bark are deadly"],"rel":["red_spruce","eastern_hemlock","yew"],"src":["usfs","usda-nrcs"],"ask":"Tell me about balsam fir"},{"id":"red_spruce","title":"Red spruce","domain":"trees","also":["spruce","Picea rubens","eastern spruce"],"def":"Red spruce is a northern evergreen with stiff, square needles that roll between the fingers and small hanging cones.","look":["square four-sided stiff needles that roll between your fingers, hanging cones, reddish scaly bark","sharp needles on small woody pegs"],"use":"Spruce boughs make shelter roofing and bedding; resin helps start fires.","not":"Do not eat or brew any part of a tree you have not identified in person; some trees, like yew and wilted cherry leaves, are deadly.","alike":["Balsam fir: Flat blunt needles with two white lines underneath, upright cones, smooth bark with resin blisters, spicy smell","White spruce: Four-sided blue-green needles, slim hanging cones; needles smell strongly when crushed"],"rel":["balsam_fir","white_spruce"],"src":["usfs","usda-nrcs"],"ask":"Tell me about red spruce"},{"id":"white_spruce","title":"White spruce","domain":"trees","also":["Picea glauca","cat spruce","skunk spruce"],"def":"White spruce is a northern evergreen with blue-green four-sided needles that smell strong when crushed.","look":["four-sided blue-green needles, slim hanging cones","needles smell strongly when crushed","slender cones that fall whole"],"use":"Spruce boughs make shelter roofing and bedding; spruce roots make cordage.","not":"Do not eat or brew any part of a tree you have not identified in person; some trees, like yew and wilted cherry leaves, are deadly.","alike":["Red spruce: Square four-sided stiff needles that roll between your fingers, hanging cones, reddish scaly bark"],"rel":["red_spruce"],"src":["usfs","usda-nrcs"],"ask":"Tell me about white spruce"},{"id":"black_spruce","title":"Black spruce","domain":"trees","also":["bog spruce","Picea mariana"],"def":"Black spruce is a slim bog spruce with short needles and small round cones that stay on the tree for years.","look":["bog tree with a thin top, short needles, small round cones that stay on the tree","club-like dense top"],"use":"Its presence usually means wet, boggy ground, so plan a route around it.","not":"Do not eat or brew any part of a tree you have not identified in person; some trees, like yew and wilted cherry leaves, are deadly.","alike":["Red spruce: Square four-sided stiff needles that roll between your fingers, hanging cones, reddish scaly bark"],"rel":["red_spruce"],"src":["usfs","usda-nrcs"],"ask":"Tell me about black spruce"},{"id":"white_pine","title":"Eastern white pine","domain":"trees","also":["white pine","Pinus strobus","eastern pine"],"def":"Eastern white pine is a tall evergreen with soft needles in bundles of five and long slim cones.","look":["soft needles in bundles of five, long slim cones, tiered branches","one needle bundle has five needles, like the letters in white"],"use":"Pitch from wounds is a fire starter, and inner bark is a famine food.","not":"Do not eat or brew any part of a tree you have not identified in person; some trees, like yew and wilted cherry leaves, are deadly.","alike":["Red pine: Long needles in bundles of two that snap cleanly, orange-red flaky bark"],"rel":["red_pine"],"src":["usfs","usda-nrcs"],"ask":"Tell me about eastern white pine"},{"id":"red_pine","title":"Red pine","domain":"trees","also":["Norway pine","Pinus resinosa"],"def":"Red pine is an evergreen with long needles in pairs that snap cleanly when bent and orange-red flaky bark.","look":["long needles in bundles of two that snap cleanly, orange-red flaky bark","often in straight planted rows"],"use":"Dead lower limbs are dry fuel, and fatwood makes strong tinder.","not":"Do not eat or brew any part of a tree you have not identified in person; some trees, like yew and wilted cherry leaves, are deadly.","alike":["Eastern white pine: Soft needles in bundles of five, long slim cones, tiered branches"],"rel":["white_pine"],"src":["usfs","usda-nrcs"],"ask":"Tell me about red pine"},{"id":"eastern_hemlock","title":"Eastern hemlock (the tree)","domain":"trees","also":["hemlock tree","Tsuga canadensis","Canada hemlock"],"def":"Eastern hemlock is a shade-loving evergreen tree with short flat needles; it is not the poisonous hemlock plants.","look":["flat short needles with two white lines underneath on tiny stalks, tiny cones, drooping top","tiny cones at the branch tips","drooping top leader"],"use":"Dense hemlock gives good shelter from wind and snow. The tree is not the poison hemlock plants. Poison and water hemlock are herbs with umbrella flowers.","not":"Do not eat or brew any part of a tree you have not identified in person; some trees, like yew and wilted cherry leaves, are deadly.","alike":["Balsam fir: Flat blunt needles with two white lines underneath, upright cones, smooth bark with resin blisters, spicy smell","Yew (Canada yew): Flat dark green needles with two pale lines underneath, red fleshy cup berries; low shrub. Needles, seeds and bark are deadly","Water hemlock: Wet ground; clustered tuberous roots; leaves with sharp toothed leaflets and side veins that run to the notches. One of the most toxic plants in North America. Every part is deadly"],"rel":["balsam_fir","yew","water_hemlock"],"src":["usfs","usda-nrcs"],"ask":"Tell me about eastern hemlock"},{"id":"eastern_red_cedar","title":"Eastern red cedar","domain":"trees","also":["red cedar","Juniperus virginiana","aromatic cedar"],"def":"Eastern red cedar is a juniper tree with scaly leaves, blue berry-like cones, and fragrant reddish wood.","look":["scaly green leaves or sharp awls, blue berry-like cones, shredding reddish bark","narrow cone shape in old fields"],"use":"Shredded bark makes good tinder.","not":"Do not eat or brew any part of a tree you have not identified in person; some trees, like yew and wilted cherry leaves, are deadly.","alike":["Northern white cedar: Flat fans of scale-like leaves, small cones, stringy bark; wet ground"],"rel":["northern_white_cedar"],"src":["usfs","usda-nrcs"],"ask":"Tell me about eastern red cedar"},{"id":"northern_white_cedar","title":"Northern white cedar","domain":"trees","also":["arborvitae","Thuja","swamp cedar","Thuja occidentalis"],"def":"Northern white cedar is an evergreen with flat fans of scale-like leaves and stringy bark, common in wet ground.","look":["flat fans of scale-like leaves, small cones, stringy bark","wet ground","small upright cones"],"use":"Its inner bark makes cordage and tinder.","not":"Do not eat or brew any part of a tree you have not identified in person; some trees, like yew and wilted cherry leaves, are deadly.","alike":["Eastern red cedar: Scaly green leaves or sharp awls, blue berry-like cones, shredding reddish bark"],"rel":["eastern_red_cedar"],"src":["usfs","usda-nrcs"],"ask":"Tell me about northern white cedar"},{"id":"tamarack","title":"Tamarack (larch)","domain":"trees","also":["larch","eastern larch","Larix laricina","hackmatack"],"def":"Tamarack is a larch, a conifer whose soft tufted needles turn gold and drop each fall.","look":["soft needles in tufts that turn gold and drop in autumn","bare in winter, unlike other conifers"],"use":"It marks wet, boggy ground.","not":"Do not eat or brew any part of a tree you have not identified in person; some trees, like yew and wilted cherry leaves, are deadly.","src":["usfs","usda-nrcs"],"ask":"Tell me about tamarack"},{"id":"sugar_maple","title":"Sugar maple","domain":"trees","also":["hard maple","rock maple","Acer saccharum"],"def":"Sugar maple is a hardwood with five-lobed leaves and rounded gaps, tapped in late winter for maple syrup.","look":["five-lobed leaf with smooth rounded gaps, opposite branches, grey furrowed bark","winged seeds in pairs"],"use":"It is excellent firewood and the classic syrup tree.","not":"Do not eat or brew any part of a tree you have not identified in person; some trees, like yew and wilted cherry leaves, are deadly.","alike":["Red maple: Three- to five-lobed leaf with toothed edges and sharp gaps, red twigs and buds"],"rel":["red_maple"],"src":["usfs","usda-nrcs"],"ask":"Tell me about sugar maple"},{"id":"red_maple","title":"Red maple","domain":"trees","also":["swamp maple","soft maple","Acer rubrum"],"def":"Red maple is a common hardwood with three- to five-lobed toothed leaves and red twigs, buds, and fall color.","look":["three- to five-lobed leaf with toothed edges and sharp gaps, red twigs and buds","red flowers before the leaves in spring"],"use":"Its sap can be boiled for syrup too, with a lower sugar content.","not":"Do not eat or brew any part of a tree you have not identified in person; some trees, like yew and wilted cherry leaves, are deadly.","alike":["Sugar maple: Five-lobed leaf with smooth rounded gaps, opposite branches, grey furrowed bark"],"rel":["sugar_maple"],"src":["usfs","usda-nrcs"],"ask":"Tell me about red maple"},{"id":"paper_birch","title":"Paper birch","domain":"trees","also":["white birch","canoe birch","Betula papyrifera"],"def":"Paper birch is a hardwood with white bark that peels in papery sheets and burns even when damp.","look":["white bark peeling in papery sheets with dark marks","toothed oval leaves","dark horizontal lines on the bark"],"use":"Peel bark only from dead or downed trees; it is one of the best natural tinders.","not":"Do not eat or brew any part of a tree you have not identified in person; some trees, like yew and wilted cherry leaves, are deadly.","alike":["Yellow birch: Silver-yellow bark that peels in curly strips; twigs smell of wintergreen when scratched"],"rel":["yellow_birch"],"src":["usfs","usda-nrcs"],"ask":"Tell me about paper birch"},{"id":"yellow_birch","title":"Yellow birch","domain":"trees","also":["Betula alleghaniensis","gold birch"],"def":"Yellow birch is a hardwood with silver-yellow bark peeling in curly strips and twigs that smell of wintergreen.","look":["silver-yellow bark that peels in curly strips","twigs smell of wintergreen when scratched","often grows on old stumps with roots like stilts"],"use":"Curly bark shreds catch a spark and burn wet.","not":"Do not eat or brew any part of a tree you have not identified in person; some trees, like yew and wilted cherry leaves, are deadly.","alike":["Paper birch: White bark peeling in papery sheets with dark marks; toothed oval leaves"],"rel":["paper_birch"],"src":["usfs","usda-nrcs"],"ask":"Tell me about yellow birch"},{"id":"american_beech","title":"American beech","domain":"trees","also":["beech","Fagus grandifolia","beechnut tree"],"def":"American beech is a hardwood with smooth gray bark and pale papery leaves that cling through winter.","look":["smooth blue-grey bark, toothed oval leaves with straight veins, pale leaves that stay in winter","long pointed cigar-shaped buds"],"use":"Its small triangular beechnuts are edible in fall.","not":"Do not eat or brew any part of a tree you have not identified in person; some trees, like yew and wilted cherry leaves, are deadly.","src":["usfs","usda-nrcs"],"ask":"Tell me about american beech"},{"id":"white_oak","title":"White oak","domain":"trees","also":["Quercus alba","white oaks"],"def":"White oak is a hardwood with rounded leaf lobes and pale, scaly bark.","look":["rounded leaf lobes, pale scaly bark","acorns mature in one year and are less bitter"],"use":"Acorns need leaching before eating.","not":"Do not eat or brew any part of a tree you have not identified in person; some trees, like yew and wilted cherry leaves, are deadly.","alike":["Red oak: Pointed leaf lobes with bristle tips, ridged bark with pale stripes"],"rel":["red_oak"],"src":["usfs","usda-nrcs"],"ask":"Tell me about white oak"},{"id":"red_oak","title":"Red oak","domain":"trees","also":["northern red oak","Quercus rubra"],"def":"Northern red oak is a hardwood with pointed, bristle-tipped leaf lobes and ridged bark with shiny stripes.","look":["pointed leaf lobes with bristle tips, ridged bark with pale stripes","acorns take two years to ripen and are bitter"],"use":"Acorns need long leaching before eating.","not":"Do not eat or brew any part of a tree you have not identified in person; some trees, like yew and wilted cherry leaves, are deadly.","alike":["White oak: Rounded leaf lobes, pale scaly bark"],"rel":["white_oak"],"src":["usfs","usda-nrcs"],"ask":"Tell me about red oak"},{"id":"american_elm","title":"American elm","domain":"trees","also":["elm","Ulmus americana","white elm"],"def":"American elm is a hardwood with lopsided, double-toothed leaves and a vase-shaped crown.","look":["leaves with uneven bases and double teeth, vase shape","many killed by Dutch elm disease"],"use":"Inner bark makes cordage.","not":"Do not eat or brew any part of a tree you have not identified in person; some trees, like yew and wilted cherry leaves, are deadly.","src":["usfs","usda-nrcs"],"ask":"Tell me about american elm"},{"id":"white_ash","title":"White ash","domain":"trees","also":["ash","Fraxinus americana","American ash"],"def":"White ash is a hardwood with opposite compound leaves and bark ridged in a diamond pattern.","look":["opposite compound leaves, diamond-pattern bark","opposite branches, unlike most trees"],"use":"Ash splits easily and burns well even when fairly green.","not":"Do not eat or brew any part of a tree you have not identified in person; some trees, like yew and wilted cherry leaves, are deadly.","src":["usfs","usda-nrcs"],"ask":"Tell me about white ash"},{"id":"quaking_aspen","title":"Quaking aspen","domain":"trees","also":["aspen","trembling aspen","popple","Populus tremuloides"],"def":"Quaking aspen is a hardwood with round leaves that tremble on flat stalks and smooth pale green-white bark.","look":["round leaves on flat stalks that tremble, smooth pale green-white bark","grows in clones of many trunks"],"use":"Its bark rubs off a white powder some use as sunblock in a pinch.","not":"Do not eat or brew any part of a tree you have not identified in person; some trees, like yew and wilted cherry leaves, are deadly.","src":["usfs","usda-nrcs"],"ask":"Tell me about quaking aspen"},{"id":"black_cherry","title":"Black cherry","domain":"trees","also":["wild black cherry","Prunus serotina","rum cherry"],"def":"Black cherry is a hardwood with dark, flaky bark like burnt potato chips; its wilted leaves, pits, and bark are poisonous.","look":["dark scaly bark like burnt potato chips, glossy toothed leaves, dark berries","almond smell when a twig is scratched"],"use":"Only the ripe fruit flesh is eaten, never the pits. Leaves, pits and bark contain cyanide compounds. Wilted leaves are dangerous.","not":"Do not eat or brew any part of a tree you have not identified in person; some trees, like yew and wilted cherry leaves, are deadly.","call":"If someone may have eaten it, call Poison Control at 1-800-222-1222, or 911 for trouble breathing, seizures, or collapse.","src":["usfs","usda-nrcs","poison-control"],"ask":"Tell me about black cherry"},{"id":"shagbark_hickory","title":"Shagbark hickory","domain":"trees","also":["hickory","Carya ovata"],"def":"Shagbark hickory is a hardwood whose bark hangs in long loose plates and whose nuts are sweet and edible.","look":["long loose plates of bark curling at the ends","compound leaves","hard nuts in husks","nuts in thick husks that split in four"],"use":"Hickory is top firewood and smoking wood.","not":"Do not eat or brew any part of a tree you have not identified in person; some trees, like yew and wilted cherry leaves, are deadly.","src":["usfs","usda-nrcs"],"ask":"Tell me about shagbark hickory"},{"id":"basswood","title":"Basswood (linden)","domain":"trees","also":["linden","lime tree","Tilia americana","bee tree"],"def":"Basswood is a hardwood with large lopsided heart-shaped leaves and fragrant summer flowers.","look":["large heart-shaped lopsided leaves, nut-like balls hanging from a leafy strip","nutlets hang from a leaf-like strip"],"use":"Its inner bark is one of the best natural cordage fibers.","not":"Do not eat or brew any part of a tree you have not identified in person; some trees, like yew and wilted cherry leaves, are deadly.","src":["usfs","usda-nrcs"],"ask":"Tell me about basswood"},{"id":"black_walnut","title":"Black walnut","domain":"trees","also":["walnut","Juglans nigra"],"def":"Black walnut is a hardwood with long compound leaves and round green-husked nuts whose meat is edible.","look":["compound leaves of many leaflets, dark ridged bark, round green husked nuts","husks stain hands dark brown"],"use":"Its roots release a chemical that stunts many plants beneath it.","not":"Do not eat or brew any part of a tree you have not identified in person; some trees, like yew and wilted cherry leaves, are deadly.","src":["usfs","usda-nrcs"],"ask":"Tell me about black walnut"},{"id":"sassafras","title":"Sassafras","domain":"trees","also":["Sassafras albidum","mitten tree"],"def":"Sassafras is a small tree with three leaf shapes on one tree and a spicy, root-beer smell when crushed.","look":["leaves of three shapes on one tree (oval, mitten, three-lobed)","spicy smell when crushed","green twigs"],"use":"The root contains safrole, which FDA has banned as a food additive, so do not brew it.","not":"Do not eat or brew any part of a tree you have not identified in person; some trees, like yew and wilted cherry leaves, are deadly.","src":["usfs","usda-nrcs"],"ask":"Tell me about sassafras"},{"id":"sycamore","title":"American sycamore","domain":"trees","also":["buttonwood","plane tree","Platanus occidentalis"],"def":"American sycamore is a large streamside tree whose bark flakes off in white, green, and brown patches.","look":["bark flaking off in patches of white and brown, big lobed leaves, ball fruits","white upper limbs visible from far away"],"use":"It almost always grows near water.","not":"Do not eat or brew any part of a tree you have not identified in person; some trees, like yew and wilted cherry leaves, are deadly.","src":["usfs","usda-nrcs"],"ask":"Tell me about american sycamore"},{"id":"witch_hazel","title":"Witch hazel","domain":"trees","also":["Hamamelis","winterbloom","Hamamelis virginiana"],"def":"Witch hazel is an understory shrub with wavy-edged leaves and yellow ribbon flowers in late fall.","look":["wavy-edged uneven leaves, yellow ribbon flowers in late autumn","flowers after the leaves drop"],"use":"Knowing the tree helps you pick firewood, shelter sites, and landmarks.","not":"Do not eat or brew any part of a tree you have not identified in person; some trees, like yew and wilted cherry leaves, are deadly.","src":["usfs","usda-nrcs"],"ask":"Tell me about witch hazel"},{"id":"water_how_much","title":"How much drinking water to plan for","domain":"water","also":["how much water do I need","gallon per day","dehydration signs","water per person"],"def":"Plan on at least one gallon (about 4 liters) of drinking water per person per day for emergencies, and more in heat, with illness, or for children and nursing mothers.","look":["pale yellow urine means you are drinking enough","dark urine, dry mouth, headache, and dizziness mean you need more","very little urine for many hours is dangerous"],"use":"Store at least three days of water for each person at home. In the field, carry what you need for the day plus a way to treat more, and sip steadily.","not":"Do not ration water by waiting until you are thirsty; do not drink too much plain water all at once.","call":"Call 911 for confusion, fainting, or no urination for many hours.","rel":["hydration_basics","water_safe_to_drink"],"src":["ready","cdc"]},{"id":"water_safe_to_drink","title":"Is this water safe to drink?","domain":"water","also":["can I drink from the stream","is creek water safe","clear water safe","wild water"],"def":"Clear water from a stream, lake, or spring can still carry germs, so treat it unless you know it is safe; clear does not mean clean.","look":["clear but untreated water can hold Giardia, Cryptosporidium, bacteria, and viruses","fuel, chemical, or flood water is not made safe by boiling","dead animals, farms, and campsites upstream raise the risk"],"use":"Treat all wild water before drinking: boil, use a filter, or use a disinfectant, and strain cloudy water first. Choose the clearest, moving source.","not":"Do not drink from radiator or boiler water, seawater, or urine, and do not trust clear water on sight.","call":"Get care for severe diarrhea, vomiting, or fever after drinking untreated water.","rel":["boil_water_method","water_filter_use"],"src":["cdc","epa","atp3-50-21"]},{"id":"boil_water_method","title":"How to boil water","domain":"water","also":["boil water to make it safe","rolling boil","how long to boil","boil at altitude"],"def":"Boiling is the most reliable way to kill germs: bring water to a rolling boil for one minute, or three minutes above 6,500 feet (2,000 m).","look":["large bubbles breaking the surface","settle or strain cloudy water first","let it cool in the covered pot"],"use":"Strain cloudy water through a clean cloth or coffee filter, bring it to a rolling boil for 1 minute (3 minutes above 6,500 feet), let it cool, and store it in a clean, covered container.","not":"Do not use boiling to make fuel, chemical, or seawater safe; it will not remove them.","steps":["Strain cloudy water through a clean cloth or coffee filter.","Bring it to a rolling boil.","Hold the boil for 1 minute, or 3 minutes above 6,500 feet.","Cool it covered and pour into a clean container."],"call":"Use a boil-water notice from your health department as the rule when there is one.","rel":["water_bleach_disinfect"],"src":["cdc","epa"]},{"id":"water_bleach_disinfect","title":"Disinfecting water with household bleach","domain":"water","also":["bleach to purify water","drops of bleach per gallon","chlorine bleach water"],"def":"Plain unscented household bleach can disinfect clear water, but it works less well than boiling against Giardia and Cryptosporidium.","look":["8 drops of 6% bleach per gallon (6 drops of 8.25%), double for cloudy water","wait 30 minutes","a slight chlorine smell afterward"],"use":"Strain cloudy water, add the right drops of regular unscented bleach (not scented, color-safe, or with additives) per gallon, stir, and wait 30 minutes. If there is no chlorine smell, repeat once and wait 15 minutes more.","not":"Do not use scented, splash-less, or color-safe bleach. Do not use bleach as your only method when you can boil.","call":"Call your health department if the water source may be contaminated by sewage or chemicals.","rel":["boil_water_method","water_filter_use"],"src":["cdc","epa"]},{"id":"water_filter_use","title":"Portable water filters: what they remove","domain":"water","also":["water filter","straw filter","pump filter","how fine a filter","backpacking filter"],"def":"A portable filter strains out parasites and bacteria; most do not remove viruses or chemicals.","look":["pore size about 1 micron or less stops Giardia and Cryptosporidium","0.3 micron or less also stops most bacteria","a filter rated as a purifier may handle viruses"],"use":"Pre-filter cloudy water through cloth, then run it through the filter, and follow the maker's directions for cleaning. Disinfect or boil afterward if viruses or unknown sources are a concern.","not":"Do not freeze a wet hollow-fiber filter, and do not assume a filter removes chemicals, fuel, or salt.","rel":["water_filter_then_disinfect","water_safe_to_drink"],"src":["cdc","epa"]},{"id":"water_filter_then_disinfect","title":"Filter first, then disinfect","domain":"water","also":["filter and treat","layer treatment","virus protection water"],"def":"Filtering removes parasites and bacteria and clears the water, and a disinfectant afterward handles viruses that pass through.","look":["filter or settle first","then boil, or add bleach or a chlorine dioxide tablet","wait the full contact time"],"use":"When you are in doubt or in a place with viruses of concern, filter first and then disinfect the filtered water. This also saves disinfectant and gives it more reliable contact.","not":"Do not use a disinfectant on very cloudy water without filtering first.","rel":["water_filter_use","water_bleach_disinfect"],"src":["cdc","epa"]},{"id":"water_cloudy_pretreat","title":"Cloudy water: settle or pre-filter","domain":"water","also":["muddy water","silty water","turbid water","clear up cloudy water"],"def":"Cloudy water hides germs from disinfectant and clogs filters, so let it settle and strain it first.","look":["silt or particles in the water","a clean cloth or coffee filter","a settled layer at the bottom"],"use":"Let the water sit until the silt sinks, pour the clear top through a clean cloth or coffee filter, then boil, filter, or disinfect.","not":"Do not skip the pre-filter and just add more disinfectant.","rel":["boil_water_method","water_filter_use"],"src":["cdc","epa"]},{"id":"water_contaminated_no","title":"Water that cannot be made safe in the field","domain":"water","also":["fuel in the water","flood water","chemical spill water","dead animal in stream"],"def":"Water contaminated with fuel, chemicals, sewage, or flood debris cannot be made safe by boiling or bleach, so do not use it to drink.","look":["an oily sheen or fuel smell","flood water with sewage or farm runoff","water near an industrial spill or a dead animal"],"use":"Find another source, use bottled water, or follow your local health department's instructions. Use contaminated water only for flushing or cleaning, not for drinking or washing dishes.","not":"Do not drink it, brush teeth with it, or use it for baby formula.","call":"Call Poison Control at 1-800-222-1222 if someone swallowed it.","rel":["water_safe_to_drink"],"src":["cdc","epa","fema"]},{"id":"water_container_storage","title":"Containers and storing treated water","domain":"water","also":["what to use for a water bottle","store clean water","water jug","hydration bladder"],"def":"Store treated water in clean, food-grade containers with tight lids, away from sun and heat.","look":["food-grade plastic or stainless steel","a lid that seals","a cool, dark place"],"use":"Wash containers with soap and rinse, fill with treated water, label them with the date, and replace commercial water as the package says. In the field, use a pot, a bottle, or a clean bag.","not":"Do not use a container that held chemicals, fuel, or milk.","rel":["water_how_much","boil_water_method"],"src":["cdc","ready"]},{"id":"water_find_new_england","title":"Finding water in New England woods","domain":"water","also":["where to find water in the woods","stream or spring","snow for water","water in Maine"],"def":"In New England, water is usually near: look for streams in valley bottoms, springs, ponds, and melted snow; moving water is better than still.","look":["valley bottoms and seeps where several slopes meet","springs and clear running streams","packed snow and ice, melted first"],"use":"Follow downhill and listen for running water, collect from the clearest moving source, and treat it. Melt snow or ice in a pot; do not eat it raw.","not":"Do not drink from radiators, boilers, seawater, or urine, and do not eat snow to get water because it lowers your body temperature.","region":"Beaver ponds, farm fields, and campsites upstream are common contamination sources in New England; Giardia is widespread in surface water.","rel":["water_safe_to_drink","snow_melt_water"],"src":["atp3-50-21","cdc"]},{"id":"snow_melt_water","title":"Melting snow and ice for water","domain":"water","also":["melt snow","eat snow","drink from snow"],"def":"Melt snow or ice in a pot and treat the water; eating snow lowers body temperature and uses energy.","look":["a pot with a little water in it to start","clean white snow, not yellow or near a road","ice yields more water than fluffy snow"],"use":"Start with a little water in the pot so it doesn't scorch, add snow gradually, and boil it. Melt it with a stove or fire, or in a bag against the body only if needed.","not":"Do not eat large amounts of snow in the cold.","rel":["boil_water_method","water_find_new_england"],"src":["atp3-50-21","cdc"]},{"id":"rain_collect_water","title":"Collecting rain","domain":"water","also":["catch rain water","tarp water catchment","rain barrel"],"def":"Rain is a good source if you collect it in clean containers, and you should treat it if it passed over roofs or leaves.","look":["a tarp funneling water into a clean pot","rain caught directly is cleaner","roof runoff can have debris"],"use":"Set clean containers out, rig a tarp to funnel rain into them, and let the first few minutes of rain wash dust off. Treat the water if it is for drinking.","not":"Do not drink water from a roof treated with chemicals or stored in dirty containers.","rel":["boil_water_method"],"src":["atp3-50-21","epa"]},{"id":"giardia_crypto","title":"Giardia and Cryptosporidium","domain":"water","also":["beaver fever","parasite in water","cryptosporidium","giardia"],"def":"Giardia and Cryptosporidium are tiny parasites in surface water that cause days of diarrhea, cramps, and nausea; boiling or the right filter stops them.","look":["watery diarrhea, gas, cramps, and nausea one to two weeks after drinking","found in streams, lakes, and ponds, even clear ones","chlorine alone works poorly on Cryptosporidium"],"use":"Boil water or use a filter rated for 1 micron or smaller. Wash your hands with soap and clean water before eating.","not":"Do not rely on bleach alone for Cryptosporidium.","call":"Get care for diarrhea that lasts more than a few days, or with fever, blood, or dehydration.","rel":["boil_water_method","vomiting_diarrhea"],"src":["cdc"]},{"id":"water_chemical_tablets","title":"Iodine and chlorine dioxide tablets","domain":"water","also":["water purification tablets","iodine tablets","micropur","aquamira drops"],"def":"Tablets disinfect water when boiling is not possible; follow the label for dose and wait time.","look":["chlorine dioxide tablets kill most germs including Cryptosporidium after the label wait time","iodine tablets are less reliable against Cryptosporidium","taste and color changes"],"use":"Read the label, pre-filter cloudy water, add the tablet, and wait the full time (often 30 minutes to 4 hours for Cryptosporidium).","not":"Do not use iodine for pregnant women, people with thyroid problems, or long-term use.","rel":["water_bleach_disinfect","water_filter_then_disinfect"],"src":["cdc","epa"]},{"id":"water_uv_solar","title":"UV purifiers and solar disinfection","domain":"water","also":["steripen","UV light water","sodis","solar water disinfection"],"def":"UV treatment works only on clear water in a working unit, and solar disinfection needs clear plastic bottles in strong sun for many hours.","look":["clear, not cloudy, water","a charged, working UV unit","clear PET bottles in full sun for 6 hours or two days in cloudy weather"],"use":"Pre-filter, treat with the UV unit as directed, and carry a backup like tablets or a pot. Use solar disinfection only as a last resort.","not":"Do not trust UV in cloudy water or with low batteries.","rel":["water_cloudy_pretreat","water_chemical_tablets"],"src":["cdc","epa"]},{"id":"water_hygiene_scarce","title":"Washing hands, dishes, and wounds when water is scarce","domain":"water","also":["wash hands without water","hand sanitizer","dishes in the field","hygiene when water is short"],"def":"When water is short, use the cleanest water for drinking and wound care, and a little soap and treated water for hands.","look":["a small amount of soap and water for hands","alcohol-based sanitizer when hands are not greasy","dishes washed away from streams"],"use":"Wash hands before eating and after the toilet, use treated water for wounds, and use hand sanitizer if there is no water. Wash dishes well away from streams.","not":"Do not use contaminated water on wounds.","rel":["wound_cleaning","latrine_placement"],"src":["cdc","atp3-50-21"]},{"id":"latrine_placement","title":"Latrine placement away from water","domain":"water","also":["where to go to the bathroom outdoors","cathole","toilet in the woods","poop in the woods"],"def":"Dig a latrine or cathole at least 200 feet (60 m) from water, trails, and camp to keep your drinking water clean.","look":["a hole 6 to 8 inches (15 to 20 cm) deep","200 feet from any stream, pond, or spring","downhill and downstream from camp"],"use":"Dig a small hole, use it, cover it with soil, and wash your hands. Pack out toilet paper if the rules require it.","not":"Do not go near water, and do not use areas near a drainage.","rel":["water_hygiene_scarce"],"src":["atp3-50-21","nps"]},{"id":"formula_unsafe_water","title":"Baby formula when tap water is unsafe","domain":"water","also":["infant formula and boil water","safe water for baby","mix formula"],"def":"Mix infant formula with bottled, boiled-and-cooled, or properly treated water when the tap is unsafe.","look":["a boil-water notice or a flood","bottled water for babies","ready-to-feed formula needs no water"],"use":"Use bottled or boiled water (cooled to room temperature before mixing, per the label), wash bottles with safe water, and use ready-to-feed formula if you can.","not":"Do not use untreated or contaminated water, and do not dilute formula to stretch it.","call":"Call a pediatrician or 911 if a baby is vomiting, lethargic, or not feeding.","rel":["vomiting_diarrhea"],"src":["cdc","fema"]},{"id":"water_no_go_sources","title":"Water sources never to drink","domain":"water","also":["radiator water","urine","seawater","toilet tank"],"def":"Never drink radiator or boiler water, seawater, urine, or water that has fuel or chemicals in it.","look":["antifreeze in radiators","salt in seawater and urine","chemicals in pool or flood water"],"use":"Use another source; if you must use pool water, treat and filter it, and use a toilet tank only if it is clean, not a bowl.","not":"Do not drink seawater or urine; the salt makes you more dehydrated.","call":"Call Poison Control at 1-800-222-1222 if anyone drinks antifreeze or chemical water.","rel":["water_contaminated_no","water_safe_to_drink"],"src":["cdc","atp3-50-21"]},{"id":"well_flood_disinfect","title":"Well disinfection after a flood","domain":"water","also":["flooded well","shock chlorinate a well","well water after flood"],"def":"A flooded well must be tested and disinfected following health-department or EPA directions; do not invent a mix.","look":["flood water over the wellhead","cloudy or odd-tasting water","a pump that was underwater"],"use":"Use bottled or boiled water until the well is tested and cleared. Contact your health department or a certified lab, and follow their disinfection steps.","not":"Do not drink or cook with the water until it is tested.","rel":["water_contaminated_no"],"src":["cdc","epa"]},{"id":"cumulonimbus_cloud","title":"Cumulonimbus (thunderhead)","domain":"weather","also":["thunderhead","thunderstorm cloud","anvil cloud","towering storm cloud"],"def":"A cumulonimbus is a very tall, dense storm cloud with a flat anvil top that produces thunderstorms, lightning, heavy rain, hail, and sometimes tornadoes.","look":["towering cauliflower shape that reaches very high","flat, spreading anvil at the top","dark, flat base with rain, hail, or lightning below"],"use":"Treat it as a lightning and downpour warning. Get off peaks, ridges, and other high ground, leave open ground and water, move to a building or hard-topped vehicle, and expect sudden strong gusts.","not":"Do not wait for rain to start before moving; lightning can strike miles ahead of the rain. Do not shelter under lone trees.","rel":["lightning","thunderstorm_stages","shelf_cloud"],"src":["nws","noaa"]},{"id":"cumulus_cloud","title":"Cumulus clouds","domain":"weather","also":["fair weather clouds","puffy clouds","cotton ball clouds"],"def":"Cumulus are puffy, flat-bottomed clouds with a cotton-ball look that usually mean fair weather unless they grow tall.","look":["distinct, rounded puffs with sharp edges","flat bases","small ones scattered in a blue sky"],"use":"Small, scattered cumulus mean fair weather. If they build taller through the day and darken, watch for afternoon showers or storms.","not":"Do not assume fair weather if they are towering upward fast; that is a thunderstorm in the making.","rel":["cumulonimbus_cloud","stratus_cloud"],"src":["nws","noaa"]},{"id":"stratus_cloud","title":"Stratus clouds and fog","domain":"weather","also":["low gray clouds","overcast low sky","gray blanket cloud","high fog"],"def":"Stratus is a flat, gray, featureless layer of low cloud, like fog that has lifted off the ground.","look":["uniform gray layer with no shape","very low base, sometimes touching hills","drizzle or mist rather than real rain"],"use":"Expect gloomy, damp, cool conditions with little wind and perhaps drizzle. Visibility is poor, so use care navigating.","not":"Do not expect real rain or storms from stratus alone; thicker rain comes from nimbostratus.","rel":["nimbostratus_cloud","fog_types"],"src":["nws","noaa"]},{"id":"nimbostratus_cloud","title":"Nimbostratus","domain":"weather","also":["rain clouds","steady rain cloud","dark gray rain layer"],"def":"Nimbostratus is a thick, dark gray layer that blocks the sun and brings steady rain or snow for hours.","look":["dark, even gray sky with no visible sun","steady, continuous rain or snow","ragged lower scud clouds under it"],"use":"Plan for long, soaking rain: set up shelter, keep gear dry, and avoid low spots and dry washes that can flood.","not":"Do not expect a quick clearing; it usually lasts until the front passes.","rel":["warm_front","flash_flood_risk"],"src":["nws","noaa"]},{"id":"cirrus_cloud","title":"Cirrus clouds","domain":"weather","also":["mares tails","wispy high clouds","feathery clouds","ice crystal clouds"],"def":"Cirrus are thin, wispy, white streaks high in the sky made of ice crystals, and they often come before a change in weather.","look":["thin white hair-like streaks","very high in a blue sky","hooks or tails, sometimes thickening over hours"],"use":"A few mean fair weather. If they thicken and lower into a sheet over a day, a warm front and rain may follow in about 24 hours.","not":"Do not treat a few scattered streaks as a storm warning on their own.","rel":["cirrostratus_halo","warm_front"],"src":["nws","noaa"]},{"id":"cirrostratus_halo","title":"Cirrostratus and halo around the sun or moon","domain":"weather","also":["ring around the moon","halo around the sun","milky sky","sun dog"],"def":"Cirrostratus is a thin, milky veil of high cloud that makes a ring (halo) around the sun or moon, and it often means rain or snow is coming within a day.","look":["bright ring around the sun or moon","thin, milky sheet across the sky","sun or moon still visible through it"],"use":"Expect weather to turn within roughly 12 to 24 hours. Use the time to prepare shelter and gear.","not":"Do not treat it as a guarantee; sometimes the front passes by without rain.","rel":["cirrus_cloud","warm_front"],"src":["nws","noaa"]},{"id":"altocumulus_cloud","title":"Altocumulus (mackerel sky)","domain":"weather","also":["mackerel sky","sheep back clouds","patchy mid-level clouds","castellanus"],"def":"Altocumulus are white or gray patches or rolls of cloud at mid-levels, and in a warm humid morning they can mean afternoon thunderstorms.","look":["rows or patches of rounded cloudlets","mid-level, smaller than cumulus","turrets rising from the tops (castellanus) mean unstable air"],"use":"If you see turrets or they appear on a warm, sticky morning, watch for storms by afternoon.","not":"Do not mistake them for harmless cirrocumulus; check the size and height of the puffs.","rel":["cumulonimbus_cloud","altostratus_cloud"],"src":["nws","noaa"]},{"id":"altostratus_cloud","title":"Altostratus","domain":"weather","also":["watery sun","gray veil","sun looks like through ground glass"],"def":"Altostratus is a gray or blue-gray mid-level sheet through which the sun appears dimly, like looking through frosted glass.","look":["gray sheet with a dim, watery sun","no halo","lowering and thickening over hours"],"use":"It usually thickens ahead of a warm front, so expect steady rain or snow within several hours.","not":"Do not expect sharp shadows or a halo; those point to thinner cirrostratus.","rel":["nimbostratus_cloud","warm_front"],"src":["nws","noaa"]},{"id":"stratocumulus_cloud","title":"Stratocumulus","domain":"weather","also":["low lumpy gray clouds","rolls of low cloud"],"def":"Stratocumulus are low, lumpy gray and white clouds in rolls or patches that cover much of the sky, often with little rain.","look":["rounded masses joined in rows","gray with brighter gaps","low and common after a front"],"use":"Usually dry or light drizzle at most. Conditions often clear toward evening.","not":"Do not expect storms or steady rain from them.","rel":["stratus_cloud","cumulus_cloud"],"src":["nws","noaa"]},{"id":"lenticular_cloud","title":"Lenticular cloud","domain":"weather","also":["UFO cloud","lens shaped cloud","stacked pancake cloud","wave cloud"],"def":"A lenticular is a smooth, lens-shaped cloud that sits over or downwind of mountains where strong winds flow in waves.","look":["smooth lens or stacked-plate shape","stays in one place while air streams through","near mountains with strong wind aloft"],"use":"Treat it as a sign of strong winds aloft and possibly rough air and gusty winds at the summit or downwind. Weather may be changing.","not":"Do not mistake it for a normal cloud that will pass; it will stay put as long as the wind blows.","rel":["wind_shift_signs","mountain_weather"],"src":["nws","noaa"]},{"id":"mammatus_cloud","title":"Mammatus clouds","domain":"weather","also":["pouch clouds","bubbly cloud underside","udder clouds"],"def":"Mammatus are pouch-like bulges that hang from the underside of a cloud, usually a thunderstorm anvil.","look":["lumpy pouches under an anvil","often seen after a storm has passed","dramatic lighting at sunset"],"use":"They mark a strong storm system. Stay alert for severe weather and move to shelter if a storm is still near.","not":"Do not take them as a sign that a tornado is coming; they are not a tornado warning.","rel":["cumulonimbus_cloud","tornado_signs"],"src":["nws","noaa"]},{"id":"shelf_cloud","title":"Shelf cloud and gust front","domain":"weather","also":["arcus cloud","roll cloud","wall of cloud ahead of storm","storm front line"],"def":"A shelf cloud is a low, wedge-shaped wall of cloud on the leading edge of a thunderstorm's cold outflow, with strong straight-line winds right behind it.","look":["long horizontal band with a smooth leading edge","dark, ragged cloud behind it","sudden cool breeze and a wind shift before the rain"],"use":"Take shelter now. Damaging gusts, heavy rain, and hail arrive within minutes of the shelf cloud.","not":"Do not confuse it with a wall cloud or tornado; it does not rotate, but its winds can still cause damage.","rel":["thunderstorm_stages","microburst"],"src":["nws","noaa"]},{"id":"wall_cloud","title":"Wall cloud and funnel cloud","domain":"weather","also":["rotating cloud base","funnel cloud","lowering under a storm","wall cloud tornado"],"def":"A wall cloud is a localized lowering of the rain-free base of a thunderstorm, and rotation there can lead to a tornado; a funnel cloud is a rotating condensation funnel that has not reached the ground.","look":["a lowering that looks like a wall under the storm base","visible rotation or rapid upward motion","a funnel hanging from the base"],"use":"Take shelter immediately in a sturdy building, in an interior room at the lowest level, or in a ditch if there is nothing else. Heed the NWS tornado warning.","not":"Do not try to outrun it by driving across open country, and do not shelter under an overpass.","rel":["tornado_signs","tornado_safety"],"src":["nws","noaa"]},{"id":"contrails_persistent","title":"Contrails as a sign","domain":"weather","also":["vapor trails","airplane trails spreading","long contrails"],"def":"Contrails are the trails of cloud behind high aircraft; if they stay long and spread, the high air is moist and weather may change.","look":["short, quickly vanishing contrails mean dry upper air","long lasting, spreading trails mean moist upper air","trails that merge into thin cirrus sheets"],"use":"Use them as a hint of a coming change, along with other signs like wind shift and falling pressure.","not":"Do not use them alone to forecast; they only suggest moisture aloft.","rel":["cirrus_cloud","barometer_trend"],"src":["nws","noaa","nasa"]},{"id":"fog_types","title":"Fog: radiation, advection, and valley fog","domain":"weather","also":["morning fog","mist","fog in valleys","fog on the water","low visibility"],"def":"Fog is a cloud at ground level; it forms when air cools to its dew point, most often on calm, clear nights or when moist air moves over a cold surface.","look":["radiation or valley fog: calm, clear night, fog in low spots","advection fog: warm moist air moving over cold water or land","fog burns off with morning sun unless it is a thick marine layer"],"use":"Slow down, stay on a known route, use a compass or GPS, and keep a rope or buddy between you if you must move. Expect clearing midday for valley fog.","not":"Do not travel by sight alone in dense fog near cliffs, rivers, or roads.","rel":["dew_point"],"src":["nws","noaa"]},{"id":"thunderstorm_stages","title":"Thunderstorm life cycle","domain":"weather","also":["how a thunderstorm forms","towering cumulus","downdraft","storm stages"],"def":"A thunderstorm grows from rising warm moist air, matures with heavy rain and lightning, and then weakens as downdrafts cut off the updraft.","look":["towering cumulus growing fast","anvil top and rain, hail, and lightning at maturity","cold outflow winds that spread out before the rain"],"use":"Watch for fast-growing towers on warm afternoons and plan to be off ridges early. Storms often last 30 minutes to an hour but can repeat along a line.","not":"Do not assume the danger ends when the rain stops; lightning can strike up to 10 miles away.","rel":["lightning","cumulonimbus_cloud"],"src":["nws","noaa"]},{"id":"flash_to_bang","title":"Flash-to-bang: counting the distance to lightning","domain":"weather","also":["how far away is the lightning","count between flash and thunder","30 30 rule","thunder distance"],"def":"Count the seconds from a lightning flash to its thunder; every five seconds is about one mile (three seconds is about one kilometer).","look":["see the flash, start counting","hear the thunder, stop","divide by five for miles, by three for kilometers"],"use":"If you hear thunder, you are close enough to be struck. Go to safe shelter and wait 30 minutes after the last thunder.","not":"Do not use a long count as a reason to stay out; lightning can strike 10 miles from the storm. Do not count on the same storm cell moving away.","rel":["lightning","cumulonimbus_cloud"],"src":["nws","noaa"]},{"id":"tornado_signs","title":"Tornado warning signs","domain":"weather","also":["how to know a tornado is coming","green sky","debris cloud","roaring sound like a freight train"],"def":"Tornado signs are a dark, greenish sky, large hail, a rotating wall cloud, a loud roar, and a debris cloud at ground level.","look":["dark, green-tinged sky and large hail","rotating, lowering cloud base","loud continuous roar like a freight train","funnel or debris cloud near the ground"],"use":"If a tornado warning is issued or you see these signs, go to shelter now. A tornado watch means conditions are favorable, so stay alert.","not":"Do not wait to see the funnel, and do not open windows. Rain wrapped tornadoes can be hidden.","rel":["tornado_safety","wall_cloud"],"src":["nws","fema","noaa"]},{"id":"tornado_safety","title":"Tornado safety","domain":"weather","also":["what to do in a tornado","tornado shelter","basement during a tornado","caught outside in a tornado"],"def":"In a tornado, get to the lowest floor of a sturdy building, in an interior room away from windows, and protect your head and neck.","look":["interior room, closet, or bathroom on the lowest floor","basement or storm shelter is best","mobile homes and vehicles are not safe"],"use":"Cover yourself with mattresses or blankets and wear a helmet if you have one. If caught outside with no shelter, lie flat in a ditch or low spot and cover your head.","not":"Do not shelter in a mobile home, do not stay in a vehicle if a sturdy building is close, and do not hide under an overpass.","rel":["tornado_signs","efscale_tornado"],"src":["nws","fema","noaa"]},{"id":"efscale_tornado","title":"Enhanced Fujita (EF) scale","domain":"weather","also":["tornado rating","EF5","how strong is a tornado"],"def":"The EF scale rates a tornado from EF0 to EF5 by the damage it causes and the wind speeds estimated from it.","look":["EF0: 65 to 85 mph, light damage","EF2: 111 to 135 mph, considerable damage","EF4: 166 to 200 mph, devastating damage","EF5: over 200 mph, incredible damage"],"use":"Use it to understand reports after a tornado. The rating is assigned after the damage survey, not in advance.","not":"Do not read a rating as a measure of the size or width of the tornado alone.","rel":["tornado_safety","tornado_signs"],"src":["nws","noaa"]},{"id":"hurricane_categories","title":"Hurricane categories (Saffir-Simpson)","domain":"weather","also":["category 3 hurricane","how strong is a hurricane","typhoon","cyclone wind speeds"],"def":"The Saffir-Simpson scale rates hurricanes from category 1 to 5 by sustained wind speed, but flooding and storm surge cause most deaths.","look":["category 1: 74 to 95 mph","category 3: 111 to 129 mph, a major hurricane","category 5: 157 mph or higher"],"use":"Prepare early by category and by the local storm surge and rainfall forecasts. Follow evacuation orders for surge zones.","not":"Do not judge your risk from the category alone. A weaker storm can flood a large area.","rel":["storm_surge","hurricane_safety"],"src":["nws","noaa","fema"]},{"id":"storm_surge","title":"Storm surge","domain":"weather","also":["hurricane flooding from the sea","wall of water","coastal flooding"],"def":"Storm surge is the rise in sea level pushed ashore by a hurricane's winds, and it is the biggest killer in hurricanes.","look":["water rising far above normal high tide","strongest to the right of the storm's track in the north hemisphere","flooding miles inland on low coasts"],"use":"Leave when told to evacuate a surge zone, and go inland or uphill. Plan the route before the storm.","not":"Do not stay behind in a surge zone, and do not drive into flooded roads.","rel":["hurricane_categories","flash_flood_risk"],"src":["nws","noaa","fema"]},{"id":"hurricane_safety","title":"Hurricane safety","domain":"weather","also":["hurricane preparedness","what to do in a hurricane","tropical storm prep"],"def":"Hurricane safety means knowing your evacuation zone, leaving early if told to, and sheltering in a safe interior room if you stay.","look":["know your zone and route","supplies for several days: water, food, medicine, radio, power bank","windows covered and outside objects secured"],"use":"Follow official evacuation orders, fill gas, and keep a battery radio. During the storm stay inside, away from windows, in an interior room on a lower floor, but above any flood or surge level.","not":"Do not go out in the eye, and do not use candles; use flashlights.","rel":["storm_surge","power_out_safety"],"src":["nws","noaa","fema"]},{"id":"watch_vs_warning","title":"Watch, warning, and advisory","domain":"weather","also":["difference between a watch and a warning","tornado watch","flood warning","weather alert meaning"],"def":"A watch means conditions are favorable for the hazard; a warning means it is happening or about to happen; an advisory means it will be a nuisance.","look":["watch: be prepared","warning: take action now","advisory: be careful"],"use":"When a warning is issued for your location, act at once. When a watch is issued, review your plan and keep a radio on.","not":"Do not wait for a warning to prepare when a watch is in effect.","rel":["noaa_weather_radio","tornado_safety"],"src":["nws","noaa"]},{"id":"noaa_weather_radio","title":"NOAA Weather Radio","domain":"weather","also":["weather radio","same alert radio","emergency alert radio"],"def":"NOAA Weather Radio broadcasts National Weather Service forecasts and alerts around the clock on seven VHF frequencies.","look":["frequencies between 162.400 and 162.550 MHz","a tone alert and SAME code for your county","battery or hand crank radios work in outages"],"use":"Keep a weather radio with fresh batteries, set to your county's SAME code, as a way to get warnings when cell service and power are out.","not":"Do not rely only on phone alerts; towers and batteries can fail.","rel":["watch_vs_warning","power_out_safety"],"src":["nws","noaa"]},{"id":"blizzard_safety","title":"Blizzard and winter storm safety","domain":"weather","also":["whiteout","heavy snow storm","stuck in a snowstorm","winter storm"],"def":"A blizzard is a storm with sustained winds or gusts of 35 mph or more and low visibility from falling or blowing snow for at least three hours.","look":["falling or blowing snow with very low visibility","strong winds and drifting","dangerous wind chills"],"use":"Stay inside, stay put in a vehicle if stranded (run the engine only briefly with the tailpipe clear), and keep warm and hydrated. Use layers, a hat, and bright markers.","not":"Do not leave a stranded car to walk in a whiteout unless safety is in sight, and do not let the tailpipe get blocked by snow.","rel":["wind_chill","carbon_monoxide_poisoning"],"src":["nws","fema","cdc"]},{"id":"ice_storm_freezing_rain","title":"Freezing rain and ice storms","domain":"weather","also":["glaze ice","icy roads","sleet versus freezing rain","ice on power lines"],"def":"Freezing rain falls as liquid and freezes on contact, coating everything with ice; it is far more damaging than sleet.","look":["glazed trees, wires, and roads","sleet bounces and rattles, freezing rain coats and sticks","limbs and lines breaking under the weight"],"use":"Stay off roads, stay clear of trees and power lines, and prepare for outages. Keep warm and do not use generators indoors.","not":"Do not walk or drive on a glazed surface, and do not go near downed lines.","rel":["power_out_safety","carbon_monoxide_poisoning"],"src":["nws","fema"]},{"id":"wind_chill","title":"Wind chill","domain":"weather","also":["feels like temperature","cold wind","frostbite time"],"def":"Wind chill is how cold the air feels on bare skin because wind carries away body heat; it affects people and animals, not objects.","look":["a stronger wind makes the same temperature feel colder","at around minus 20 F (minus 29 C) wind chill, frostbite can occur in about 30 minutes","at minus 40 and lower it is much faster"],"use":"Dress for the wind chill: windproof outer layer, covered skin, and warm insulation, and check for frostbite on exposed skin.","not":"Do not think the wind chill lowers the actual air temperature or freezes water faster.","rel":["frostbite_warming","hypothermia_stages"],"src":["nws","noaa","cdc"]},{"id":"heat_index","title":"Heat index","domain":"weather","also":["feels like in the heat","humid and hot","heat advisory"],"def":"The heat index combines air temperature and humidity to show how hot it really feels, because sweat cannot cool you when the air is humid.","look":["high humidity makes it feel hotter","heat index above 103 F (39 C) is dangerous","full sun can add up to 15 F"],"use":"Do hard work in the early morning or evening, rest in the shade, and drink water. Check on older people, children, and pets.","not":"Do not rely on the air temperature alone, and do not leave anyone in a parked car.","rel":["heat_stroke_signs","hydration_basics"],"src":["nws","cdc"]},{"id":"dew_point","title":"Dew point and humidity","domain":"weather","also":["dewpoint","why is it sticky","dew on the grass","fog forms when"],"def":"The dew point is the temperature at which air becomes saturated and dew or fog forms; a higher dew point means muggier air.","look":["dew point under 10 C (50 F): dry, comfortable","above 18 C (65 F): sticky","air temperature falling toward the dew point means dew or fog"],"use":"If the night temperature will fall to the dew point, expect dew or fog and condensation on gear. Put gear in a tent or bag to keep it dry.","not":"Do not confuse dew point with relative humidity; the dew point tells you how much moisture is in the air.","rel":["fog_types"],"src":["nws","noaa"]},{"id":"barometer_trend","title":"Reading the barometer trend","domain":"weather","also":["falling pressure","rising pressure","barometer","altimeter weather change","pressure drop"],"def":"A barometer measures air pressure; how it changes over a few hours tells more than the number itself.","look":["falling slowly: clouds and weather deteriorating","falling fast: a storm is near","rising: clearing and drier air","steady: little change"],"use":"Note the pressure every few hours. A fast fall, such as 3 hPa or more in three hours, calls for preparing for rough weather. Watch altimeter drift as a pressure change.","not":"Do not trust a single reading; use the trend. Do not mistake pressure change from altitude for weather.","rel":["wind_shift_signs","cold_front"],"src":["nws","noaa"]},{"id":"cold_front","title":"Cold front","domain":"weather","also":["front passing","storm line","temperature drop and wind shift","squall line"],"def":"A cold front is the leading edge of a cooler air mass that pushes under warmer air, causing a narrow band of storms, a wind shift, and a drop in temperature.","look":["a line of towering clouds and showers or storms","wind shifts to the west or northwest in the northern hemisphere","pressure falls then rises and temperature drops sharply"],"use":"Expect a brief, sometimes severe band of weather followed by clearing and cooler, drier air. Secure camp before it arrives.","not":"Do not expect a long soak; the front is usually fast, though it can be fierce.","rel":["warm_front","wind_shift_signs"],"src":["nws","noaa"]},{"id":"warm_front","title":"Warm front","domain":"weather","also":["slow moving rain","thickening clouds","steady rain ahead of warm air"],"def":"A warm front is where warm air slides over cooler air, bringing a long period of thickening clouds and steady rain or snow, then milder weather.","look":["cirrus, then cirrostratus, then altostratus, then nimbostratus","pressure falls steadily","winds back to the south or southeast before the front"],"use":"Expect a day or so of build-up, then hours of steady precipitation and warmer, muggier air after it passes.","not":"Do not expect sharp storms; the weather is usually steady rather than violent.","rel":["cold_front","cirrostratus_halo"],"src":["nws","noaa"]},{"id":"wind_shift_signs","title":"Wind shifts and Buys Ballot's law","domain":"weather","also":["wind changed direction","wind backing","which way is the low pressure","how to find the storm"],"def":"Wind shifts show a passing front: in the northern hemisphere, stand with your back to the wind and the low pressure is on your left.","look":["wind backing (counterclockwise) with falling pressure ahead of a low","sudden shift to the northwest with a cold front","calm followed by gusts"],"use":"Use wind direction with cloud and pressure changes to judge where the weather is coming from, and plan for a front when the wind swings.","not":"Do not use the rule in the southern hemisphere without reversing it, and do not use it for local mountain winds.","rel":["barometer_trend","cold_front"],"src":["nws","noaa"]},{"id":"beaufort_scale","title":"Beaufort wind scale","domain":"weather","also":["wind force","gale","how strong is the wind","wind speed words"],"def":"The Beaufort scale describes wind force from 0 (calm) to 12 (hurricane) using what you can see.","look":["force 4: moderate breeze, dust and small branches move (11-16 knots)","force 6: strong breeze, large branches sway, umbrellas hard to use (22-27 knots)","force 8: gale, twigs break off trees, walking is hard (34-40 knots)","force 12: hurricane force, 64 knots or more"],"use":"Use it to judge conditions and decide to stay off the water, ridgelines, and exposed trails at force 6 and above.","not":"Do not take the word choice as an exact speed; it is an observed estimate.","rel":["wind_shift_signs","mountain_weather"],"src":["nws","noaa"]},{"id":"mountain_weather","title":"Mountain weather","domain":"weather","also":["weather in the mountains","storms on peaks","summit weather","afternoon thunderstorms"],"def":"Mountain weather changes fast: temperatures fall with height, winds strengthen, and storms often build by early afternoon.","look":["temperature drops about 6.5 C per 1,000 m (3.5 F per 1,000 ft)","afternoon cumulus towers in summer","strong winds on exposed ridges and cols"],"use":"Start early, be off summits and ridges by noon, and turn back when clouds build. Carry rain and warm layers even on fair days.","not":"Do not push on to the summit when storms are building, and do not assume the weather in the valley matches the summit.","rel":["cumulonimbus_cloud","lenticular_cloud"],"src":["nps","nws"]},{"id":"microburst","title":"Microburst and downburst","domain":"weather","also":["straight-line winds","sudden gust","storm winds knocked trees down"],"def":"A microburst is a small, intense downdraft from a thunderstorm that spreads out at the ground and can knock down trees in one direction.","look":["sudden strong wind at the leading edge of a storm","dust or rain streaking down","trees down in a one-directional pattern afterward"],"use":"Move away from trees and into a sturdy shelter at the first sign of a strong, sudden gust ahead of a storm.","not":"Do not camp under tall dead trees or rely on a tent in a thunderstorm.","rel":["shelf_cloud","thunderstorm_stages"],"src":["nws","noaa"]},{"id":"flash_flood_risk","title":"Flash flood risk","domain":"weather","also":["flood watch","rising creek","dry wash flood","slot canyon flood","dry gully","arroyo","dry wash","desert wash"],"def":"A flash flood is a rapid rise of water, often from storms miles upstream, and it can reach you under a clear sky.","look":["heavy rain upstream, rising and muddy creeks","a rumbling roar in a canyon, or debris in the water","low-water crossings and dry washes"],"use":"Move to high ground at once, avoid canyons and washes in storm season, and never drive or walk through floodwater. Turn around, don't drown.","not":"Do not cross moving water. As little as 6 inches (15 cm) can knock you down and about a foot (30 cm) can float a car.","rel":[],"src":["nws","fema","noaa"]},{"id":"wildfire_smoke_aqi","title":"Wildfire smoke and air quality","domain":"weather","also":["smoky air","air quality index","AQI","fire smoke","N95 for smoke"],"def":"Wildfire smoke contains fine particles that can harm the lungs and heart; the air quality index (AQI) shows when to limit time outside.","look":["AQI above 100 is unhealthy for sensitive groups","above 150 is unhealthy for all","haze, ash, and a smell of smoke"],"use":"Stay indoors with windows closed, run a HEPA filter, and use a well-fitted N95 respirator outside if you must. Limit exertion.","not":"Do not rely on a cloth or paper mask for smoke, and do not exercise hard outdoors on smoky days.","rel":["wildfire_evacuation","smoke_inhalation"],"src":["epa","cdc","usfs"]},{"id":"wildfire_evacuation","title":"Wildfire evacuation","domain":"weather","also":["fire is coming","wildfire go bag","leave before the fire","fire evacuation zone"],"def":"For a wildfire, leave early when told to or when smoke and flames are near; waiting is the biggest mistake.","look":["official evacuation order or warning","smoke, ember showers, and a wind shift toward you","roads clogging up"],"use":"Take people, pets, medicines, papers, and a go bag, close windows and doors, and follow known evacuation routes. Tell someone where you are going.","not":"Do not wait for flames to be in view, and do not try to defend a home against a major fire if told to leave.","rel":["wildfire_smoke_aqi"],"src":["usfs","fema","nws"]},{"id":"dust_storm_haboob","title":"Dust storm (haboob)","domain":"weather","also":["dust wall","sandstorm","blowing dust"],"def":"A haboob is a wall of dust pushed ahead of a thunderstorm's outflow, dropping visibility to near zero within seconds.","look":["a towering brown wall approaching","sudden strong gusts and a drop in visibility","dry air and dust over deserts"],"use":"Pull off the road as far as you can, turn off lights, set the parking brake, and keep your foot off the brake pedal. Cover your nose and mouth.","not":"Do not keep driving in a dust storm or leave lights on in a parked vehicle; others may follow them.","rel":["microburst","shelf_cloud"],"src":["nws","noaa"]},{"id":"temperature_inversion","title":"Temperature inversion and cold air pooling","domain":"weather","also":["cold in the valley at night","frost hollows","smoke lies flat","inversion"],"def":"On calm clear nights, cold air sinks and pools in valleys while the slopes above stay warmer; this is a temperature inversion.","look":["smoke or fog layers lie flat","valley floors much colder than the slopes","still, clear night"],"use":"Camp on the slope or bench, not the valley floor. Frost and fog form in the low spots first.","not":"Do not pitch camp in the lowest spot to hide from wind; it will be the coldest.","rel":["fog_types"],"src":["nws","noaa"]},{"id":"weather_folk_signs","title":"Folk weather signs: what holds up","domain":"weather","also":["red sky at night","cows lying down","birds flying low","weather sayings","ants before rain"],"def":"Some old sayings work because they match real changes in air pressure and moisture; others are myths.","look":["red sky at night, shepherd's delight: often works in mid-latitudes where weather moves west to east","a ring around the moon: thin high cloud ahead of a front","smoke that hangs low or rises slowly: low pressure and humid air","swallows and bats flying low: insects stay low in humid air"],"use":"Treat folk signs as clues to combine with cloud types, wind shift, and pressure. If several agree, expect a change.","not":"Do not trust a single saying, and do not rely on animal behavior as the only forecast.","rel":["barometer_trend","cirrostratus_halo"],"src":["nws","noaa"]},{"id":"lightning_myths","title":"Lightning myths","domain":"weather","also":["does lightning strike twice","rubber tires protect","if the sky is clear lightning cannot hit","bolt from the blue"],"def":"Lightning can strike the same place many times, can reach 10 miles from a storm, and rubber tires do not protect you; a hard-topped metal vehicle does.","look":["bolts from the blue strike under clear skies near a storm","tall isolated objects are struck repeatedly","a car protects because of its metal body, not its tires"],"use":"When thunder is heard, go inside a substantial building or a hard-topped vehicle and wait 30 minutes after the last thunder.","not":"Do not shelter under a tree, in a tent, in a shed, or in an open-sided shelter. Do not stay on the water.","rel":["lightning","flash_to_bang"],"src":["nws","noaa","cdc"]},{"id":"power_out_safety","title":"Power outage basics in a storm","domain":"weather","also":["lights are out","storm knocked out power","candles safety","fridge during outage"],"def":"In a storm outage, keep warm, use flashlights, keep fridge and freezer doors closed, and run generators outside, far from the house.","look":["flashlights and battery lantern, not candles","closed fridge keeps food safe about four hours, a full freezer about 48 hours","a battery radio for alerts"],"use":"Use dry ice or ice for the fridge, and eat perishables first. Unplug sensitive electronics, and leave one light on to know when power returns.","not":"Do not use a gas oven or grill for heat, and do not run a generator in a garage or near a window.","rel":["carbon_monoxide_poisoning"],"src":["fema","cdc","usda-fsis"]},{"id":"weather_trend_reading","title":"What is the weather trend?","domain":"weather","also":["weather trend","is the weather getting worse","will it rain","pressure trend","barometer says","forecast for today"],"def":"The weather trend is the direction air pressure and the sky are moving over the last few hours, read from this phone's barometer together with the saved forecast and how old it is.","look":["pressure falling 1 hPa or more per hour: weather is worsening, often rain or wind","pressure steady: no big change soon","pressure rising: clearing and drier air","the age of the saved forecast and any alert's expiry time"],"use":"Check the pressure trend and the saved forecast age first, then look at the sky and wind. Prepare shelter and gear if the pressure is falling and clouds are thickening. Use the NOAA Weather Radio or a fresh forecast whenever you have signal.","not":"A barometer trend is a clue, not a forecast, and a saved forecast more than about 6 hours old may be stale.","call":"If a warning is in effect for your area, follow it first; call 911 in an emergency.","rel":["barometer_trend","forecast_staleness"],"src":["nws","noaa"]},{"id":"forecast_staleness","title":"How old is the saved forecast or alert?","domain":"weather","also":["is the forecast out of date","stale forecast","when was the alert issued","alert expires"],"def":"A saved forecast or alert is a snapshot; it gets less reliable with age, and every NWS alert carries its own expiry time.","look":["the issue time on the forecast","the 'until' or expiry time on an alert","weather that no longer matches what you see"],"use":"Treat a forecast over about 6 hours old as aging and one over a day old as stale. Refresh when you have signal, and trust what the sky and your barometer are doing over an old forecast.","not":"Do not assume an alert is still in effect after its expiry time, or that no alert means no danger.","call":"If conditions look dangerous and you cannot refresh, act on what you see: seek shelter.","rel":["weather_trend_reading","noaa_weather_radio"],"src":["nws"]},{"id":"hypothermia_mild_weather","title":"Hypothermia in mild but wet weather","domain":"weather","also":["cold and wet","hypothermia at 50 degrees","rain and wind chill","cold drizzle"],"def":"Hypothermia can happen well above freezing: cool air plus rain, wind, and wet clothes steals body heat fast.","look":["air temperatures from 30 to 50 F (minus 1 to 10 C) with rain or wind","shivering, clumsiness, and mumbling","wet cotton clothing and no wind block"],"use":"Put on a waterproof shell and a hat, swap wet layers for dry ones, eat and drink, and get out of the wind. Stop and warm up at the first shivering.","not":"Do not trust a mild number on the thermometer, and do not wear wet cotton.","call":"Call 911 if shivering stops or the person is confused or drowsy.","rel":["hypothermia_stages","clothing_layers"],"src":["cdc","nws"]},{"id":"fog_hunting_visibility","title":"Fog and low visibility on a hunt or hike","domain":"weather","also":["foggy morning hunt","can't see in the fog","low light and mist"],"def":"Fog cuts visibility, hides landmarks, and can make a known place unfamiliar; it also muffles sound.","look":["valley fog at dawn on calm clear mornings","visibility dropping below a few hundred feet","damp clothing and falling temperature"],"use":"Stay on a known route, use a compass or GPS, and keep track of the time. If you lose your bearings, stop, and wait for the fog to lift; mark your position on your phone. Make noise with a whistle if you need help.","not":"Do not take shots you cannot clearly identify and see beyond, and do not walk near cliffs, water, or roads by sight alone.","rel":["fog_types"],"src":["nws","atp3-50-21"]},{"id":"thunderstorm_hunting_water","title":"A thunderstorm starts while you are hunting or on the water","domain":"weather","also":["storm while hunting","lightning in the woods","storm on the boat","lightning on the lake"],"def":"If thunder is heard, get to a vehicle, a building, or low ground at once, and get off the water, ridges, and open fields.","look":["thunder or a flash within 30 seconds","dark towers and a sudden cool breeze","hair standing on end or buzzing metal"],"use":"Walk to a vehicle or building now. If none is near, go to a low spot away from lone trees, water, and metal fences, and spread out groups by 50 feet. On water, head for shore immediately. Wait 30 minutes after the last thunder.","not":"Do not shelter under a lone tree, in a pop-up blind, or on a ridge, and do not leave a firearm propped on a tree.","call":"Call 911 for a lightning strike; start CPR if the person is not breathing.","rel":["lightning","flash_to_bang"],"src":["nws","noaa"]},{"id":"tree_ice_branches","title":"Ice, branches, and downed lines after a storm","domain":"weather","also":["tree limb down","power line on the ground","ice storm cleanup","widowmaker after a storm"],"def":"After ice or wind storms, ice-loaded limbs and downed lines are the main hazards, and any line on the ground should be treated as live.","look":["ice-coated or cracked limbs overhead","wires on the ground or hanging in trees","a vehicle touching a line"],"use":"Stay at least 10 meters (30 feet) from any downed line and call the utility or 911. Stay out from under heavily loaded trees, and wait for daylight to clear debris. If a line falls on your car, stay in the car and wait for help.","not":"Do not touch anything in contact with a line, and do not drive over a downed wire. If you must leave a car on a live wire, jump clear with both feet together and shuffle away.","call":"Call 911 and the utility for any downed power line.","rel":["power_out_safety","ice_storm_freezing_rain"],"src":["fema","nws","cpsc"]},{"id":"red_flag_fire_weather","title":"Red flag warning and fire weather","domain":"weather","also":["red flag warning","fire weather watch","dry windy day","drought and fire risk"],"def":"A red flag warning means warm temperatures, very low humidity, and strong winds are creating critical fire conditions.","look":["low humidity, dry vegetation, and gusty winds","a burn ban or an NWS red flag warning","smoke or a fire nearby"],"use":"Do not burn outdoors, keep vehicles off dry grass, and have an escape route ready. Check local burn bans. Put out any fire completely.","not":"Do not drag chains, park on tall dry grass, or use fireworks and open flames on a red flag day.","call":"Call 911 at the first sign of a wildfire.","rel":["wildfire_evacuation","fire_legal_ban"],"src":["nws","usfs","fema"]},{"id":"rain_on_snow_flood","title":"Rain on snow and ice jam flooding","domain":"weather","also":["thaw flooding","ice jam","snowmelt flood","spring flood"],"def":"Rain on deep snow plus warm air can melt it fast and send a surge of water into streams, and ice jams can back up rivers.","look":["warm rain on a deep snowpack","rapidly rising streams and cracking river ice","water pooling at culverts and low crossings"],"use":"Stay away from rivers and stream banks, move to higher ground if water rises, and avoid crossing flooded roads. Move vehicles and valuables from low spots early.","not":"Do not walk or drive through floodwater or on river ice during a thaw.","call":"Call 911 if trapped by water; stay on high ground.","rel":["flash_flood_risk"],"src":["nws","fema"]},{"id":"small_craft_marine_forecast","title":"Marine and small-craft forecast","domain":"weather","also":["small craft advisory","coastal waters forecast","boating weather","choppy seas"],"def":"A small craft advisory warns that winds or seas are hazardous for small boats, and a marine forecast gives wind, seas, and visibility for coastal waters.","look":["winds around 20 to 33 knots and rough seas","fog and reduced visibility","gale or storm warnings for larger systems"],"use":"Check the marine forecast before you go and again before you leave the dock. Stay in port when an advisory is posted, wear a life jacket, and know where to land.","not":"Do not rely on a calm morning; coastal weather can change fast.","region":"On the Maine and Rhode Island coasts, fog and cold water are constant risks even in summer.","call":"Call the Coast Guard on VHF channel 16 or 911 in an emergency on the water.","rel":["cold_water_shock","weather_trend_reading"],"src":["nws","noaa"]},{"id":"dew_frost_overnight","title":"Dew, frost, and overnight lows","domain":"weather","also":["will it freeze tonight","frost forecast","ground frost","heavy dew"],"def":"Dew forms when surfaces cool to the dew point, and frost forms when they cool below freezing on a clear, calm night.","look":["clear skies and calm winds cool the ground fastest","wet grass or a white coating at dawn","low spots and valleys are coldest"],"use":"Expect a frost when the forecast low is near 36 F (2 C) on a clear, calm night. Cover gear, bring water filters and batteries inside, and sleep above the cold air in the valley.","not":"Do not leave a wet water filter out to freeze.","rel":["temperature_inversion","dew_point"],"src":["nws","noaa"]},{"id":"whiteout_snow","title":"Whiteout","domain":"weather","also":["can't see in the snow","blowing snow","snow squall","white out"],"def":"A whiteout is a loss of depth and horizon in blowing snow or flat light, and it makes it easy to lose direction or walk off an edge.","look":["no visible horizon or shadows","blowing snow and low visibility","sudden snow squalls"],"use":"Stop moving unless you are on a sure handrail such as a fence or a wall. Put on warm layers, take shelter, and wait for visibility to improve. Use a compass if you must move.","not":"Do not walk on without a reference, and do not leave a vehicle in a whiteout without a plan.","call":"Call 911 if stranded; stay with the vehicle.","rel":["blizzard_safety"],"src":["nws","atp3-50-21"]},{"id":"weather_signals_combined","title":"Using pressure, wind, and clouds together","domain":"weather","also":["how do I forecast the weather myself","signs of a storm coming","weather clues","predict rain"],"def":"A better local forecast comes from combining pressure trend, wind shift, cloud change, and temperature rather than relying on any one sign.","look":["falling pressure plus thickening high cloud: wet weather in a day","backing wind plus low, dark cloud: worsening","rising pressure plus a northwest wind and clearing sky: improving","three or more signs agreeing is strong"],"use":"Write down pressure, wind, and sky every few hours. If two or more clues point to worsening weather, prepare for it. Refresh with the NWS forecast whenever you have signal.","not":"Do not trust a single sign, and do not ignore an official warning for a hunch.","rel":["barometer_trend","wind_shift_signs"],"src":["nws","noaa","jetstream"]},{"id":"tropical_remnants_coastal_flooding","title":"Tropical storm remnants and coastal flooding","domain":"weather","also":["hurricane remnants","nor'easter","coastal flood","storm tide"],"def":"Remnants of tropical storms and nor'easters bring heavy rain, wind, and high tides that flood coasts and rivers well inland.","look":["tropical storm or nor'easter in the forecast","heavy rain bands and rising rivers","high tide plus onshore wind causing coastal flooding"],"use":"Follow evacuation orders, move to higher ground, secure outside items, and avoid flooded roads. Have supplies for several days.","not":"Do not drive through floodwater, and do not assume a weakened storm is harmless.","region":"The Rhode Island and Maine coasts are exposed to storm surge and coastal flooding from hurricanes and nor'easters.","call":"Call 911 if trapped by water.","rel":["storm_surge","hurricane_safety"],"src":["nws","fema"]}];
